SELECT 'moj-all-verified-judgments-review-002-chunk-013' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"591faeaf-4942-58ec-a866-be42d44b7820","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب فسخ النكاح بعد الدخول لسوء العشرة ،وتعاطي والكره -قرر احلكمان املختاران من قبل الزوجني التفريق املخدرات ، دون عوض -استعداد الزوجة بذل كامل املهر املسلم ،والتنازل عن املؤخر -عدم موافقة الزوج -فسخ النكاح على كامل العوض .","document_number":"33450924","case_number":"33199867","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/10","year":"1434","subject":"فسخ نكاح -طلب فسخ النكاح بعد الدخول لسوء العشرة ،وتعاطي والكره -قرر احلكمان املختاران من قبل الزوجني التفريق املخدرات ، دون عوض -استعداد الزوجة بذل كامل املهر املسلم ،والتنازل عن املؤخر -عدم موافقة الزوج -فسخ النكاح على كامل العوض .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/10 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33450924 :‬‬\n                          ‫َر ْق ُم الدعوى‪33199867 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3413731‬تاريخه‪1434/1/17:‬هـ‬\n\n\n       ‫فســخ نــكاح ‪ -‬طلــب فســخ النــكاح بعــد الدخــول لســوء العشــرة ‪ ،‬وتعاطي‬\n       ‫والكــره ‪ -‬قــرر احلكمــان املختــاران مــن قبل الزوجني التفريق‬  ‫املخــدرات ‪ُ ،‬‬\n       ‫دون عــوض ‪ -‬اســتعداد الزوجــة بــذل كامــل املهــر املســلم ‪ ،‬والتنــازل عــن‬\n            ‫املؤخــر ‪ -‬عــدم موافقــة الــزوج ‪ -‬فســخ النــكاح علــى كامــل العوض ‪.‬‬\n\n\n\n\n       ‫‪ .1‬قولــه تعالــى‪« :‬وإن خفتــم شــقاق بينهمــا فابعثــوا حكم ـ ًا مــن أهلــه‬\n                        ‫وحكم ـ ًا مــن أهلهــا إن يريــدا إصالح ـ ًا يوفــق اهلل بينهمــا»‬\n       ‫‪ .2‬مــا رواه البخــاري عــن ابــن عبــاس رضــي اهلل عنهمــا قــال‪ :‬جــاءت امــرأة‬\n       ‫ثابــت بــن قيــس بــن شــماس إلــى النبــي صلــى اهلل عليــه وســلم فقالــت‪:‬‬\n       ‫يــا رســول اهلل مــا أنقــم علــى ثابــت يف ديــن وال خلــق إال أنــي أخــاف‬\n       ‫الكفــر يف اإلســام‪ ،‬فقــال رســول اهلل صلــى اهلل عليــه وســلم‪ :‬أترديــن‬\n                        ‫عليــه حديقتــه قالــت‪ :‬نعــم فــردت عليــه فأمــره ففارقهــا»‪.‬‬\n                                  ‫‪ .3‬قوله صلى اهلل عليه وسلم‪« :‬ال ضرر وال ضرار»‬\n       ‫‪ .4‬مــا رواه النســائي وعبــد الــرزاق عــن ابــن عبــاس رضــي اهلل عنهمــا قــال‪:‬‬\n       ‫بعثــت أنــا ومعاويــة حكمــن قــال معمــر‪ :‬بلغنــي أن عثمــان بعثهمــا وقــال‬\n                         ‫إن رأيتمــا أن جتمعــا جمعتمــا وإن رأيتمــا أن تفرقــا ففرقــا»‬\n       ‫‪ .5‬مــا رواه الــدار قطنــي والنســائي والشــافعي والبيهقــي عــن محمــد بــن‬\n       ‫ســيرين عــن عبيــدة قــال‪« :‬جــاء رجــل وامــرأة إلــى علــي مــع كل واحــد‬\n       ‫منهمــا فئــام مــن النــاس فأمرهــم فبعثــوا حكم ـ ًا مــن أهلــه وحكم ـ ًا مــن‬\n‫‪307‬‬\n\f‫أهلهــا وقــال للحكمــن هــل تدريــان مــا عليكمــا؟ عليكمــا إن رأيتمــا إن‬\n‫جتمعــا فاجمعــا وإن رأيتمــا أن تفرقــا فرقتمــا فقالــت املــرأة‪ :‬رضيــت‬\n‫بكتــاب اهلل مبــا علـ ّـي فيــه ولــي ‪ ،‬وقــال الــزوج‪ :‬أمــا الفرقــة فــا‪ ،‬فقــال‬\n‫علــي‪ :‬كذبــت واهلل ال تبــرح حتــى تقــر مثــل الــذي أقــرت بــه» قــال ابــن‬\n                                                      ‫حجــر‪ :‬إســناده صحيــح‪.‬‬\n‫‪ .6‬مــا أخرجــه الطبــري يف تفســيره‪ :‬عــن ابــن عبــاس رضــي اهلل عنهمــا‬\n‫يف احلكمــن أنــه قــال‪ :‬فــإن اجتمــع أمرهمــا علــى أن يفرقــا أو يجمعــا‬\n                                                                ‫فأمرهمــا جائــز ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة املعــرف بهــا مــن قبــل والدهــا أن املدعــى عليــه تزوجهــا‪،‬‬\n‫ورزقــت منــه بابنــن وأن العشــرة ســاءت بينهمــا‪ ،‬وذلــك أنــه يضربهــا‬\n‫ويشــتمها ويســيء معاملتهــا ويتعاطــى املخــدرات‪ ،‬وال يعتنــي بنظافــة‬\n‫بدنــه‪ ،‬وأنهــا أصبحــت مبغضــة لــه وال تطيــق العيــش معــه وطلبــت‬\n‫تكليفــه بطالقهــا أو فســخ نكاحهــا منــه ‪ ،‬بعــرض دعــوى املدعيــة‬\n‫علــى املدعــى عليــه صــادق علــى الــزواج واملهــر واألبنــاء وأنكــر مــا ســوى‬\n‫ذلــك‪ ،‬وقــرر أنــه ضربهــا مــرة واحــدة بســبب وجــود مقاطــع إباحيــة يف‬\n‫جهازهــا اجلــوال وبســبب تكــرر رفــع صوتهــا عليــه‪ ،‬ولــم يوافــق علــى‬\n‫طلبهــا الطــاق ‪ ،‬اســتجابة لقــول اهلل تعالــى ( وإن خفتــم شــقاق بينهمــا‬\n‫فابعثــوا حكمــا مــن أهلــه وحكمــا مــن أهلهــا ) مت طلــب حكمــن مــن‬\n‫الطرفــن ‪ ،‬اختــارت املدعيــة أخاهــا‪ ،‬واختــار املدعــى عليــه أهــل اخلبــرة‬\n‫يف احملكمــة ‪ ،‬جــرى التحكيــم بــن الطرفــن ومحاولــة اإلصــاح‬\n‫بينهمــا قــدر املســتطاع ‪ -‬ورد جــواب هيئــة النظــر يف احملكمــة املتضمــن‬\n\n                                                                                       ‫‪308‬‬\n\f      ‫أنــه حضــر حكــم الزوجــة وحكـ ٌـم مــن قبــل الــزوج وذكــرا أن األمــر‬\n      ‫وصــل إلــى طريـ ٍـق مســدود ورأت هيئــة النظــر أن تعيــد املدعيــة املهــر‬\n      ‫إلــى زوجهــا وتتــم املخالعــة ‪ ،‬بعــرض ذلــك علــى الطرفــن وافقــت عليــه‬\n      ‫املدعيــة‪ ،‬وقــرر املدعــى عليــه عــدم موافقتــه ‪ ،‬قــرر الطرفــان أن املهــر‬\n      ‫عشــرون ألــف ‪ ،‬أحضــرت املدعيــة العــوض بشــيك مصــدق مببلــغ قــدره‬\n      ‫عشــرون ألــف ريــال ‪ ،‬وقــررت تنازلهــا عــن مؤخــر الصــداق وقــدره ثالثون‬\n      ‫ألــف ريــال ‪ ،‬إلصــرار كل منهمــا علــى رأيــه ونظــر ًا إلــى أن اســتمرار‬\n      ‫احليــاة الزوجيــة علــى هــذا الوضــع أمــر ال تتحقــق منــه مقاصــد النــكاح‬\n      ‫يف الشــريعة مــن املــودة والرحمــة والســكن وتربيــة األوالد والعفــة مــع‬\n      ‫مــا يف ذلــك مــن املضــار النفســية واالجتماعيــة واجلســدية علــى الزوجــن‬\n      ‫واألوالد‪ ،‬ونظــر ًا لبقــاء املدعيــة ناشــز ًا مــع طــول املــدة أمــر غيــر محمــود‬\n      ‫شــرع ًا مــع مــا ينشــأ عنــه مــن الظلــم واإلثــم والقطيعــة بــن األســر وتوليــد‬\n      ‫العــداوة والبغضــاء ‪ ،‬لــذا مت احلكــم بفســخ نــكاح املدعيــة مــن زوجهــا‬\n      ‫املدعــى عليــه علــى عــوض قــدره عشــرون ألــف ريــال ‪ ،‬جــرى إفهــام‬\n      ‫املدعيــة بــأن عليهــا العــدة الشــرعية ‪ ،‬كمــا جــرى إفهــام املدعــى عليــه‬\n      ‫بــأن زوجتــه قــد بانــت منــه بينونــة صغــرى ال حتــل لــه إال بعقــد ومهــر‬\n      ‫جديديــن ‪ ،‬بعــرض احلكــم علــى الطرفــن قــررت املدعيــة القناعــة وقــرر‬\n      ‫املدعــى عليــه عدمهــا ‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت‬\n                                                                         ‫املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫‪309‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا (‪ )........‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيس احملكمة العامــة مبحافظة جدة‪/‬‬\n‫املســاعد برقــم ‪ 33199867‬وتاريــخ ‪1433/3/20‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 33530117‬وتاريــخ ‪1433/03/20‬ه ـ حضــرت (‪ )........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬املعــرف بهــا مــن قبــل‬\n‫والدهــا (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)........‬‬\n‫وحضــر حلضورهــا (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )........‬فادعــت ‪ ...‬قائلــة يف دعواهــا أن املدعــى عليــه زوجــي‬\n‫تزوجنــي عــام ‪1425‬ه ـ بواليــة والــدي مبوجــب عقــد نــكاح رســمي ال‬\n‫اعــرف رقمــه وال تاريخــه وأمهرنــي مبلغــا وقــدره ثالثــون ألــف ريــال وقــد‬\n‫رزقــت منــه بابنــن وهمــا ‪ ......‬املولــود يف ‪1427/3/19‬ه ـ و‪ ..........‬املولــود‬\n‫يف ‪1430/11/13‬ه ـ وقــد ســاءت العشــرة بينــي وبينــه فهــو يضربنــي‬\n‫ويشــتمني ويســيء معاملتــي ويتعاطــى املخــدرات وال يعتنــي بنظافــة‬\n‫بدنــه فأصبحــت مبغضــة لــه وال أطيــق العيــش معــه لــذا اطلــب تكليفــه‬\n‫بطالقــي أو فســخ نكاحــي منــه هكــذا ادعــت وبعــرض الدعــوى علــى‬\n‫املدعــى عليــه قــال مــا ذكرتــه املدعيــة يف دعواهــا مــن الــزواج وتاريخــه‬\n‫واملهــر وقــدره واألبنــاء وتواريــخ ميالدهــم كلــه صحيــح ومــا ذكرتــه مــن‬\n‫أننــي اشــتمها وأســيء معاملتهــا وأتعاطــى املخــدرات وال أعتنــي بنظافــة‬\n‫بدنــي فهــو غيــر صحيــح ومــا ذكرتــه مــن أننــي أضربهــا فلــم أضربهــا‬\n‫ســوى مــرة واحــدة بســبب وجــود مقاطــع اباحيــة يف جهازهــا اجلــوال‬\n\n                                                                                     ‫‪310‬‬\n\f      ‫وبســبب تكــرر رفــع صوتهــا علــي وأمــا طلبهــا الطــاق فــا أوافــق عليــه‬\n      ‫فهــي زوجتــي وأم أوالدي وأحبهــا وال أوافــق علــى طلبهــا الطــاق هكــذا‬\n      ‫أجــاب واســتجابة لقــول اهلل تعالــى ( وان خفتــم شــقاق بينهمــا فابعثــوا‬\n      ‫حكمــا مــن أهلــه وحكمــا مــن أهلهــا ) طلبــت مــن الطرفــن اختيــار‬\n      ‫حكمــن مــن أهلهمــا فاختــارت املدعيــة أخاهــا ‪ ...........‬واختــار املدعــى‬\n      ‫عليــه أهــل اخلبــرة يف احملكمــة فقــررت الكتابــة لقســم اخلبــراء يف هــذه‬\n      ‫احملكمــة الختيــار حكــم املدعــى عليــه مــن قبلهــم واالجتمــاع باحلكــم‬\n      ‫الــذي اختارتــه املدعيــة وإجــراء التحكيــم بــن الطرفــن ومحاولــة‬\n      ‫اإلصــاح بينهمــا قــدر املســتطاع ويف جلســة اخــرى حضــر الطرفــان‬\n      ‫واملعــرف وقــد كانــت جــرت الكتابــة لقســم الصلــح الختيــار حكــم‬\n      ‫منهــم عــن املدعــى عليــه واالجتمــاع بحكــم الزوجــة وإجــراء التحكيــم‬\n      ‫ومحاولــة اإلصــاح بينهمــا قــدر املســتطاع وذلــك مبوجــب خطابنــا رقــم‬\n      ‫‪ 33530117‬يف ‪1433/08/05‬ه ـ فوردنــا خطابهــم رقــم ‪ 33530117‬يف‬\n      ‫‪1433/10/15‬ه ـ وبرفقــه محضرهــم املــؤرخ يف ‪1433/10/13‬ه ـ ونــص‬\n      ‫احلاجــة منــه ( حضــرت املدعيــة وحضــر حلضورهــا املدعــى عليــه وجــرت‬\n      ‫محاولــة اإلصــاح حيــث ذكــرت املدعيــة أنهــا زوجــة لهــذا احلاضــر‬\n      ‫يف مجلــس الصلــح وأنهــا كرهــة العيــش معــه لســوء معاملتــه وطلبنــا‬\n      ‫إحضــار حكمــا مــن قبــل املدعيــة فأحضــرت ‪ .............‬وأحضــر الــزوج‬\n      ‫‪ ............‬وذكــرا أن األمــر وصــل إلــى طريــق مســدود وبعــرض ذلــك علــى‬\n      ‫الــزوج ذكــر أنــه يرغــب يف زوجتــه وال يســتطيع فراقهــا وحيــث األمــر‬\n      ‫مــا ذكــر وبعــد العــرض علــى املدعيــة إمــا العــودة إلــى بيــت زوجهــا أو‬\n      ‫إعــادة املهــر قالــت الزوجــة ال أريــده ومســتعدة بإعــادة املهــر ومقــداره‬\n      ‫عشــرون ألــف ريــال وحيــث األمــر مــا ذكــر فإنــا نــرى أن تعيــد املهــر إلــى‬\n\n\n‫‪311‬‬\n\f‫زوجهــا وتتــم املخالعــة والــرأي لفضيلتكــم‪ .‬حكــم مــن قبــل الزوجــة‬\n‫‪ ..........‬توقيــع ‪ ..............‬توقيــع) وبعرضــه علــى الطرفــن قالــت املدعيــة‬\n‫إننــي موافقــة علــى مــا جــاء فيــه هكــذا قــرر وقــال املدعــى عليــه إننــي‬\n‫غيــر موافــق علــى مــا جــاء فيــه هكــذا قــررت فجــرى ســؤال املدعيــة‬\n‫عــن املهــر فقالــت إنــه ليــس لــدي وأطلــب إمهالــي إلحضــاره كمــا قــرر‬\n‫الطرفــان بــأن املهــر عشــرين ألــف ريــال وليــس كمــا ذكــر يف اجللســة‬\n‫األولــى مــن أنــه ثالثــون ألــف ريــال ‪ ..........‬يتبــع ورفعــت اجللســة لذلــك ويف‬\n‫جلســة أخــرى حضــر الطرفــان واملعــرف وقــد أبــرزت الشــيك املصــدق‬\n‫رقــم ‪ 33440‬يف ‪2012/09/24‬م املســحوب علــى مصــرف اإلمنــاء باســم‬\n‫فضيلــة رئيــس احملكمــة مببلــغ وقــدره عشــرون ألــف ريــال وقــد جــرى‬\n‫منــي محاولــة اإلصــاح بــن الطرفــن مــرارا فلــم يصطلحــا فبنــاء علــى ما‬\n‫تقــدم مــن الدعــوى واإلجابــة ومــا قــرره احلكمــان اللــذان مت اختيارهمــا‬\n‫مــن قبــل الزوجــن مــن التفريــق بينهمــا بــدون عــوض ومــا مت مــن وعظهمــا‬\n‫وتوجيههمــا وإلصــرار كل منهمــا علــى رأيــه ولعمــوم قولــه تعالــى‪« :‬وإن‬\n‫خفتــم شــقاق بينهمــا فابعثــوا حكم ـ ًا مــن أهلــه وحكم ـ ًا مــن أهلهــا إن‬\n‫يريــدا إصالح ـ ًا يوفــق اهلل بينهمــا» وملــا رواه البخــاري عــن ابــن عبــاس‬\n‫رضــي اهلل عنهمــا قــال‪ :‬جــاءت امــرأة ثابــت بــن قيــس بــن شــماس إلــى‬\n‫النبــي صلــى اهلل عليــه وســلم فقالــت‪ :‬يــا رســول اهلل مــا أنقــم علــى ثابــت‬\n‫يف ديــن وال خلــق إال أنــي أخــاف الكفــر يف اإلســام‪ ،‬فقــال رســول اهلل‬\n‫صلــى اهلل عليــه وســلم‪ :‬أترديــن عليــه حديقتــه قالــت‪ :‬نعــم فــردت عليــه‬\n‫فأمــره ففارقهــا»‪ ،‬ولقولــه صلــى اهلل عليــه وســلم ‪« :‬ال ضــرر وال ضــرار»‬\n‫وملــا رواه النســائي وعبــد الــرزاق عــن ابــن عبــاس رضــي اهلل عنهمــا قــال‪:‬‬\n‫بعثــت أنــا ومعاويــة حكمــن قــال معمــر‪ :‬بلغنــي أن عثمــان بعثهمــا وقــال‬\n\n\n                                                                                          ‫‪312‬‬\n\f      ‫إن رأيتمــا أن جتمعــا جمعتمــا وإن رأيتمــا أن تفرقــا ففرقا»وملــا رواه‬\n      ‫الــدار قطنــي والنســائي والشــافعي والبيهقــي عــن محمــد بــن ســيرين عــن‬\n      ‫عبيــدة قــال‪« :‬جــاء رجــل وامــرأة إلــى علــي مــع كل واحــد منهمــا فئــام‬\n      ‫مــن النــاس فأمرهــم فبعثــوا حكمـ ًا مــن أهلــه وحكمـ ًا مــن أهلهــا وقــال‬\n      ‫للحكمــن هــل تدريــان مــا عليكمــا؟ عليكمــا إن رأيتمــا إن جتمعــا‬\n      ‫فاجمعــا وإن رأيتمــا أن تفرقــا فرقتمــا فقالــت املــرأة‪ :‬رضيــت بكتــاب‬\n      ‫اهلل مبــا علـ ّـي فيــه ولــي ‪ ،‬وقــال الــزوج‪ :‬أمــا الفرقــة فــا‪ ،‬فقــال علــي‪:‬‬\n      ‫كذبــت واهلل ال تبــرح حتــى تقــر مثــل الــذي أقــرت بــه» قــال ابــن حجــر‪:‬‬\n      ‫إســناده صحيــح وملــا أخرجــه الطبــري يف تفســيره‪ :‬عــن ابــن عبــاس رضــي‬\n      ‫اهلل عنهمــا يف احلكمــن أنــه قــال‪ :‬فــإن اجتمــع أمرهمــا علــى أن يفرقــا‬\n      ‫أو يجمعــا فأمرهمــا جائــز ونظــر ًا إلــى أن اســتمرار احليــاة الزوجيــة علــى‬\n      ‫هــذا الوضــع أمــر ال تتحقــق منــه مقاصــد النــكاح يف الشــريعة مــن املــودة‬\n      ‫والرحمــة والســكن وتربيــة األوالد والعفــة مــع مــا يف ذلــك مــن املضــار‬\n      ‫النفســية واالجتماعيــة واجلســدية علــى الزوجــن واألوالد‪ ،‬ونظــر ًا لبقــاء‬\n      ‫املدعيــة ناشــز ًا مــع طــول املــدة أمــر غيــر محمــود شــرع ًا مــع مــا ينشــأ عنــه‬\n      ‫مــن الظلــم واإلثــم والقطيعــة بــن األســر وتوليــد العــداوة والبغضــاء لــذا‬\n      ‫كلــه فقــد فســخت نــكاح املدعيــة ‪ ................‬مــن زوجهــا املدعــى عليــه‬\n      ‫‪ ..........‬وقــدره عشــرون ألــف ريــال وبــه حكمــت وجــرى إفهــام املدعيــة‬\n      ‫بــأن عليهــا العــدة الشــرعية وهــي ثــاث حيــض فقــد ذكــرت أنهــا مــن‬\n      ‫ذوات األقــراء كمــا جــرى إفهــام املدعــى عليــه بــأن زوجتــه قــد بانــت‬\n      ‫منــه بينونــة صغــرى ال حتــل لــه إال بعقــد ومهــر جديديــن وبعــرض احلكــم‬\n      ‫علــى الطرفــن قــررت املدعيــة القناعــة وقــرر املدعــى عليــه عــدم القناعــة‬\n      ‫وجــرى إفهامــه بتعليمــات االعتــراض وجــرى إفهــام الزوجــة بــأن عليهــا‬\n\n\n‫‪313‬‬\n\f‫أن ال تتــزوج وال تتعــرض خلاطــب حتــى يكتســب احلكــم القطعيــة كمــا‬\n‫قــررت التهميــش علــى عقــد النــكاح بحكمــي هــذا بعــد اكتســاب‬\n‫احلكــم القطعيــة وقــررت بعــث العــوض لبيــت املــال يف هــذه احملكمــة‬\n‫حلفظــه لديهــم لصالــح املدعــى عليــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n        ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/9‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ .........‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة والقائــم بعمــل‬\n‫فضيلــة القاضــي ‪ ..........‬أثنــاء تواجــده يف الــدورة التدريبيــة ففــي يــوم‬\n‫الثالثــاء املوافــق ‪1434/2/19‬ه ـ افتتحــت اجللســة بعــد أن عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 3413731‬وتاريــخ‬\n‫‪1434/01/17‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم بفســخ النــكاح‬\n‫مــع مالحظــة التنبيــه املرفــق واهلل املوفــق ) قاضــي اســتئناف ‪............‬‬\n‫ختــم وتوقيــع قاضــي اســتئناف ‪ ....................‬ختــم وتوقيــع رئيــس الدائــرة‬\n‫‪ ..............‬ختــم وتوقيــع عليــه فقــد أمــرت بإثباتــه علــى ضبطــه وســجله‬\n‫حتــى ال يخفــى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/19‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n‫‪............‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة ويف يــوم األحــد‬\n‫املوافق‪1434/04/21‬ه ـ حضــرت املدعيــة واملعــرف وقــد جــرى االطــاع‬\n‫علــى قــرار التصديــق املرصــود نــص احلاجــة منــه أعــاه فتبــن وجــود‬\n‫تنبيــه مرفــق بــه مــن أصحــاب الفضيلــة قضــاة محكمــة االســتئناف‬\n‫ونــص احلاجــة مــن هــذا التنبيــه ( وحيــث جــرى منــا تصديقــه فإننــا ننبــه‬\n\n\n                                                                                       ‫‪314‬‬\n\f      ‫فضيلتــه إلــى مــا يلــي ‪ -1‬أخــذ اقــرار املدعيــة بأنهــا ال تطالــب باملؤخــر‬\n      ‫واحلاقــه بالصــك وســجله ‪ -2‬الغــاء مــا ورد يف الســطر الثالــث مــن الصــك‬\n      ‫صفحــة رقــم ‪ 2‬وكذلــك يف الضبــط واملقوســة بقلــم الرصــاص ‪ -3‬طلــب‬\n      ‫العقــد والشــرح عليــه مبــا مت مــن قبــل فضيلتــه املرفــق واهلل املوفــق )‬\n      ‫وبعــرض ذلــك علــى املدعيــة قالــت إننــي متنازلــة عــن مؤخــر الصــداق‬\n      ‫وقــدره ثالثــون ألــف ريــال ولــن أطالــب املدعــى عليــه بــه هكــذا قــررت‬\n      ‫وســيجري منــا تــدارك مــا جــاء يف الفقرتــن ‪ 2‬و ‪ 3‬إن شــاء اهلل وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                          ‫حــرر يف‪1434/04/21‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية‬\n      ‫واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف‬\n      ‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة املســاعد مبحافظــة جــده برقــم ‪33530117‬‬\n      ‫وتاريــخ ‪1434/1/5‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪ ...........‬القاضــي باحملكمــة العامــة بجــده برقــم ‪ 33450924‬وتاريــخ‬\n      ‫‪1433/11/10‬ه ـ املتضمــن طلــب املــرأة ‪ ..........‬فســخ نكاحهــا مــن‬\n      ‫زوجهــا ‪ ، ........‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم بفســخ النــكاح مــع مالحظــة التنبيــه‬\n      ‫املرفــق ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                                                ‫وســلم ‪.‬‬\n\n\n\n\n‫‪315‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":307,"source_page_end":315,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e5cff5693ae7f896b195ff7a6127f4927d00f857ae4474e1ede95d7e4bc89fc2","normalized_text_hash":"91e7e0b2692511a6feb2452e196c72b28097256165e2936684e5eae9b650b489","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p307-33450924"},{"id":"ddc30d37-5907-5c06-acd7-b50835611a97","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -فسخ نكاح -مطالبة بسكن مستقل -ورد تقرير مكتب الصلح قرر فيه إن املدعى عليه ال يستطيع توفير سكن مستقل - املطالبة بالفسخ للسبب الوارد -حكمت المحكمة بفسخ النكاح دون عوض للسبب الوارد -صدق احلكم .","document_number":"34180146","case_number":"33248843","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/6","year":"1434","subject":"زوجية -فسخ نكاح -مطالبة بسكن مستقل -ورد تقرير مكتب الصلح قرر فيه إن املدعى عليه ال يستطيع توفير سكن مستقل - املطالبة بالفسخ للسبب الوارد -حكمت المحكمة بفسخ النكاح دون عوض للسبب الوارد -صدق احلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/6 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34180146 :‬‬\n                   ‫َر ْق ُم الدعوى‪33248843 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34248843‬تاريخه‪1434/6/21:‬هـ‬\n\n\n‫زوجيــة ‪ -‬فســخ نــكاح ‪ -‬مطالبــة بســكن مســتقل ‪ -‬ورد تقريــر مكتــب‬\n‫الصلــح قــرر فيــه إن املدعــى عليــه ال يســتطيع توفيــر ســكن مســتقل ‪-‬‬\n‫املطالبــة بالفســخ للســبب الــوارد ‪ -‬حكمــت احملكمــة بفســخ النــكاح دون‬\n                               ‫عــوض للســبب الــوارد ‪ -‬صــدق احلكــم ‪.‬‬\n\n\n\n\n               ‫(فإمساك مبعروف أو تسريح بإحسان)‪.‬‬     ‫ٌ‬          ‫‪ .1‬قول اهلل تعالى‬\n‫‪ .2‬قــول الرســول صلــى اهلل عليــه وســلم (امرأتــك تقــول أطعمنــي وإال‬\n                      ‫فارقنــي) رواه أحمــد والــدار قطنــي بإســناد صحيــح‪.‬‬\n‫‪ .3‬قــول البهوتــي (فصــل وإن اعســر الــزوج بنفقتهــا الواجبــة أو أعســر‬\n‫الــزوج ببعضهــا أي بعــض النفقــة بــأن أعســر عــن نفقــة املعســر فلهــا‬\n‫الفســخ وال تفســخ إذا أعســر مبــا زاد عنهــا أي عــن نفقــة املعســر ‪ -‬ألن‬\n‫الزيــادة تســقط بإعســاره أو أعســر الــزوج بالكســوة أو ببعضهــا أو أعســر‬\n‫بالســكنى أو أعســر باملهــر بشــرطه وتقــدم الســابق يف آخــر الصــداق‬\n‫خيــرت علــى التراخــي بــن الفســخ مــن غيــر انتظــار أي تأجيــل ثالث ـ ًا‬\n‫خالفـ ًا البــن البنــاء وبــن املقــام معــه علــى النــكاح وهــذا قــول عمــر وعلــي‬\n                                      ‫وأبــي هريــرة) كشــاف القنــاع‪. 476/5‬‬\n\n\n\n\n                                                                                         ‫‪316‬‬\n\f      ‫ادعــت زوجــة بالدعــوى تطالــب زوجهــا بتأمــن ســكن مســتقل لهــا ‪ -‬أقر‬\n      ‫املدعــى عليــه مبــا جــاء يف دعــوى املدعيــة وذكــر انــه ال مانــع مــن توفيــر‬\n      ‫ســكن مســتقل لهــا متــى مــا اســتطاع وانــه ال يســتطيع يف الوقــت احلاضر‬\n      ‫‪ ،‬أنكــرت املدعيــة مــا ذكــره املدعــى عليــه مــن أنــه ال يســتطيع تأمــن‬\n      ‫الســكن املســتقل ألنــه موظــف يف شــركة (‪ )...‬فســألت احملكمــة‬\n      ‫املدعــى عليــه عــن عملــه وراتبــه الشــهري وذكــر انــه موظــف يف شــركة‬\n      ‫ويتقاضــى راتــب شــهري قــدره ثالثــة آالف وســتمائة ريــال ‪ ،‬وطلبــت‬\n      ‫احملكمــة عقــد النــكاح فأبرزتــه املدعيــة وبعــد االطــاع عليــه تبــن أن‬\n      ‫مــن شــروط املدعيــة يف عقــد النــكاح بيــت مســتقل ‪ ،‬ســألت احملكمــة‬\n      ‫املدعــى عليــه عــن املانــع مــن اســتئجاره لســكن مســتقل لزوجتــه مــع‬\n      ‫وجــود راتبــه الشــهري فذكــر أن لديــه قســط شــهري لســداد قيمــة‬\n      ‫ســيارة قــدره ألــف وســبعمائة وواحــد وســبعون ريــا ًال فأفهمتــه احملكمــة‬\n      ‫بإحضــار مــا يثبــت ذلــك وكتبــت لقســم اخلبــراء لديهــا لإلفــادة عــن مــدى‬\n      ‫كفايــة راتــب املدعــى عليــه الســتئجار ســكن ‪ ،‬ورد للمحكمــة خطاب‬\n      ‫مــن مكتــب الصلــح بأنــه مت االجتمــاع بــن الطرفــن وانــه تعــذر الصلــح‬\n      ‫بينهمــا واتضــح انــه يتقاضــى راتــب قــدره ثالثــة آالف وخمســمائة ريــال‬\n      ‫وأن عليــه أقســاط مســتحقه وأن راتبــه يف الوقــت احلاضــر ال يكفــي‬\n      ‫الســتئجار ســكن ‪ ،‬عرضــت احملكمــة قــرار مكتــب الصلــح علــى‬\n      ‫الطرفــن فطالبــت املدعيــة بفســخ نكاحهــا بــا عــوض ‪ ،‬ورفــض‬\n      ‫املدعــى عليــه الفســخ ‪ ،‬وبعــد تأمــل احملكمــة لقــرار مكتــب الصلح وما‬\n      ‫قــرره املدعــى عليــه مــن عجــزه عــن الســكن املســتقل للمدعيــة واختيــار‬\n\n‫‪317‬‬\n\f‫املدعيــة للفســخ وملــا قــرره الفقهــاء مــن أن الــزوج إذا اعســر بنفقــة الزوجة‬\n‫ومنهــا تأمــن الســكن خيــرت الزوجــة بــن الفســخ مــن غيــر انتظــار أو‬\n‫البقــاء معــه ولقولــه صلــى اهلل عليــه وســلم (امرأتــك تقــول أطعمنــي وإال‬\n‫فارقنــي) لــذا فســخت احملكمــة نــكاح املدعــى عليــه مــن املدعيــة بــدون‬\n‫عــوض وأفهمتهــا بــأن عليــه العــدة الشــرعية ‪ ،‬اعتــرض املدعــى عليــه ‪،‬‬\n                                                                 ‫صــدق احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا(‪ )........‬القاضــي يف احملكمــة العامــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫وتاريــخ ‪1433/04/10‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1433/4/10‬ه ـ‬\n‫ففــي يــوم الثالثــاء املوافــق ‪1433/06/24‬ه ـ افتتحــت اجللســة وفيهــا‬\n‫حضــرت (‪ )........‬ســعودية (املعــرف بهــا مــن قبــل والدهــا ســعودي)‬\n‫وادعــت علــى احلاضــر (‪ )........‬ســعودي قائلــة يف دعواهــا‪ :‬إن املدعــى‬\n‫عليــه هــذا احلاضــر معــي زوجــي مبوجــب عقــد النــكاح لــدى مــأذون‬\n‫األنكحــة (‪ )........‬وتاريــخ ‪1430/6/6‬ه علــى مهــر وقــدره خمســون‬\n‫ألــف ريــال مقبوضــة ودخــل بــي الدخــول الشــرعي وأجنبــت منــه (‪)........‬‬\n‫املولــود يف ‪1431/7/16‬ه ـ وأخرجنــي مــن بيتــي إلــى بيــت أهلــي يف‬\n‫‪1432/6/28‬ه ـ حيــث قــال لــي روحــي ألهلــك ألننــي طلبــت منــه ســكن ًا‬\n‫ال لــي ألنــه أســكنني يف بيــت أهلــه املســتأجر فاتصلــت علــى‬     ‫مســتق ً‬\n‫أهلــي وأخذونــي ثــم بعــد أســبوعني أحضــر عفشــي إلــى بيــت أهلــي وإلــى‬\n‫اآلن لــم يجعــل لــي بيــت مســتقل حســب شــرط العقــد لــذا اطلــب أن يجعــل‬\n‫لــي ســكنا مســتقال هــذه دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب‬\n                                                                                      ‫‪318‬‬\n\f      ‫قائــا‪ :‬مــا ذكرتــه املدعيــة مــن زواجــي بهــا والدخــول واملهــر واجنابهــا‬\n      ‫(‪ )........‬وســلمت لهــا مــن النفقــة ســتمائة ريــال فقــط فهــذا كلــه صحيــح‬\n      ‫ومــا ذكرتــه أننــي طلبــت منهــا الذهــاب إلــى أهلهــا فغيــر صحيــح بــل‬\n      ‫خرجــت مــن نفســها ألنهــا ترفــض اســتمرار الســكن مــع أهلــي وأنــا ال‬\n      ‫ال متــى اســتطعت وأمــا االن‬‫مانــع لــدي مــن أن أجعــل لهــا ســكن ًا مســتق ً‬\n      ‫فــا أســتطيع هكــذا أجــاب‪ .‬ويف يــوم االثنــن املوافــق ‪1433/11/01‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــرت (‪ )........‬املعــرف بهــا مــن قبــل والدهــا‬\n      ‫(‪ )........‬واملدعــى عليــه (‪ )........‬وبعــرض مــا ذكــره املدعــى عليــه يف‬\n      ‫اجللســة املاضيــة علــى املدعيــة أجابــت قائلــة‪ :‬مــا ذكــره املدعــى عليــه‬\n      ‫أنــه ال يســتطيع أن يســتأجر لــي ســكن ًا فغيــر صحيــح بــل يســتطيع‬\n      ‫وهــو موظــف يف شــركة هكــذا أجابــت وبســؤال املدعــى عليــه عــن‬\n      ‫وظيفتــه وراتبــه الشــهري أجــاب قائــا ‪ :‬أعمــل رجــل أمــن يف شــركة‬\n      ‫خاصــة وراتبــي الشــهري قــدره ثالثــة آالف وســتمائة ريــال هكــذا‬\n      ‫أجــاب وبطلــب عقــد الــزواج أبــرزت املدعيــة صــورة مــن ضبــط عقــد زواج‬\n      ‫للســعوديني وتاريــخ ‪1430/6/6‬ه ـ لــدى مــأذون األنكحــة واملتضمــن‬\n      ‫عقــد الــزواج بــن املدعيــة واملدعــى عليــه ومــن شــروطه بيــت مســتقل‪.‬‬\n      ‫أ‪.‬ه ـ وبســؤال املدعــى عليــه عــن املانــع لــه مــن اســتئجار ســكن لزوجتــه‬\n      ‫مــع وجــود راتبــه الشــهري أجــاب قائــا ‪ :‬لــدي قســط شــهري قــدره ألــف‬\n      ‫وســبعمائة وواحــد وســبعون ريــال الســداد ثمــن الســيارة هكــذا أجــاب‬\n      ‫وأفهمتــه بإحضــار مــا يثبــت ذلــك القســط كمــا أمــرت بالكتابــة إلــى‬\n      ‫قســم اخلبــراء لإلفــادة عــن مــدى كفايــة راتــب املدعــى عليــه الســتئجار‬\n                                                                            ‫ســكن‪.‬‬\n      ‫ويف يــوم الســبت املوافــق ‪1434/04/06‬ه ـ افتتحــت اجللســة وفيهــا‬\n\n\n‫‪319‬‬\n\f‫حضــرت املدعيــة املعــرف بهــا مــن قبــل أخوهــا (‪ )........‬ســعودي مبوجــب‬\n‫ســجل مدنــي رقــم (‪ )........‬وحضــر املدعــى عليــه ووردنــا خطــاب مديــر‬\n‫مكتــب الصلــح برقــم (‪ )........‬وتاريــخ ‪1434/3/25‬ه ـ املتضمــن أنــه مت‬\n‫االجتمــاع بالطرفــن وقــد تعــذر الصلــح بينهمــا واملدعيــة تطالــب املدعــى‬\n‫عليــه بتأمــن املســكن وأنــه ال يســتطيع تأمــن املســكن يف الوقــت‬\n‫احلاضــر وبعــد نهايــة األقســاط املســتحقة عليــه ســوف يقــوم بتأمــن‬\n‫املســكن وجتــدون إقــرار كال منهمــا بطــي املعاملــة وبنــاء علــى ذلــك‬\n‫واحلــال كمــا ذكــر وبعــد االطــاع علــى مقــدار مرتــب املدعــى عليــه‬\n‫حيــث اتضــح أنــه يتقاضــى مرتــب ‪ 3500‬ريــال وذلــك حســب اخلطــاب‬\n‫املرفــق رقــم بــدون وتاريــخ ‪1434/2/3‬ه ـ الصــادر مــن إدارة املجاهديــن‬\n‫وكذلــك كشــف احلســاب املرفــق واألقســاط املســتحقة عليــه وبعــد‬\n‫التأمــل يف الوضــع املــادي للمدعــى عليــه فإننــا نــرى إنــه تكــون النفقــة‬\n‫الســابقة واملســتقبلية للمدعيــة وابنهــا ‪ 400‬ريــال شــهري ًا لــكل واحــد‬\n‫منهمــا أمــا بخصــوص مــدى كفايــة راتــب املدعــى عليــه الســتئجار‬\n‫ســكن فإننــا نــرى أنــه غيــر كايف حيــث أنــه بعــد خصــم القســط‬\n‫املســتحق عليــه ونفقتــه علــى املدعيــة وابنهــا ال يتبقــى مــن مرتبــه إال‬\n‫الشــيء القليــل هــذا مــا لدينــا‪ .‬أ‪.‬ه ـ وبعرضــه علــى املدعيــة أجابــت قائلــة‪:‬‬\n‫أطلــب فســخ النــكاح بــدون عــوض هكــذا أجابــت‪ .‬وبعرضــه علــى‬\n‫املدعــى عليــه أجــاب قائــا‪ :‬أرفــض فســخ النــكاح هكــذا أجــاب‪ .‬فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وقــرار مكتــب الصلــح ومــا قــرره‬\n‫املدعــى عليــه مــن عجــزه عــن الســكن املســتقل للمدعيــة واختيارهــا‬\n‫فســخ النــكاح بــدون عــوض وملــا قــرره الفقهــاء يف حــال إعســار الــزوج‬\n‫بالســكنى قــال يف كشــاف القنــاع (‪ (476/5‬فصــل وإن أعســر الــزوج‬\n\n\n                                                                                       ‫‪320‬‬\n\f      ‫بنفقتهــا الواجبــة أو أعســر الــزوج ببعضهــا أي بعــض النفقــة بــأن أعســر‬\n      ‫عــن نفقــة املعســر فلهــا الفســخ وال تفســخ إذا أعســر مبــا زاد عنهــا أي عــن‬\n      ‫نفقــة املعســر‪ ،‬ألن الزيــادة تســقط بإعســاره أو أعســر الــزوج بالكســوة‬\n      ‫أو ببعضها أو أعســر بالســكنى أو أعســر باملهر بشــرطه وتقدم الســابق‬\n      ‫يف آخــر الصــداق خيــرت علــى التراخــي بــن الفســخ مــن غيــر انتظــار أي‬\n      ‫تأجيــل ثالث ـ ًا خالف ـ ًا البــن البنــاء وبــن املقــام معــه علــى النــكاح وهــذا‬\n      ‫قــول عمــر وعلــي وأبــي هريــرة لقولــه تعالــى‪( :‬فإمســاك مبعــروف أو‬\n      ‫تســريح بإحســان) وليــس اإلمســاك مــع تــرك اإلنفــاق إمســاكا مبعــروف‬\n      ‫فتعــن التســريح وقــال صلــى اهلل عليــه وســلم‪( :‬امرأتــك تقــول أطعمنــي‬\n      ‫وإال فارقنــي) رواه أحمــد والدارقطنــي والبيهقــي بإســناد صحيــح ورواه‬\n      ‫الشــيخان مــن قــول أبــي هريــرة‪ .‬لــذا فســخت نــكاح املدعــى عليــه مــن‬\n      ‫املدعيــة بــدون عــوض وبــه حكمــت وأفهمــت املدعيــة أن عليهــا العــدة‬\n      ‫الشــرعية ثــاث حيــض وأن ال تتــزوج إال بعــد اكتســاب احلكــم القطعية‬\n      ‫وبإعــان احلكــم قــرر املدعــى عليــه املعارضــة وطلــب االســتئناف فســلم‬\n      ‫صــورة احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يوم ـ ًا فــإن مضــت‬\n      ‫املــدة ولــم يقــدم الئحــة اعتراضــه ســقط حقــه يف االعتــراض واكتســب‬\n      ‫احلكــم القطعيــة وأفهمــت املدعــى عليــه أن عليــه تســجيل هــذه الواقعــة‬\n      ‫يف إدارة األحــوال املدنيــة متــى اكتســب احلكــم القطعيــة وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                       ‫يف ‪1434/4/6‬ه ـ‬\n      ‫ويف يــوم الثالثــاء ‪1434/09/01‬ه ـ حســب تقــومي أم القــرى و‬\n      ‫‪1434/08/30‬ه ـ حســب الرؤيــة افتتحــت اجللســة الســاعة ‪ 09.00‬بنــاء‬\n      ‫علــى ورود املعاملــة بشــرح رئيــس احملكمــة علــى القيــد رقــم وتاريــخ‬\n\n\n‫‪321‬‬\n\f‫‪1434/7/30‬ه ـ وبرفقــه خطــاب رئيــس محكمــة االســتئناف وتاريــخ‬\n‫‪1434/06/28‬ه ـ وبرفقــه قــرار دائــرة األحــوال الشــخصية الثانيــة‬\n‫وتاريــخ ‪1434/6/21‬ه ـ ونصــه مــا يلــي ‪ :‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة‬\n‫علــى احلكــم وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                             ‫وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫املختصــة بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة‬\n‫االســتئناف علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫وتاريــخ ‪1434/6/14‬ه املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ (‪ . )........‬وتاريــخ ‪1434/4/6‬ه ـ اخلــاص بدعــوى‬\n‫(‪ )........‬ضــد (‪ )........‬بشــأن فســخ نــكاح ‪ ،‬وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى‬\n‫احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪322‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":316,"source_page_end":322,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"58f51fa7257b1e10d5128b0baaa46d40101dd67699e223ec9b570461a7d5f511","normalized_text_hash":"e5bae316e6e1717ccc51805729f923e95bf22fd8375599960c7a62e1fb259c99","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p316-34180146"},{"id":"2c5bd33a-2f9a-5628-ad18-db0a41b8bf32","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول للضرر كون الزوج يف غيبوبة مدة أربع سنوات -الغيبوبة مرض يذهب مقصد االستمتاع بن الزوجن ويوجب اخليار للزوجة -احلكم بفسخ النكاح دون عوض .","document_number":"34234714","case_number":"33260543","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول للضرر كون الزوج يف غيبوبة مدة أربع سنوات -الغيبوبة مرض يذهب مقصد االستمتاع بن الزوجن ويوجب اخليار للزوجة -احلكم بفسخ النكاح دون عوض .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/6/7 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34234714 :‬‬\n                        ‫َر ْق ُم الدعوى‪33260543 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34262527‬تاريخه‪1434/7/9:‬هـ‬\n\n\n      ‫فســخ نــكاح ‪ -‬طلــب الزوجــة فســخ النــكاح بعــد الدخــول للضــرر كــون‬\n      ‫الــزوج يف غيبوبــة مــدة أربــع ســنوات ‪ -‬الغيبوبــة مــرض يذهــب مقصــد‬\n      ‫االســتمتاع بــن الزوجــن ويوجــب اخليــار للزوجــة ‪ -‬احلكــم بفســخ‬\n                                                        ‫النــكاح دون عــوض ‪.‬‬\n\n\n\n\n            ‫تضاروهن لتذهبوا ببعض ما أتيتموهن ) ‪.‬‬      ‫ُّ‬     ‫‪ .1‬قوله تعالى‪ ( :‬وال‬\n                           ‫‪ .2‬قوله صلى اهلل عليه وسلم ( ال ضرر وال ضرار ) ‪.‬‬\n      ‫‪ .3‬قــال يف كشــاف القنــاع ( ويثبــت اخليــار يف فســخ النــكاح بجــذام أو‬\n      ‫بــرص أو جنــون ولــو أفــاق أحيانــا ألن النفــس ال تســكن إلــى مــن هــذه‬\n                                                            ‫حالــه ) ( ‪. ) 404/11‬‬\n\n\n\n\n      ‫ادعــت املدعيــة علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم أنــه‬\n      ‫تزوجهــا وأجنبــت منــه علــى فــراش الزوجيــة ثالثــة أوالد‪ ،‬وأنــه أصيــب‬\n      ‫بجلطــة قبــل أربــع ســنوات نتيجــة ارتفــاع ضغــط الــدم‪ ،‬وأنــه مــن ذلــك‬\n      ‫احلــن وهــو يف املستشــفى يف غيبوبــة وتضــررت مــن بقائهــا يف عصمتــه‪،‬‬\n      ‫وطلبت فسخ نكاحها منه ‪ ،‬ورد التقرير الطبي املتضمن ‪ :‬بأن املريض‬\n      ‫طريــح الفــراش وال يســتطيع احلركــة وال يتواصــل مــع احمليطــن بــه وهــو‬\n\n‫‪323‬‬\n\f‫يف غيبوبــة ســباتية ناجتــة عــن نزيــف ســابق باملــخ والتنفــس عــن طريــق‬\n‫أنبوبــه الشــق احلنجــري والتغذيــة عــن طريــق األنبوبــة األنفيــة املعديــة إ‪.‬ه ـ‬\n‫‪ ،‬أحضــرت املدعيــة شــاهدين ‪ ،‬ومت ســماع شــهادتهما ‪ ،‬وتعديلهمــا ‪،‬‬\n‫جــرى االطــاع علــى عقــد النــكاح فوجــد مطابقـ ًا لدعــوى املدعيــة ‪ ،‬مــا‬\n‫ورد يف التقريــر الطبــي يشــهد بصحــة مــا جــاء يف دعــوى املدعيــة‪ ،‬ومــا‬\n‫جــاء يف شــهادة الشــهود‪ ،‬وألن املــرض الواقــع علــى زوج املدعيــة يذهــب‬\n‫مقصــد االســتمتاع بــن الزوجــن ‪ ،‬وبقــاء املدعيــة يف عصمــة زوجهــا مــع‬\n‫مرضــه ويف هــذه املــدة الطويلــة ضــرر عليهــا وألن املــرض الواقــع باملدعــى‬\n‫عليــه ممــا يثبــت بــه اخليــار للمدعيــة ‪ ،‬وألن الضــرر يــزال يف الشــريعة ‪،‬‬\n‫لــذا مت احلكــم بفســخ نــكاح املدعيــة مــن زوجهــا املدعــى عليــه وجــرى‬\n‫إفهــام املدعيــة بــأن عليهــا العــدة الشــرعية ‪ ،‬وأنهــا بانــت مــن زوجهــا‬\n‫بينونــة صغــرى ال حتــل لــه إال مبهــر وعقــد جديديــن وبرضاهــا كمــا‬\n‫جــرى إفهامهــا بأنهــا ال تتــزوج حتــى يكتســب احلكــم الصفــة القطعيــة‬\n           ‫‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة جــدة بنــاء علــى االســتدعاء احملــال لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪33260543‬‬\n‫وتاريــخ ‪1433/04/13‬ه ـ املقيــد باحملكمــة برقــم ‪ 33701310‬وتاريــخ‬\n‫‪1433/04/13‬ه ـ ففــي يــوم الســبت املوافــق ‪1433/08/24‬ه ـ افتتحــت‬\n‫اجللســة الســاعة (‪ )10:15‬وفيهــا حضــرت املدعيــة (‪ )........‬مبوجــب‬\n‫اإلقامــة رقــم (‪ )........‬ولــم يحضــر املدعــى عليــه (‪ )........‬وال مــن ميثلــه‬\n                                                                                        ‫‪324‬‬\n\f      ‫بوكالــة شــرعية ولــم يردنــا مــا يفيــد تبلغــه مبوعــد هــذه اجللســة لــذا فقــد‬\n      ‫تقــرر رفــع اجللســة وتأجيلهــا إلــى يــوم األحــد املوافــق ‪1434/01/11‬ه ـ‬\n      ‫وبــاهلل التوفيــق ثــم بتاريــخ ‪1434/2/17‬ه ـ افتتحــت اجللســة وفيهــا‬\n      ‫حضــرت املدعيــة (‪ )........‬وحضــر حلضورهــا املترجــم (‪، )........‬‬\n      ‫بنجالديشــي اجلنســية مبوجــب اإلقامــة رقــم (‪ )........‬حيــث أن املدعيــة‬\n      ‫تتكلــم اللغــة البرماويــة وال جتيــد اللغــة العربيــة ولــم يحضــر املدعــى‬\n      ‫عليــه (‪ )........‬وال مــن ميثلــه بوكالــة شــرعية وقــد قــررت املدعيــة قائلــة‬\n      ‫إن املدعــى عليــه ‪ .........‬مريــض منــذ أربــع ســنوات وقــد أبــرزت مــن‬\n      ‫يدهــا صــورة إشــعار تنــومي بتاريــخ ‪1432/10/27‬ه ـ جــاء فيــه ( تشــهد‬\n      ‫مستشــفى ‪ ...........‬بحــداء بــأن املريــض أعــاه منــوم لدينــا باملستشــفى‬\n      ‫محــوال إلينــا بتاريــخ ‪1430/09/04‬ه ـ مــن مستشــفى النــور التخصصــي‬\n      ‫ومــا زال منومــا حتــى تاريــخ حتريــر هــذا اإلشــعار ‪1430/10/27‬ه ـ )‬\n      ‫أ‪.‬ه ـ ‪ ،‬عليــه فقــد تقــرر الكتابــة ملستشــفى ‪ ............‬بحــداء طريــق‬\n      ‫مكــة القــدمي لالستفســار عــن حــال املدعــى عليــه وموافاتنــا بتقريــر‬\n      ‫وايف ومفصــل عــن حالــة املذكــور واإلفــادة وحتــى ورود اجلــواب فقــد‬\n      ‫تقــرر رفــع اجللســة ثــم بتاريــخ ‪ 1434/06/04‬ه ـ افتتحــت اجللســة وفيهــا‬\n      ‫حضــرت املدعيــة ‪...........‬وحضــر حلضورهــا املترجــم يف هــذه احملكمــة‬\n      ‫‪ .............‬وبســؤال املدعيــة عــن دعواهــا أجابــت قائلــه ان املدعــى عليــه‬\n      ‫‪ ...........‬زوجــي تــزوج بــي مبوجــب عقــد شــرعي صحيــح ودخــل بــي‬\n      ‫الدخــول الشــرعي وقــد أجنبــت منــه علــى فــراش الزوجيــة ب‪.......‬‬\n      ‫وعمــره اآلن تســعة أعــوام و‪ .......‬وعمــره اآلن ســتة أعــوام و‪ .....‬وعمرهــا‬\n      ‫اآلن أربعــة أعــوام وقــد أصيــب بجلطــة نتيجــة ارتفــاع ضغــط الــدم وكان‬\n      ‫ذلــك قبــل أربعــة أعــوام ومــن ذلــك احلــن وزوجــي مريــض يف املستشــفى‬\n\n\n‫‪325‬‬\n\f‫لــم نســمع لــه صوتــا فهــو يف غيبوبــة وقــد تضــررت مــن بقائــي يف عصمتــه‬\n‫وهــو ال يعــي شــيئا أطلــب احلكــم بفســخ نكاحــي مــن املدعــى عليــه‬\n‫هــذه دعــواي وقــد وردنــا اخلطــاب الصــادر مــن مستشــفى ‪ .........‬بحــداء‬\n‫ذي الرقــم ‪ 93‬وتاريــخ ‪1434/2/23‬ه ـ واملقيــد بهــذه احملكمــة برقــم‬\n‫‪ 34584575‬وتاريــخ ‪1434/03/07‬ه ـ واملتضمــن مــا يلــي ( أن املريــض‬\n‫املذكــور حاليــا طريــح فــراش وال يســتطيع احلركــة وال يتواصــل مــع‬\n‫احمليطــن بــه وهــو يف غيبوبــة ســباتية ناجتــة عــن نزيــف ســابق باملــخ‬\n‫والتنفــس عــن طريــق أنبوبــه الشــق احلنجــري والتغذيــة عــن طريــق‬\n‫األنبوبــة األنفيــة املعديــة وذلــك منــذ إحالتــه إلينــا مــن مستشــفى النــور‬\n‫التخصصــي مبكــة املكرمــة بتاريــخ ‪1430/09/04‬ه ـ حتــى تاريخــه )‬\n‫وبعــد االطــاع علــى التقريــر املرفــق وبســؤال املدعيــة وهــل لديهــا مزيــد‬\n‫مــن البينــات علــى مــا جــاء ويف دعواهــا فأجابــت قائلــة نعــم لــدي املزيــد‬\n‫منهــا ومســتعدة بإحضارهــا يف اجللســة القادمــة فأجيــب لطلبهــا وتقــرر‬\n‫رفــع اجللســة لذلــك وتأجلــت إلــى يــوم األربعــاء املوافــق ‪1434/06/07‬ه ـ‬\n‫وبــاهلل التوفيــق ‪ .‬ثــم بتاريــخ ‪1434/6/7‬ه ـ افتتحــت اجللســة وفيهــا‬\n‫حضــرت املدعيــة ‪ ..................‬وقــد أبــرزت املدعيــة مــن يدهــا عقــد‬\n‫النــكاح الصــادر مــن احملكمــة العامــة مبكــة املكرمــة ذي الرقــم‬\n‫‪ ..............‬وتاريــخ ‪1425/08/27‬ه ـ والــذي جــرى االطــاع عليــه فوجــد‬\n‫مطابقــا ملــا جــاء يف دعواهــا وبســؤالها عمــا طلبــت املهلــة ألجلــه أحضــرت‬\n‫للشــهادة وأدائهــا ‪ ، ..............‬بنجالديشــي اجلنســية مبوجــب اإلقامــة رقــم‬\n‫‪ ..........‬ويظهــر أن تاريــخ ميــاده هــو ‪1399/01/01‬ه ـ وبســؤاله عــن‬\n‫معلوماتــه املدنيــة بعــد ظهــور معرفتــه العربيــة حتدثــا وفهمــا أجــاب قائــا‬\n‫إننــي أســكن يف كيلــو أربعــة عشــر يف مدينــة جــدة ومتــزوج ولــي أوالد‬\n\n\n                                                                                     ‫‪326‬‬\n\f      ‫وأعمــل يف مؤسســة خاصــة وأعــرف املدعيــة وزوجهــا مــن زمــن وأشــهد‬\n      ‫بــاهلل العظيــم أن زوج املدعيــة واســمه ‪..........‬مريــض يف غيبوبة منذ أربعة‬\n      ‫أعــوام وقــد زرتــه يف املستشــفى مــرارا هــذا مــا أشــهد بــه وقــد أحضــرت‬\n      ‫املدعيــة كذلــك للشــهادة وأدائهــا ‪ ، ................‬اجلنســية ميامنــار مبوجــب‬\n      ‫اإلقامــة رقــم ………… ويظهــر أن تاريــخ ميــاده هــو ‪1981/01/01‬م‬\n      ‫وبســؤاله عــن معلوماتــه املدنيــة أجــاب قائــا إننــي أســكن يف كيلــو‬\n      ‫أربعــة عشــر يف مدينــة جــدة ومتــزوج وال أوالد لــي وأعمــل يف ســوق‬\n      ‫الصواريــخ يف جــدة واملدعيــة وزوجهــا كانــوا يســكنون معنــا يف احلــي‬\n      ‫وأشــهد بــاهلل العظيــم أن زوج املدعيــة واســمه ‪ .........‬مريــض عــن مــا يزيــد‬\n      ‫عــن أربعــة أعــوام مغمــى عليــه وقــد زرتــه يف املستشــفى هــذا مــا أشــهد‬\n      ‫بــه وقــد أحضــرت املدعيــة كذلــك للشــهادة وأدائهــا كال مــن ‪.........‬‬\n      ‫‪ ،‬بنجالديشــي اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬و‪ ، ..........‬اجلنســية‬\n      ‫ميامنــار مبوجــب اإلقامــة رقــم ……‪ .‬وشــهد كل واحــد منهمــا مبفــرده‬\n      ‫أن كال مــن ‪ .......‬و‪ ............‬عــدول ومقبولــن الشــهادة فبنــاءا علــى مــا‬\n      ‫تقــدم مــن الدعــوى وحيــث أن املدعيــة قــد ادعــت مــرض زوجهــا مرضــا‬\n      ‫مزمنــا وتضررهــا مــن ذلــك حيــث أنــه قــد بقــي مــدة طويلــة وطلبهــا فســخ‬\n      ‫النــكاح وحيــث قــد ورد التقريــر الطبــي يشــهد بصحــة مــا جــاء يف‬\n      ‫دعــوى املدعيــة مــن مــرض زوجهــا ملــدة طويلــة وحيــث أن املدعيــة كذلــك‬\n      ‫قــد أحضــرت بينــة موصلــة تشــهد لصحــة دعواهــا مــن شــهادة الشــهود‬\n      ‫وحيــث أن املــرض الواقــع علــى زوج املدعيــة يذهــب مقصــد االســتمتاع‬\n      ‫الــذي هــو مــن مقاصــد الــزوج والزوجــة وحيــث أ‪ ،‬يف بقــاء املدعيــة يف‬\n      ‫عصمــة زوجهــا مــع مرضــه ويف هــذه املــدة الطويلــة ضــرر علــى املدعيــة‬\n      ‫وحيــث أن املــرض الواقــع باملدعــى عليــه ممــا يثبــت بــه اخليــار للمدعيــة‬\n\n\n‫‪327‬‬\n\f‫قــال يف كشــاف القنــاع ( ويثبــت اخليــار يف فســخ النــكاح بجــذام أو‬\n‫بــرص أو جنــون ولــو أفــاق أحيانــا ألن النفــس ال تســكن إلــى مــن هــذه‬\n‫حالــه ) (‪ )404/11‬وحيــث أن الضــرر يــزال يف الشــريعة بقــول اهلل تعالــى‬\n‫( وال تضاروهــن لتذهبــوا ببعــض مــا أتيتموهــن) وقــول النبــي صلــى اهلل‬\n‫عليــه وســلم ( ال ضــرر وال ضــرار ) وحيــث أن الواقــع مــن خــال مــا دون‬\n‫أعــاه يظهــر أنــه يتعــذر تبليــغ املدعــى عليــه باحلكــم جلميــع ما تقــدم فقد‬\n‫فســخت نــكاح املدعيــة ‪ .............‬مــن زوجهــا ‪ ............‬وبذلــك حكمــت‬\n‫وأفهمــت املدعيــة بــأن عليهــا العــدة الشــرعية حســب حالهــا وأنهــا بانــت‬\n‫مــن زوجهــا بينونــة صغــرى ال حتــل لــه إال مبهــر وعقــد جديديــن وبرضاها‬\n‫كمــا أفهمتهــا بأنهــا ال تتــزوج حتــى يكتســب احلكــم الصفــة القطعيــة‬\n‫وأمــرت بالتهميــش علــى عقــد النــكاح مبــا انتهــى إليــه الطرفــان بعــد‬\n‫تصديــق احلكــم مــن محكمــة االســتئناف وبعثــه إلــى مرجعــه لنقلــه يف‬\n‫ســجله وأمــرت برفــع كامــل أوراق املعاملــة إلــى محكمــة االســتئناف‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                       ‫حــرر يف ‪1434/6/7‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 33/701310‬وتاريــخ‬\n‫‪1434/07/11‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪ 33/701310‬وتاريــخ‬\n‫‪1434/07/15‬ه ـ واملصدقــة مــن الدائــرة الثالثــة لألحــوال الشــخصية‬\n‫واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف‬\n‫مبكــة املكرمــة بالقــرار الصــادر مــن أصحــاب الفضيلــة قضــاة‬\n‫محكمــة االســتئناف رقــم ‪ 34262527‬وتاريــخ ‪1434/07/09‬ه ـ‬\n‫املتضمــن مــا نصــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه تقــرر املوافقــة‬\n\n\n                                                                                     ‫‪328‬‬\n\f      ‫علــى احلكــم بفســخ النــكاح مالحظــة التنبيــه املرفــق وبــاهلل التوفيــق‬\n      ‫‪ .‬أ‪.‬ه ـ ‪ ،‬قاضــي اســتئناف ختــم وتوقيــع ‪ ...............‬وقاضــي اســتئناف‬\n      ‫ختــم وتوقيــع ‪ .............‬ورئيــس الدائــرة ختــم وتوقيــع ‪ ، ..........‬عليــه فقــد‬\n      ‫أمــرت بإحلــاق ذلــك بالضبــط وســجله وبــاهلل التوفيــق وصلــى اهلل علــى‬\n         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/07/23‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n      ‫مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جــده املســاعد برقــم ‪ 33/701310‬وتاريــخ‬\n      ‫‪1434/7/2‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪...........‬‬\n      ‫القاضــي باحملكمــة العامــة مبحافظــة جــده برقــم ‪ 34234714‬وتاريــخ‬\n      ‫‪1434/6/7‬ه ـ ‪ ،‬املتضمــن دعــوى املــرأة ‪ ........‬بنقاليــه اجلنســية ضــد‬\n      ‫‪ ...........‬اجلنســية يف فســخ نكاحهــا مــن املدعــى عليــه ‪ ،‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه ‪ ،‬تقــررت املوافقــة علــى احلكــم بفســخ النــكاح ‪ ،‬مــع‬\n      ‫مالحظــة التنبيــه املرفــق ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                          ‫وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":323,"source_page_end":329,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1d78ca5b527518b420e6acb14577a09021be3cbcff7901d4030201b1c26ae0f7","normalized_text_hash":"ef0830d12e1f3ceb3fa7161a513255ae8d7d31f5877f419b4717c3e5cc756d94","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p323-34234714"},{"id":"ed650b08-6362-58a0-8cde-6220d6a9e0a1","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة الفسخ بعد الدخول لطروء إعاقة عقلية على الزوج -إنكار ولي الزوج اإلعاقة العقلية -صك الوالية مثبت به اإلعاقة العقلية -ما قرره األطباء من التخلف العقلي للزوج -اجلنون عيب يثبت به اخليار -اخليار يثبت بحدوث العيب بعد العقد ولو بعد الدخول -احلكم بفسخ نكاح املدعية من زوجها با","document_number":"3457561","case_number":"33406385","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/8","year":"1434","subject":"فسخ نكاح -طلب الزوجة الفسخ بعد الدخول لطروء إعاقة عقلية على الزوج -إنكار ولي الزوج اإلعاقة العقلية -صك الوالية مثبت به اإلعاقة العقلية -ما قرره األطباء من التخلف العقلي للزوج -اجلنون عيب يثبت به اخليار -اخليار يثبت بحدوث العيب بعد العقد ولو بعد الدخول -احلكم بفسخ نكاح املدعية من زوجها با","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫تاريخه‪1434/3/8 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3457561 :‬‬\n                   ‫َر ْق ُم الدعوى‪33406385 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3522928‬تاريخه‪1434/5/25:‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬طلــب الزوجــة الفســخ بعــد الدخــول لطــروء إعاقــة عقليــة‬\n‫علــى الــزوج ‪ -‬إنــكار ولــي الــزوج اإلعاقــة العقليــة ‪ -‬صــك الواليــة مثبــت‬\n‫بــه اإلعاقــة العقليــة ‪ -‬مــا قــرره األطبــاء مــن التخلــف العقلــي للــزوج‬\n‫‪ -‬اجلنــون عيــب يثبــت بــه اخليــار ‪ -‬اخليــار يثبــت بحــدوث العيــب بعــد‬\n‫العقــد ولــو بعــد الدخــول ‪ -‬احلكــم بفســخ نــكاح املدعيــة مــن زوجهــا بــا‬\n                                                                       ‫عــوض ‪.‬‬\n\n\n\n\n                   ‫‪ .1‬قوله صلى اهلل عليه وآله وسلم (ال ضرر وال ضرار)‪.‬‬\n‫‪ .2‬مــا نــص عليــه الفقهــاء مــن أن اجلنــون عيــب يثبــت بــه اخليــار‪ .‬انظــر‬\n                                                     ‫كشــاف القناع ‪405/11‬‬\n‫‪ .3‬مــا قــرره الفقهــاء مــن ثبــوت اخليــار بحــدوث العيــب بعــد العقــد ولــو‬\n‫بعــد الدخــول وأن الــزوج ال يرجــع باملهــر‪ .‬انظــر كشــاف القناع ‪409/11‬‬\n\n\n\n\n‫ادعــت املدعيــة علــى املدعــى عليــه أنــه تزوجهــا وأجنبــت منــه ثالثــة‬\n‫أوالد‪ ،‬وأنــه أصيــب بحــادث مــروري ممــا أدى إلــى إصابتــه بإعاقــة‬\n‫عقليــة وجســمية ‪ ،‬وأنهــا صبــرت عليــه ولكنهــا تعبــت ‪ ،‬ولــم تعــد تطيــق‬\n‫العيــش معــه‪ ،‬وطلبــت فســخ نكاحهــا منــه ‪ ،‬حضــر حلضــور املدعيــة‬\n\n                                                                                    ‫‪330‬‬\n\f      ‫الولــي الشــرعي علــى املدعــى عليــه مبوجــب صــك الواليــة الصــادر مــن‬\n      ‫احملكمــة برقــم ‪ ....‬يف ‪ ....‬وبعــرض دعــوى املدعيــة عليــه‪ ،‬صــادق عليها‪،‬‬\n      ‫ســوى مــا ذكرتــه أنــه مصــاب بإعاقــة عقليــة وذكــر أن الصحيــح أنــه‬\n      ‫مصــاب بإعاقــة جســمية وصعوبــة يف النطــق وأنــك إذا ســألته ســؤا ًال‬\n      ‫يجيــب إجابــة صحيحــة ‪ ،‬وقــرر أنــه ال مانــع لديــه مبــا طلبتــه املدعيــة ‪،‬‬\n      ‫ا أو عيب ـ ًا ‪،‬‬\n                    ‫املدعــى عليــه بالواليــة أنكــر أن يكــون يف عقــل ابنــه خل ـ ً‬\n      ‫وبعــد االطــاع علــى صــك الواليــة وجــد يتضمــن إنهاء املنهي وهــو املدعى‬\n      ‫عليــه بالواليــة بطلــب الواليــة علــى ابنــه لكونــه مصــاب بحالــة التخلــف‬\n      ‫العقلــي ‪ ،‬أهــل اخلبــرة مــن األطبــاء قــرروا أن املولــى عليــه مصــاب بحالــة‬\n      ‫التخلــف العقلــي وهــو غيــر مــدرك ملــا يــدور حولــه وال يســتطيع إدارة‬\n      ‫شــؤونه بنفســه ويحتــاج إلــى ولــي ‪ ،‬مــا نــص عليــه الفقهــاء مــن أن اجلنــون‬\n      ‫عيــب يثبــت بــه اخليــار ‪ ،‬وأن اخليــار يثبــت بحــدوث العيــب بعــد العقــد ولــو‬\n      ‫بعــد الدخــول وأن الــزوج ال يرجــع باملهــر ‪ ،‬بقــاء الزوجــة جبــر ًا مــع زوجهــا‬\n      ‫وهــو علــى هــذه احلــال فيــه ضــرر ظاهــر عليهــا ولقولــه صلــى اهلل عليــه‬\n      ‫وآلــه وســلم (ال ضــرر وال ضــرار) ‪ ،‬لــذا مت احلكــم بفســخ نــكاح املدعيــة‬\n      ‫مــن زوجهــا بــا عــوض ‪ ،‬بعــرض احلكــم علــى الطرفــن قــررا القناعــة‬\n      ‫‪ ،‬مت رفــع احلكــم حملكمــة االســتئناف لتدقيقــه نظــر ًا حلــق القاصــر‬\n      ‫والتهميــش علــى عقــد النــكاح بذلــك بعــد اكتســاب احلكــم القطعيــة‬\n      ‫وجــرى إفهــام املدعيــة بــأن عليهــا العــدة الشــرعية‪ ،‬وأن ال تتــزوج حتــى‬\n      ‫يكتســب احلكــم القطعيــة ‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف‬\n                                                                   ‫متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫‪331‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وآلــه وصحبــه أمــا‬\n‫العامــة مبحافظة القطيف‬  ‫ّ‬    ‫بعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة برقــم‬\n‫‪ 331132758‬يف ‪ 1433/6/16‬هـ يف يوم الثالثاء املوافق‪1433/7/1‬هـ‬\n‫افتتحــت اجللســة اخلاصــة بدعــوى (‪ )........‬ضــد (‪ )........‬وفيهــا حضــرت‬\n‫(‪ )........‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .........‬برفقــة‬\n‫املعــرف بهــا أخوهــا (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )........‬ولــم يحضــر املدعــى عليــه وال مــن ميثلــه ولــم يقــدم أي عــذر‬\n‫هــذا وقــد وردتنــا إفــادة قســم احملضريــن باحملكمة برقــم ‪331132758‬‬\n‫يف ‪1433/6/19‬ه ـ املتضمنــة تبلــغ املدعــى عليــه لغيــر شــخصه ومســتلم‬\n‫التبليــغ ‪ ........‬أخــو املدعــى عليــه الســاكن معــه أ‪ .‬ه ـ ‪ .‬وقــررت املدعيــة‬\n‫بــأن املدعــى عليــه لــن يحضــر يف هــذا اليــوم وطلبــت رفــع اجللســة ليــوم‬\n‫آخــر فأجبتهــا لطلبهــا ورفعــت اجللســة مــن أجــل إعــادة إبــاغ املدعــى‬\n‫عليــه ويف جلســة أخــرى حضــرت املدعيــة برفقــة املعــرف بهــا أخوهــا ولــم‬\n‫يحضــر املدعــى عليــه وال مــن ميثلــه ولــم يقــدم أي عــذر وقــد وردتنــا إفــادة‬\n‫قســم احملضريــن باحملكمــة برقــم ‪ 331240531‬يف ‪1433/7/2‬ه ـ‬\n‫املتضمنــة تبلــغ املدعــى عليــه لغيــر شــخصه ومســتلم التبليــغ ‪...........‬‬\n‫والــد املدعــى عليــه الســاكن معــه أ‪ .‬ه ـ ‪ .‬وبســؤال املدعيــة عــن دعواهــا‬\n‫قالــت‪ :‬إن املدعــى عليــه زوجــي تزوجنــي أكثــر مــن خمســة عشــر ســنة‬\n‫تقريبـ ًا وقــد أجنبــت منــه ثالثــة أوالد وهــم كمــا يلــي‪ ........ -1 :‬املولــودة‬\n‫بتاريــخ ‪1418/3/7‬ه ـ ‪ ......-2‬املولــود بتاريــخ ‪1420/11/1‬هــ‪.......... -3 .‬‬\n\n                                                                                        ‫‪332‬‬\n\f      ‫املولــود بتاريــخ ‪1426/12/17‬ه ـ وقــد أصيــب بحــادث مــروري بتاريــخ‬\n      ‫‪1429/3/1‬ه ـ ‪ .‬ممــا أدى إلــى إصابتــه بإعاقــة عقليــة وجســمية وقــد‬\n      ‫صبــرت عليــه ولكنــي تعبــت ولــم أعــد أطيــق العيــش معــه لــذا أطلــب‬\n      ‫فســخ نكاحــي منــه هــذه دعــواي ‪ .‬هــذا ونظــر ًا لعــدم حضــور املدعــى‬\n      ‫عليــه رفعــت اجللســة مــن أجــل إعــادة إبالغــه عــن طريــق احملافظــة‬\n      ‫وإحضــاره أو مــن ينــوب عنــه بالقــوة ويف جلســة أخــرى حضــرت املدعيــة‬\n      ‫برفقــة والدهــا املعــرف بهــا ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...........‬وحضــر حلضورهــا ‪ ........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدني رقم ‪ ........‬الولي الشــرعي على املدعى عليه عبداللطيف‬\n      ‫مبوجــب صــك الواليــة الصــادر مــن هــذه احملكمــة برقــم ‪ 33431675‬يف‬\n      ‫‪1433/10/21‬ه ـ واملتضمــن إقامــة ‪ ..........‬والــد املدعــى عليــه وليـ ًا عليــه‬\n      ‫ال ‪ :‬ما ذكرته‬      ‫وبعــرض دعــوى املدعيــة علــى ولــي املدعى عليه أجــاب قائ ً‬\n      ‫املدعيــة يف دعواهــا صحيــح ســوى أنــه مصــاب بإعاقــة عقليــة والصحيــح‬\n      ‫أنــه مصــاب بإعاقــة جســمية وصعوبــة يف النطق ولكن إذا ســألته ســؤا ًال‬\n      ‫يجيــب إجابــة صحيحــة وال مانــع لــدي مبــا طلبتــه املدعيــة ‪ .‬هكذا أجاب‬\n      ‫‪ .‬ثــم طلبــت وثيقــة عقــد النــكاح فاســتعدت املدعيــة بإحضــاره يف اجللســة‬\n      ‫القادمــة ثــم رفعــت اجللســة ويف جلســة أخــرى حضــرت املدعيــة برفقــة‬\n      ‫ـاء علــى مــا‬\n                   ‫والدهــا وحضــر حلضورهــا املدعــى عليــه بالواليــة ‪ ............‬فبنـ ً‬\n      ‫تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه بالواليــة أنكــر أن‬\n      ‫ا أو عيبـ ًا ‪ ،‬وبعــد االطــاع علــى صــك الواليــة‬        ‫يكــون يف عقــل ابنــه خلـ ً‬\n      ‫واملتضمــن إنهــاء املنهــي وهــو املدعــى عليــه بالواليــة بطلــب الواليــة علــى‬\n      ‫ابنــه لكونــه مصــاب بحالــة التخلــف العقلــي ‪ .‬ومبــا أن أهــل اخلبــرة مــن‬\n      ‫األطبــاء قــرروا أن ‪...........‬املولــى عليــه مصــاب بحالــة التخلــف العقلــي‬\n\n\n‫‪333‬‬\n\f‫وهــو غيــر مــدرك ملــا يــدور حولــه وال يســتطيع إدارة شــؤونه بنفســه‬\n‫ويحتــاج إلــى ولــي ‪ .‬وملــا نــص عليــه الفقهــاء مــن أن اجلنــون عيــب يثبــت‬\n‫بــه اخليــار ‪ -‬انظــر كشــاف القنــاع ‪ - 405/11‬وملــا قــرروه أيض ـ ًا مــن‬\n‫ثبــوت اخليــار بحــدوث العيــب بعــد العقــد ولــو بعــد الدخــول وأن الــزوج‬\n‫ال يرجــع باملهــر ‪ -‬انظــر كشــاف القنــاع ‪ - 409/11‬وألن بقــاء الزوجــة‬\n‫جبــر ًا مــع زوجهــا وهــو علــى هــذه احلــال فيــه ضــرر ظاهــر عليهــا ولقولــه‬\n‫صلــى اهلل عليــه وآلــه وســلم (( ال ضــرر وال ضــرار )) لذلــك كلــه فقــد‬\n‫فســخت نــكاح املدعيــة ‪ ...........‬مــن زوجهــا ‪ ...........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ...........‬مجان ـ ًا وبــه حكمــت وبعــرض‬\n‫احلكــم علــى الطرفــن قــررا القناعــة بــه عليــه فقــد قــررت رفــع احلكــم‬\n‫حملكمــة االســتئناف لتدقيقــه نظــر ًا حلــق القاصــر والتهميــش علــى عقــد‬\n‫النــكاح بذلــك بعــد اكتســاب احلكــم القطعيــة وأفهمــت املدعيــة بــأن‬\n‫عليهــا العــدة الشــرعية وهــي حيضــة واحــدة وأن ال تتــزوج حتــى يكتســب‬\n‫احلكــم القطعيــة ففهمــت ذلــك حــرر يف ‪1433/11/21‬ه ـ وصلــى اهلل‬\n                                 ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلــى آلــه‬\n‫ـاء‬\n‫وصحبــه أمــا بعــد يف يــوم الثالثــاء ‪1434/6/13‬ه ـ فتحــت اجللســة بنـ ً‬\n‫علــى ورود املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب‬\n‫كتــاب ســماحة رئيســها رقــم ‪ 34790604‬يف ‪1434/5/29‬ه ـ وبرفقهــا‬\n‫قــرار أصحــاب الفضيلــة قضــاة دائــرة األحــوال الشــخصية الثانيــة رقــم‬\n‫‪/34222009‬ش‪ 2/‬يف ‪1434/5/26‬ه ـ املتضمــن نــص احلاجــة منــه‪:‬‬\n‫بدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن املعاملــة لــم‬\n‫يرفــق بهــا صــورة مصدقــة مــن واليــة ‪ .......‬علــى ابنــه املدعــى عليــه ‪........‬‬\n\n\n                                                                                         ‫‪334‬‬\n\f      ‫والبــد مــن ذلــك فعلــى فضيلتــه مالحظــة مــا أشــير إليــه وإحلاق مــا يجد يف‬\n      ‫الصــك وضبطــه وســجله ومــن ثــم إعــادة املعاملــة إلكمــال ال زمهــا واهلل‬\n      ‫املوفــق قاضــي اســتئناف ختمــه وتوقيعــه ‪ ..........‬قاضــي اســتئناف ختمــه‬\n      ‫وتوقيعــه ‪ .........‬رئيــس الدائــرة ختمــه وتوقيعــه ‪ .......‬أ‪.‬ه ـ ‪ .‬عليــه أجيــب‬\n      ‫أصحــاب الفضيلــة بأنــه مت إرفــاق املطلــوب شــاكر ًا ألصحــاب الفضيلــة‬\n      ‫مــا تفضلــوا علــي وقــررت إعــادة كامــل املعاملــة حملكمــة االســتئناف‬\n           ‫لتدقيقــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n      ‫ـاء علــى ورود‬‫أمــا بعــد يف يــوم الثالثــاء ‪1434/8/9‬ه ـ فتحــت اجللســة بنـ ً‬\n      ‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية بكتــاب ســماحة‬\n      ‫رئيسها رقم ‪ 34/1567036‬يف ‪1434/7/22‬هـ املرفق به قرار أصحاب‬\n      ‫الفضيلــة قضــاة دائــرة األحــوال الشــخصية الثانيــة رقــم ‪ 34269840‬يف‬\n      ‫‪1434/7/16‬ه ـ املتضمــن نــص احلاجــة منــه‪ ( :‬باالطــاع علــى مــا أجــاب‬\n      ‫بــه فضيلــة القاضــي وأحلقــه بالصــك جواب ـ ًا علــى قرارنــا الســابق رقــم‬\n      ‫‪/34222009‬ش‪/2‬ب يف ‪1434/5/26‬ه ـ لوحــظ أن فضيلــة القاضــي لم‬\n      ‫يــدون قــرار محكمــة االســتئناف املتضمــن املالحظــة علــى فضيلتــه ولــم‬\n      ‫يجــب عليهــا فعلــى فضيلتــه مالحظــة مــا أشــير إليــه وإحلــاق مــا يجــد يف‬\n      ‫الصــك وضبطــه وســجله ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا واهلل‬\n      ‫املوفــق ) ‪ .‬أ ه ـ ‪ .‬قاضــي اســتئناف ‪........‬ختمــه وتوقيعــه قاضــي اســتئناف‬\n      ‫‪ ...........‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ........‬ختمــه وتوقيعــه عليــه أجيــب‬\n      ‫أصحــاب الفضيلــة بأنــه مت إكمــال املطلــوب يف قرارهــم املشــار إليــه‬\n      ‫أعــاه ‪ .‬شــاكر ًا ألصحــاب الفضيلــة مــا تفضلــوا بــه وأســأل اهلل لــي‬\n      ‫ولهــم معرفــة احلــق واتباعــه حــرر يف ‪1434/8/9‬ه ـ ‪ ،‬وصلــى اهلل علــى‬\n\n\n‫‪335‬‬\n\f                                   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n‫الشــخصية الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/2303389‬ش‪ 2‬وتاريــخ‬\n‫‪1434/10/13‬ه ـ والــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫مبحافظــة القطيــف برقــم ‪ 34/5167036‬وتاريــخ ‪1434/9/23‬ه ـ‬\n‫املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي بها الشــيخ ‪ ......‬املســجل‬\n‫برقــم ‪ 3457561‬وتاريــخ ‪1434/3/8‬ه ـ اخلــاص بدعــوى ‪ ..........‬ضــد‬\n‫‪ ...........‬يف قضيــة فســخ نــكاح وباالطــاع علــى مــا أجــاب بــه فضيلــة‬\n‫القاضــي وأحلقــه بالصــك جواب ـ ًا علــى قــراري الدائــرة الســابقني رقــم‬\n‫‪/34222009‬ش‪/2‬ب يف ‪1434/5/26‬ه ـ ورقــم ‪/34269840‬ش‪/2‬ب‬\n‫يف ‪1434/7/16‬ه ـ قررنــا أنــه لــم يظهــر مــا يوجــب النقــض بعــد اإلجــراء‬\n‫األخيــر‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                    ‫حــرر يف ‪1435/1/22‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪336‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":330,"source_page_end":336,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"18053af6b69d91d739514f21822633ef70dd8104f84443ad0472b6fbd375fbe1","normalized_text_hash":"b58da8e1892ce5acddabe29872b397a36daca3a1b926c5e840764d70c260242b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p330-3457561"},{"id":"b363bd52-8bc5-5d7d-80c2-cb8c4239c588","document_type":"judgment","category":"judicial","subcategory":"general","title":"خلع -مطالبة الزوجة باخللع مقابل رد املهر -امتناع الزوج من املخالعة -املطالبة بفسخ النكاح -بقاء الزوجة معلقة مع وجود الشقاق من الضرر الواجب إزالته شرع ا -من وجب عليه شيء وامتنع عن أدائه استوفاه عنه احلاكم -احلكم بفسخ النكاح على عوض -ال عبرة بالطاق بعد صدور احلكم بالفسخ -إفهام الطرفن باآلثار املترتبة على فسخ النكاح .","document_number":"33422293","case_number":"33431124","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/10/10","year":"1434","subject":"خلع -مطالبة الزوجة باخللع مقابل رد املهر -امتناع الزوج من املخالعة -املطالبة بفسخ النكاح -بقاء الزوجة معلقة مع وجود الشقاق من الضرر الواجب إزالته شرع ا -من وجب عليه شيء وامتنع عن أدائه استوفاه عنه احلاكم -احلكم بفسخ النكاح على عوض -ال عبرة بالطاق بعد صدور احلكم بالفسخ -إفهام الطرفن باآلثار املترتبة على فسخ النكاح .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1432/10/10 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33422293 :‬‬\n                          ‫َر ْق ُم الدعوى‪33431124 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3429503‬تاريخه‪1434/2/4 :‬هـ‬\n\n\n       ‫خلــع ‪ -‬مطالبــة الزوجــة باخللــع مقابــل رد املهــر ‪ -‬امتنــاع الــزوج مــن‬\n       ‫املخالعــة ‪ -‬املطالبــة بفســخ النــكاح ‪ -‬بقــاء الزوجــة معلقــة مــع وجــود‬\n       ‫الشــقاق مــن الضــرر الواجــب إزالتــه شــرع ًا ‪ -‬مــن وجــب عليــه شــيء‬\n       ‫وامتنــع عــن أدائــه اســتوفاه عنــه احلاكــم ‪ -‬احلكــم بفســخ النــكاح‬\n       ‫علــى عــوض ‪ -‬ال عبــرة بالطــاق بعــد صــدور احلكــم بالفســخ ‪ -‬إفهــام‬\n                                 ‫الطرفــن باآلثــار املترتبــة علــى فســخ النــكاح ‪.‬‬\n\n\n\n       ‫‪ -1‬قولــه تعالــى (فــإن خفتــم شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه‬\n                      ‫وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا)‪.‬‬\n                            ‫‪ -2‬قوله تعالى (وإن يتفرقا يغن اهلل كال من سعته)‪.‬‬\n                                  ‫‪ -3‬قوله تعالى (وال تضاروهن لتضيقوا عليهن)‪.‬‬\n                                ‫‪ -4‬قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)‪.‬‬\n       ‫‪ -5‬قولــه صلــى اهلل عليــه وســلم يف قصــة ثابــت بــن قيــس (خــذ احلديقــة‬\n                                                   ‫وطلقهــا تطليقــة) رواه البخاري‪.‬‬\n                            ‫‪ -6‬املادة ‪ 176‬واملادة ‪ 178‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n       ‫ادعــت املدعيــة علــى املدعــى عليــه بأنــه قــد تزوجهــا ودخــل بهــا الدخــول‬\n       ‫الشــرعي علــى صــداق قــدره ســتون ألــف ريــال وقــد حصــل بينهمــا نــزاع‬\n‫‪337‬‬\n\f‫ذهبــت علــى إثــره إلــى بيــت أهلهــا منــذ شــهر شــعبان ‪1429‬ه ـ وحتــى‬\n‫هــذا اليــوم وقــد كرهتــه وال تطيــق العيــش معــه وتطلــب اخللــع منــه ورد‬\n‫مهــره لــه هكــذا ادعــت ‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الــزواج‬\n‫والدخــول بهــا وأنكــر وجــود نــزاع بينهمــا وأن ســبب خروجهــا مــن‬\n‫البيــت هــو زواجــه بثانيــة ويرفــض اخللــع ويطلــب رجوعهــا لبيــت الزوجيــة‬\n‫‪ ،‬جــرى عــرض الصلــح علــى الطرفــن لكــن املدعيــة كرهــت املدعــى‬\n‫عليــه ورفضــت الرجــوع معــه ‪ ،‬اســتعد املدعــى عليــه باخللــع مقابــل تنــازل‬\n‫املدعيــة عــن احلضانــة ورفضــت املدعيــة ذلــك ‪ ،‬أقــر املدعــى عليــه ببقــاء‬\n‫املدعيــة ببيــت أهلهــا أربــع ســنوات ‪ ،‬ولقولــه تعالــى (فــإن خفتــم شــقاق‬\n‫بينهمــا فابعثــوا حكمــا مــن أهلــه وحكمــا مــن أهلهــا إن يريــدا إصالحــا‬\n‫يوفــق اهلل بينهمــا ) فاختــار كل واحــد منهمــا حكم ـ ًا لــه واســتعدا‬\n‫بإحضــار احلكمــن يف اجللســة القادمــة ‪ ،‬حضــر حكــم الزوجــة ولــم‬\n‫يحضــر حكــم الــزوج ‪ ،‬جــرى محاولــة الصلــح بينهمــا ولــم يصطلحــا ‪،‬‬\n‫طلــب مــن املدعــى عليــه طــاق زوجتــه أو مخالعتهــا بعــوض وتذكيــره‬\n‫بقــول اهلل جــل وعــا (وإن يتفرقــا يغــن اهلل كال مــن ســعته ) فرفــض‬\n‫ذلــك ‪ ،‬ولتعــذر الصلــح بــن الطرفــن وإلقــرار املدعــى عليــه ببقــاء زوجتــه‬\n‫أربــع ســنوات خــارج بيتــه وحيــث اســتعدت املدعيــة بدفــع كامــل املهــر‬\n‫وقــدره ســتون ألــف ريــال ‪ ،‬وألن بقــاء الزوجــة هــذه الفتــرة فيــه ضــرر‬\n‫عليهــا ولقولــه تعالــى (وال تضاروهــن لتضيقــوا عليهــن ) ولقولــه صلــى‬\n‫اهلل عليــه وســلم (ال ضــرر وال ضرار)وقــد شــرع رفــع الضــرر بالفرقــة‬\n‫بــن الزوجــن وألن الشــقاق حاصــل بينهمــا ممــا تعــذر التحكيــم بــن‬\n‫الطرفــن ولقولــه صلــى اهلل عليــه وســلم يف قصــة ثابــت بــن قيــس (خــذ‬\n‫احلديقــة وطلقهــا تطليقــة) رواه البخــاري وألن الــزوج امتنــع مــن الطــاق‬\n\n\n                                                                                   ‫‪338‬‬\n\f      ‫وألن مــن وجــب عليــه شــيء وامتنــع عــن أدائــه اســتوفاه عنــه احلاكــم ‪،‬‬\n      ‫ملــا تقــدم جــرى فســخ نــكاح املدعيــة مــن زوجهــا املدعــى عليــه علــى مبلــغ‬\n      ‫وقــدره ســتون ألــف ريــال تســلمه املدعيــة للمدعــى عليــه ‪ ،‬إفهــام املدعــى‬\n      ‫عليــه بــأن زوجتــه قــد بانــت منــه بينونــة صغــرى ال حتــل لــه إال بعقــد‬\n      ‫جديــد ومهــر جديــد كمــا أفهمــت املدعيــة بــأن ال تســتقبل اخلطــاب‬\n      ‫إال بعــد اكتســاب احلكــم القطعيــة وانتهــاء العــدة الشــرعية ‪ ،‬قنعــت‬\n      ‫املدعيــة باحلكــم واعتــرض املدعــى عليــه ‪ ،‬قــدم املدعــى عليــه يف اليــوم‬\n      ‫التالــي للحكــم ورقــة إقــرار بتطليقــه زوجتــه ‪ ،‬أفهمــه حاكــم القضيــة‬\n      ‫بــأن إقــراره بالطــاق ال يؤثــر علــى ماحكــم بــه ‪ ،‬صــدق احلكــم مــن‬\n         ‫دائــرة األحــوال الشــخصية األولــى مبحكمــة االســتئناف بالريــاض ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي القائــم بالعمــل يف‬\n      ‫املكتــب القضائــي احلــادي والثالثــن باحملكمــة العامــة بالريــاض بنــاء‬\n      ‫علــى تكليــف فضيلــة رئيــس احملكمــة املســاعد رقــم ‪ 331421333‬يف‬\n      ‫‪1433/08/21‬ه ـ وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بالريــاض (‪ )........‬املســاعد برقــم ‪33431124‬‬\n      ‫وتاريــخ ‪ 1433/06/29‬ه ـ املقيــدة باحملكمــة برقــم ‪33748263‬‬\n      ‫وتاريــخ ‪ 1433/04/20‬ه ـ ففــي يــوم الســبت املوافــق‪1433/08/24‬‬\n      ‫ه ـ افتتحــت اجللســة وفيهــا حضــرت (‪ )........‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ )........‬واملعــرف بهــا مــن قبــل أخيهــا احلاضــر معهــا‬\n      ‫(‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬كمــا‬\n      ‫حضــر (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)........‬‬\n‫‪339‬‬\n\f‫وكيلهــا الشــرعي مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل عرقــة‬\n‫رقــم ‪ 511002005798‬وتاريــخ ‪1431/12/24‬ه ـ واملتضمــن لــه (حــق‬\n‫املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة الدعــاوى وســماع‬\n‫الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح وطلــب قبــول‬\n‫احلكــم واالعتــراض عليــه وطلــب متييــزه ) كمــا حضــر ‪ ...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وقــرر قائــا إننــي وكيــل عــن ‪...‬‬\n‫وبســؤاله عــن أســاس الوكالــة أجــاب قائــا ســأحضرها اجللســة القادمة‬\n‫ويف يــوم األربعــاء املوافــق ‪ 1433/08/28‬ه ـ افتتحــت اجللســة وفيهــا‬\n‫حضــرت املدعيــة ومعرفهــا ووكيلهــا احلاضــرون يف اجللســة الســابقة‬\n‫كمــا حضــر املدعــى عليــه‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ...‬وبســؤال املدعيــة عــن دعواهــا أجابــت قائلــة إن املدعــى عليــه‬\n‫احلاضــر هــو زوجــي وقــد تزوجنــي ودخــل بــي الدخــول الشــرعي مبوجــب‬\n‫العقــد الصــادر مــن محكمــة الضمــان و األنكحــة بالريــاض برقــم ‪26‬‬\n‫وتاريــخ ‪1417/5/1‬ه ـ علــى مهــر وقــدره ســتون ألــف ريــال واجنبــت لــه‬\n‫علــى فــراش الزوجيــة ثالثــة أوالد وهــم ‪ ...‬املولــودة يف ‪1419/2/11‬ه ـ‬\n‫و‪ ...‬املولــود يف ‪1422/4/24‬ه ـ و‪ ...‬املولــود يف ‪1425/4/10‬ه ـ وقــد‬\n‫حصــل بيننــا نــزاع ذهبــت علــى إثــره إلــى بيــت أهلــي منــذ شــهر شــعبان‬\n‫‪1429‬ه ـ وحتــى هــذا اليــوم وقــد كرهتــه وال أطيــق العيــش معــه وأطلــب‬\n‫اخللــع منــه ورد مهــره لــه هكــذا ادعــت وبعــرض ذلــك علــى املدعــى عليــه‬\n‫أجــاب قائــا مــا ذكرتــه املدعيــة مــن زواجــي بهــا ودخولــي بهــا الدخــول‬\n‫الشــرعي وإجنابهــا لــي األوالد الثالثــة فكلــه صحيــح وأمــا النــزاع فــا‬\n‫صحــة لــه وســبب خروجهــا مــن البيــت هــو زواجــي بثانيــة وأنــا أرفــض‬\n‫اخللــع وأطلــب رجوعهــا لبيــت الزوجيــة هكــذا أجــاب هــذا كمــا جــرى‬\n\n\n                                                                                    ‫‪340‬‬\n\f      ‫اإلطــاع علــى أســاس عقــد النــكاح فوجدتــه كمــا ذكــرت املدعيــة‬\n      ‫وبعــرض الصلــح علــى الطرفــن أبــدى الــزوج اســتعداده للصلــح وقبولــه‬\n      ‫رجــوع الزوجــة والعفــو عمــا ســلف وبعــرض ذلــك علــى املدعيــة أجابــت‬\n      ‫قائلــة أنــا ال أقبــل بالصلــح وأرفــض الرجــوع إليــه وقــد كرهتــه وليــس‬\n      ‫لــدي أكثــر مــن ذلــك وأطلــب اخللــع منــه هكــذا أجابــت وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه أجــاب قائــا إننــي أعــرض عليهــا بقائهــا علــى ذمتــي‬\n      ‫مقابــل ســكنها هــي وأوالدي يف بيــت خــاص لهــم هكــذا أجاب وبعرض‬\n      ‫ذلــك علــى املدعيــة أجابــت قائلــة غيــر مســتعدة لذلــك هكــذا أجابــت‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا إننــي مســتعد لقبــول‬\n      ‫اخللــع مقابــل تنازلهــا عــن حضانــة األوالد وبعــرض ذلــك علــى املدعيــة‬\n      ‫أجابــت قائلــة ليــس لــدي زيــادة علــى مــا ذكــرت وأطلــب اخللــع منــه وال‬\n      ‫أوافــق علــى جعــل حضانــة األوالد عوضــا علــى اخللــع هكــذا أجابــت‬\n      ‫وبســؤال املدعــى عليــه كــم مكثــت عنــد أهلهــا فقــال إنهــا مكثــت‬\n      ‫أربــع ســنوات هكــذا أجــاب فبنــاء علــى ذلــك ولقولــه تعالــى (فــإن خفتــم‬\n      ‫شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه وحكمــا مــن أهلهــا إن يريــدا‬\n      ‫إصالحــا يوفــق اهلل بينهمــا ) فقــد ألزمــت الطرفــان بتحديــد حكمــن‬\n      ‫مــن طرفهمــا فأجابــت املدعيــة قائلــه أطلــب أن يكــون احلكــم مــن‬\n      ‫طــريف العــم ‪ ...‬هكــذا أجابــت وبســؤال املدعــى عليــه عــن احلكــم مــن‬\n      ‫طرفــه أجــاب قائــا أطلــب أن يكــون احلكــم مــن طــريف ابــن اخلــال ‪...‬‬\n      ‫هكــذا أجــاب فاســتعد كل واحــد منهمــا بإحضــار احلكــم مــن طرفــه‬\n      ‫يف موعــد اجللســة القادمــة ويف جلســة أخــرى افتتحــت اجللســة الســاعة‬\n      ‫وفيهــا حضــر الطرفــان احلاضــران يف اجللســة الســابقة كمــا حضــر ‪...‬‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ...‬وقــرر قائــا إننــي مســتعد للتحكيــم‬\n\n\n‫‪341‬‬\n\f‫بــن الطرفــن ومحاولــة اإلصــاح هكــذا قــرر وبســؤال املدعــى عليــه‬\n‫عــن احلكــم مــن طرفــه أجــاب قائــا لــم يلتقــي الطرفــان ولــم أفهــم منــك‬\n‫أنــه يحضــر ملوعــد هــذه اجللســة هكــذا قــرر هــذا وقــد جــرى محاولــة‬\n‫اإلصــاح بــن الطرفــن وتذكيرهمــا بــاهلل جــل وعــا وحقــوق بعضهمــا‬\n‫لبعض ومداراة مصلحة أوالدهما وتقوى اهلل يف هذا الشهر الفضيل إال‬\n‫أن محاولــة اإلصــاح قــد تعــذرت كمــا قــرر احلكــم مــن طــرف املدعيــة‬\n‫قائــا إن اإلصــاح متعــذر بــن الطرفــن هكــذا قــرر هــذا وبســؤال‬\n‫املدعــى عليــه هــل قــام برفــع دعــوى انقيــاد وطاعــة علــى املدعيــة فأجــاب‬\n‫قائــا لــم يســبق لــي أن رفعــت دعــوى انقيــاد وطاعــة هكــذا أجــاب عنــد‬\n‫ذلــك طلبــت مــن املدعــى عليــه طــاق زوجتــه وتذكيــره بقــول اهلل جــل‬\n‫وعــا (وإن يتفرقــا يغــن اهلل كال مــن ســعته ) فرفــض ذلــك وبطلــب‬\n‫مخالعــة زوجتــه مقابــل العــوض أجــاب قائــا أرفــض ذلــك فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة ولتعــذر الصلــح بــن الطرفــن وإلقــرار‬\n‫املدعــى عليــه ببقــاء زوجتــه أربــع ســنوات خــارج بيتــه وإلصــرار الزوجــة‬\n‫علــى ذلــك وقــد رفــض الــزوج ذلــك ومبــا أن الزوجــة قــد خرجــت مــن بيتهــا‬\n‫منــذ عــام ‪ 1429‬وحيــث اســتعدت املدعيــة بدفــع كامــل املهــر وقــدره‬\n‫ســتون ألــف ريــال وألن بقــاء الزوجــة هــذه الفتــرة فيــه ضــرر عليهــا ولقولــه‬\n‫تعالــى (وال تضاروهــن لتضيقــوا عليهــن ) ولقولــه صلــى اهلل عليــه وســلم‬\n‫(ال ضــرر وال ضــرار) وقــد شــرع رفــع الضــرر بالفرقــة بــن الزوجــن وألن‬\n‫الشــقاق حاصــل بينهمــا ممــا تعــذر التحكيــم بني الطرفــن ولقوله صلى‬\n‫اهلل عليــه وســلم يف قصــة ثابــت بــن قيــس (خــذ احلديقــة وطلقهــا تطليقــة)‬\n‫رواه البخــاري وألن الــزوج امتنــع مــن الطــاق وألن مــن وجــب عليــه شــي‬\n‫وامتنــع عــن أدائــه اســتوفاه عنــه احلاكــم لذلــك كلــه فقــد فســخت‬\n\n\n                                                                                       ‫‪342‬‬\n\f      ‫نــكاح املدعيــة ‪ ...‬مــن زوجهــا ‪ ...‬علــى مبلــغ وقــدره ســتون ألــف ريــال‬\n      ‫تســلمه املدعيــة للمدعــى عليــه وبذلــك كلــه حكمــت وبعــرض احلكــم‬\n      ‫علــى الطرفــن قنعــت بــه املدعيــة ولــم يقنــع بــه املدعــى عليــه فأفهمته بأن‬\n      ‫لــه أن يتقــدم بالئحــة اعتراضيــة خــال ثالثــن يومــا مــن اســتالمه نســخة‬\n      ‫مــن احلكــم وإن لــم يتقــدم خاللهــا بالئحتــه االعتراضيــة ســقط حقــه يف‬\n      ‫االعتــراض ويكتســب احلكــم القطعيــة كمــا أفهــم املدعــى عليــه بــأن‬\n      ‫عليــه املراجعــة يــوم الســبت بتاريــخ ‪1433/09/09‬ه ـ الســتالم نســخة‬\n      ‫مــن احلكــم هــذا كمــا أفهمــت املدعــى عليــه بــأن زوجتــه ‪ ...‬ال حتــل‬\n      ‫لــه إال بعقــد جديــد ومهــر جديــد كمــا أفهمــت املدعيــة بــأن ال تســتقبل‬\n      ‫اخلطــاب إال بعــد اكتســاب احلكــم القطعيــة وانتهــاء العــدة الشــرعية‬\n      ‫هــذا وقــد ســلمت املدعيــة العــوض املذكــور مبوجــب الشــيك املصــدق‬\n      ‫باســم رئيــس احملكمــة مســحوبا علــى بنــك ‪ ...‬مببلــغ وقــدره ســتون ألــف‬\n      ‫ريــال برقــم ‪ 393697‬يف ‪1432/05/15‬ه ـ كمــا أفهمــت املدعــى عليــه‬\n      ‫باســتالمه وكان ذلــك بحضــور وشــهادة احلاضــر ‪ ...‬واملعــرف بهــا ‪ ...‬ويف‬\n      ‫جلســة أخــرى يف يــوم الســبت املوافــق ‪1433/9/9‬ه ـ افتتحــت اجللســة‬\n      ‫وفيهــا حضــرت املدعيــة ‪ ...‬واملعــرف بهــا مــن قبــل ‪ ...‬واحلكــم مــن طرفهــا‬\n      ‫عمهــا ‪ ...‬وقــد حضــر املدعــى عليــه صبــاح هــذا اليــوم وقــدم إقــرارا‬\n      ‫خطي ـ ًا متضمنــا ( اقــر لفضيلتكــم بأننــي طلقــت زوجتــي ‪ ... /‬طلقــة‬\n      ‫واحــدة رجعيــة شــرعية بقولــه لنــا أنتــي طالــق وهــي تســمع وقــد أخبــرت‬\n      ‫الشــهود وإخوانهــا بذلــك وســأزود مكتبكــم بنســخة مــن صــك الطــاق‬\n      ‫حــال صــدوره خــال يومــن وســأخبر إخوانهــا برقــم الصــك ليســتلموه‬\n      ‫مــع شــيك النفقــة مــن محكمــة األنكحــة واهلل املوفــق املقــر مبــا فيــه ‪...‬‬\n      ‫توقيــع) ولــم يســتلم نســخة مــن احلكــم عليــه فقــد جــرى إفهــام املدعــى‬\n\n\n‫‪343‬‬\n\f‫عليــه بأنــه ال تــزال مــدة االعتــراض ســارية وأنــه ســوف يعامــل مبقتضــى‬\n‫املــادة ‪ 176‬واملــادة ‪ 178‬مــن نظــام املرافعــات الشــرعية وأن إقــراره‬\n‫بالطــاق لــم يؤثــر علــى مــا حكمــت بــه كمــا مت إرفــاق اإلقــرار يف‬\n‫املعاملــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                             ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/09/09‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتمييــز‬\n‫قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف بالرياض‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n‫برقــم ‪ 331793511‬وت ــاريخ ‪1434/1/11‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ... /‬املســجل برقــم ‪ ...‬وتاريــخ‬\n‫‪1432/10/10‬ه ـ اخلــاص بدعــوى ‪ ... /‬ضــد ‪ ... /‬بالوكالــة عــن ‪ ...‬بشــأن‬\n‫طلــب املدعيــة اخللــع مــن املدعــى عليــه ‪ ،‬وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض علــى مــا حكــم بــه‬\n‫فضيلتــه بالفســخ املــؤرخ يف ‪1433/9/9‬ه ـ واهلل املوفــق وصلــى اهلل علــى‬\n                                    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪344‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":337,"source_page_end":344,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1cbb2668956cdb2a35f633e85c11ac243afed482461019129677422a8efbc710","normalized_text_hash":"c8c9f07b299c45ff54af80157b4e4670e1c92c09cd9cbcc5bfc202ce06ec5f5e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p337-33422293"},{"id":"4424fecd-c6e4-556e-9eb9-9652a4c501c4","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح بعد الدخول للضرر وسوء العشرة -للمدعية يف القضايا الزوجية إقامة دعواها يف بلد إقامتها -االستخالف لسماع جواب املدعى عليه -عدم حضور املدعى عليه رغم تبلغه يعد نكو ال عن اجلواب -احلكم بفسخ النكاح دون عوض -إفهام الطرفن باآلثار املترتبة على فسخ النكاح .","document_number":"34266092","case_number":"33464576","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع وقد أبرزته لناظر القضية","circuit":"الدائرة اجلزائية الرابعة مبحكمة الاستئناف مبنطقة مكة املكرمة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/11","year":"1434","subject":"فسخ نكاح بعد الدخول للضرر وسوء العشرة -للمدعية يف القضايا الزوجية إقامة دعواها يف بلد إقامتها -االستخالف لسماع جواب املدعى عليه -عدم حضور املدعى عليه رغم تبلغه يعد نكو ال عن اجلواب -احلكم بفسخ النكاح دون عوض -إفهام الطرفن باآلثار املترتبة على فسخ النكاح .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/11 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34266092 :‬‬\n                         ‫َر ْق ُم الدعوى‪33464576 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34355084‬تاريخه‪1434/11/10 :‬هـ‬\n\n\n      ‫فســخ نــكاح بعــد الدخــول للضــرر وســوء العشــرة ‪ -‬للمدعيــة يف القضايا‬\n      ‫الزوجيــة إقامــة دعواهــا يف بلــد إقامتهــا ‪ -‬االســتخالف لســماع جــواب‬\n      ‫املدعــى عليــه ‪ -‬عــدم حضــور املدعــى عليــه رغــم تبلغــه يعــد نكــو ًال عــن‬\n      ‫اجلــواب ‪ -‬احلكــم بفســخ النــكاح دون عــوض ‪ -‬إفهــام الطرفــن باآلثــار‬\n                                                         ‫املترتبــة علــى فســخ النــكاح ‪.‬‬\n\n\n\n\n                        ‫‪ .1‬قوله صلى اهلل عليه وسلم‪( :‬ال ضرر وال ضرار) ‪.‬‬\n         ‫‪ .2‬املادة ‪/10/34‬ه من نظام املرافعات الشرعية والئحته التنفيذية ‪.‬‬\n                    ‫‪ .3‬املادة ‪ 4/176‬واملادة ‪178‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة ضــد املدعــى عليــه الغائــب بأنه تزوجهــا بوالية أخيها على‬\n      ‫مهــر وقــدره (‪ )15000‬خمســة عشــر ألــف ريــال ســعودي مســتلمة مقدمــا‬\n      ‫واملؤخــر (‪ )20000‬عشــرون ألــف ريــال ودخــل بهــا وأنــه قــد هجرهــا منــذ‬\n      ‫أكثــر مــن ســنتني وتركهــا بــا نفقــة وهــو ال يقيــم الصــاة ويضربهــا‬\n      ‫وســاءت العشــرة بينهمــا وأنهــا تكرهــه وال تطيقــه وتطلــب احلكــم لهــا‬\n      ‫بفســخ نكاحهــا منــه هكــذا ادعــت ‪ ،‬طلبــت االســتخالف يف ســماع‬\n      ‫جــواب املدعــى عليــه ألنــه يقيــم يف محافظــة ينبــع ‪ ،‬جــرى اســتخالف‬\n\n‫‪345‬‬\n\f‫محكمــة ينبــع لســماع إجابــة الــزوج بنــاء علــى املــادة ‪/10/34‬ه مــن‬\n‫نظــام املرافعــات الشــرعية ‪ ،‬ورد جــواب محكمــة ينبــع بأنــه مت إكمــال‬\n‫الــازم وبرفقــه جــواب املدعــى عليــه املتضمــن (املصادقــة علــى الــزواج‬\n‫والدخــول والصــداق وإنــكار مــا ســوى ذلــك ‪ ،‬وبعــرض ذلــك علــى‬\n‫املدعيــة أنكــرت جوابــه وأن الصحيــح مــا ذكرتــه فهــو قــد أخرجهــا‬\n‫وقــد قذفهــا وصــدر بحقــه القــرار الشــرعي الصــادر مــن احملكمــة‬\n‫واملتضمــن جلــد املدعــى عليــه ‪ 79‬تســعا وســبعني جلــدة بحضــور املدعيــة‬\n‫باحلــق اخلــاص ولديهــا تقريــر طبــي بأنــه قــد ضربهــا هكــذا أجابــت ‪ ،‬لــم‬\n‫يحضــر املدعــى عليــه رغــم تبلغــه ‪ -‬قدمــت املدعيــة بينــة القــرار الشــرعي‬\n‫الصــادر مــن احملكمــة العامــة بينبــع وقــد أبرزتــه لناظــر القضيــة ‪،‬‬\n‫فبنــاء علــى مــا تقــدم مــن دعــوى املدعيــة وحيــث لــم يحضــر املدعــى عليــه‬\n‫مــع تبلغــه ممــا يــدل علــى أنــه يقصــد الضــرر باملدعيــة وهــذا يعــد نكــوال‬\n‫منــه عــن اجلــواب واخلصومــة كمــا يظهــر أنــه لــم يطلبهــا طــوال الفتــرة‬\n‫املاضيــة لبيــت الطاعــة وهــذا إضــرار منــه باملدعيــة وملــا أن انقيادها لبيت‬\n‫الزوجيــة أمــر ال تتحقــق معــه مصلحــة النــكاح مــن املــودة والرحمــة بــن‬\n‫الزوجــن وخصوصــا يف هــذه احلــال كمــا أن املدعيــة قــد أقامــت بينتهــا‬\n‫املثبتــة لدعواهــا ولقولــه صلــى اهلل عليــه وســلم‪( :‬ال ضرر وال ضرار) ‪ ،‬ملا‬\n‫تقــدم جــرى فســخ نــكاح املدعيــة مــن املدعــى عليــه مجانــا بغيــر عــوض‬\n‫ألنــه متســبب يف طلبهــا الفرقــة ‪ ،‬ويعــد احلكــم يف حــق املدعــى عليــه‬\n‫غيابيـ ًا ‪ ،‬وســوف يتــم إبــاغ احملكــوم عليــه وفــق إجــراءات التبليــغ ملــا يف‬\n‫املــادة ‪ 4/176‬مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة ‪ ،‬إفهــام‬\n‫املدعيــة أن عليهــا العــدة ثالثــة قــروء تبــدأ مــن تاريــخ اليــوم وأال تتــزوج‬\n‫حتــى يكتســب احلكــم القطعيــة كمــا أن علــى الــزوج أن يفهــم أنهــا قــد‬\n\n\n                                                                                       ‫‪346‬‬\n\f      ‫بانــت منــه بينونــة صغــرى ال حتــل لــه إال بعقــد ومهــر جديديــن ‪ ،‬الكتابــة‬\n      ‫حملكمــة األحــوال الشــخصية للتهميــش علــى وثيقــة عقــد النــكاح بعــد‬\n      ‫اكتســاب احلكــم القطعيــة ‪ ،‬اعتــرض املدعــى عليــه بالئحــة ‪ ،‬صــدق‬\n      ‫احلكــم مــن دائــرة األحــوال الشــخصية الثانيــة مبحكمــة االســتئناف‬\n                                                        ‫مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده ‪ ،‬وبعــد‪ :‬فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪33464576‬‬\n      ‫وتاريــخ ‪1433/07/14‬ه ـ املقيــدة باحملكمــة برقــم ‪331225033‬‬\n      ‫وتاريــخ ‪ 1433/06/30‬ه ـ ففــي يــوم اإلثنني‪1434/01/05‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة العاشــرة والربــع وفيهــا حضــرت (‪ )........‬فلســطينية‬\n      ‫اجلنســية بوثيقــة مصريــة مســلمة الديانــة مبوجــب رخصــة اإلقامــة رقــم‬\n      ‫(‪ )........‬بهــا مــن قبــل أخيهــا الشــقيق (‪ )........‬فلســطيني اجلنســية مســلم‬\n      ‫الديانــة مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬لســماع دعواهــا (‪)........‬‬\n      ‫بشــأن فســخ نــكاح وقــد أفــادت املدعيــة بــأن املدعــى عليــه زوجهــا يقيــم‬\n      ‫يف محافظــة ينبــع وبنــاء علــى املــادة ‪/10/34‬ه ـ مــن نظــام املرافعــات‬\n      ‫الشــرعية والئحتــه التنفيذيــة والتــي جتيــز ســماع الدعــاوى الزوجيــة يف‬\n      ‫بلــد الزوجــة فقــد قــررت ســماع الدعــوى وادعــت األولــى قائلــة إن املدعــى‬\n      ‫عليــه زوجــي عقــد علــي بتاريــخ ‪1430/06/15‬ه ـ بواليــة ‪ ......‬علــى مهــر‬\n      ‫وقــدره (‪ )15000‬خمســة عشــر ألــف ريــال ســعودي مســتلمة مقدمــا‬\n      ‫واملؤخــر (‪ )20000‬عشــرون ألــف ريــال وال شــروط بيننــا ودخــل بــي‬\n\n‫‪347‬‬\n\f‫بتاريــخ ‪1430/08/21‬ه ـ وأجنبــت منــه بنتــا اســمها ‪ ......‬وعمرهــا ســنتان‬\n‫وإن زوجــي قــد هجرنــي منــذ أكثــر مــن ســنتني وتركنــي بــا نفقــة وهــو‬\n‫ال يقيــم الصــاة وقــد ضربنــي وقــد ســاءت العشــرة بيننــا وأنــا أكرهــه‬\n‫وال أطيقــه أطلــب احلكــم لــي بفســخ نكاحــي منــه هكــذا ادعــت ثــم‬\n‫أضافــت قائلــة إن زوجــي يقيــم يف واليــة احملكمــة العامــة مبحافظــة‬\n‫ينبــع وهــو مقيــم إقامــة نظاميــة ويعمــل يف جامعــة طيبــة فــرع محافظــة‬\n‫ينبــع ورقــم هاتفــه النقــال األول ‪ ......‬والثانــي ‪ ......‬وأطلــب اســتخالف‬\n‫فضيلــة رئيــس احملكمــة العامــة بينبــع أو مــن ينيبــه مــن قضاتهــا يف‬\n‫ســماع إجابــة الــزوج هكــذا أضافــت لــذا قــررت الكتابــة لفضيلة رئيس‬\n‫احملكمــة العامــة مبحافظــة ينبــع الســتخالفه يف ســماع إجابــة الــزوج‬\n‫أو مــن ينيبــه مــن قضاتهــا وعليــه رفعــت اجللســة واختتمــت اجللســة ثــم‬\n‫يف يــوم الثالثاء‪1434/05/28‬ه ـ افتتحــت اجللســة يف الســاعة العاشــرة‬\n‫وفيهــا حضــرت ‪ ......‬هويتهــا ســابقا املعــرف بهــا مــن قبــل أخيهــا الشــقيق‬\n‫‪ ......‬هويتــه ســابقا وقــد متــت الكتابــة للمحكمــة العامــة مبحافظــة ينبــع‬\n‫ملــا ذكــر ســابقا باخلطــاب رقــم ‪ 3446543‬وتاريــخ ‪1434/01/11‬ه ـ‬\n‫فــوردت اإلفــادة باخلطــاب رقــم ‪ 34180932‬وتاريــخ ‪1434/05/14‬ه ـ من‬\n‫أنــه مت إكمــال الــازم ونــص الضبــط‪( :‬احلمــد هلل وحــده وبعــد فلــدي‬\n‫أنــا ‪ .......‬القاضــي يف احملكمــة بينبــع وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بينبع‪/‬املســاعد برقــم ‪3444015‬‬\n‫وتاريخ‪1434/01/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34180932‬وتاريــخ‬\n‫‪1434/01/20‬ه ـ املبنيــة علــى كتــاب االســتخالف الــوارد مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بجــدة برقــم ‪ 3446543‬يف ‪1434/01/11‬ه ـ‬\n                                  ‫ففــي يــوم اإلثنــن املوافــق ‪1434/05/13‬ه ـ‬\n\n\n                                                                                       ‫‪348‬‬\n\f      ‫افتتحــت اجللســة الســاعة ‪ 12:00‬وفيهــا حضــر ‪ .........‬أردنــي اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة ‪.........‬وجــرى االطــاع علــى الدعــوى املقيــدة يف‬\n      ‫صــورة الضبــط املرفقــة بخطــاب االســتخالف املتضمنــة بعــد املقدمــة‬\n      ‫مــا نصــه‪ « :‬وفيهــا حضــرت ‪.........‬فلســطينية اجلنســية بوثيقــة مصريــة‬\n      ‫مســلمة الديانــة مبوجــب رخصــة اإلقامــة رقــم ‪.........‬املعــرف بهــا مــن قبــل‬\n      ‫أخيهــا الشــقيق ‪.........‬فلســطيني اجلنســية مســلم الديانــة مبوجــب رخصــة‬\n      ‫اإلقامــة رقــم‪ .........‬لســماع دعواهــا ‪.........‬بشــأن فســخ نــكاح وقــد‬\n      ‫أفــادت املدعيــة بــأن املدعــى عليــه زوجهــا يقيــم يف محافظــة ينبــع وبنــاء‬\n      ‫علــى املــادة ‪/10/34‬ه ـ مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذية‬\n      ‫والتــي جتيــز ســماع الدعــاوى الزوجيــة يف بلــد الزوجــة فقــد قــررت ســماع‬\n      ‫الدعــوى وادعــت األولــى قائلــة إن املدعــى عليــه زوجــي عقــد علــي بتاريــخ‬\n      ‫‪1430/06/15‬ه ـ بواليــة أخــي ‪.........‬علــى مهــر وقــدره (‪ )15000‬خمســة‬\n      ‫عشــر ألــف ريــال ســعودي مســتلمة مقدمــا واملؤخــر (‪ )20000‬عشــرون‬\n      ‫ألــف ريــال وال شــروط بيننــا ودخــل بــي بتاريــخ ‪1430/08/21‬ه ـ وأجنبت‬\n      ‫منه بنتا اسمها ‪.........‬وعمرها سنتان وإن زوجي قد هجرني منذ أكثر‬\n      ‫مــن ســنتني وتركنــي بــا نفقــة وهــو ال يقيــم الصــاة وقــد ضربنــي وقــد‬\n      ‫ســاءت العشــرة بيننــا وأنــا أكرهــه وال أطيقــه أطلــب احلكــم لــي بفســخ‬\n      ‫نكاحــي منــه» أ‪.‬ه ـ وبعــرض الدعــوى أعــاه علــى احلاضــر ‪.........‬أجــاب‬\n      ‫قائــا‪ :‬مــا ذكرتــه املدعيــة ‪.........‬مــن زواجــي بهــا بالتاريــخ املذكــور‬\n      ‫باملهــر املذكــور ودخولــي بهــا وإجنابهــا بنتــا منــي علــى فــراش الزوجيــة‬\n      ‫فصحيــح‪ ،‬ومــا ســوى ذلــك فغيــر صحيــح‪ ،‬فاســم البنــت ‪.........‬وليــس‬\n      ‫‪ ،.........‬ومــا ذكرتــه مــن هجرانــي لهــا فغيــر صحيــح فهــي هربــت مــن‬\n      ‫بيــت الزوجيــة يف ينبــع إلــى جــدة‪ ،‬وقــد أخــذت معهــا حــن خرجــت مــن‬\n\n\n‫‪349‬‬\n\f‫بيــت الزوجيــة مبلغــا مــن مالــي قــدره ســتة آالف ريــال ومــا ذكرتــه مــن‬\n‫أنــي ال أقيــم الصــاة فغيــر صحيــح فأنــا مــن احملافظــن علــى الصــاة‬\n‫ومســتعد بإحضــار مــن يزكينــي مــن أئمــة املســاجد‪ ،‬ولــم أخرجهــا قــط‬\n‫ولــم أســئ عشــرتها وأنــا راغــب بهــا ولســت مســتعدا بطالقهــا هكــذا‬\n‫أجــاب املدعــى عليــه‪ ،‬وقــررت إعــادة املعاملــة لفضيلــة حاكــم القضيــة‬\n‫مرفقــا بهــا صــورة مصدقــة مــن ضبــط االســتخالف وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n‫‪1434/05/13‬ه ـ مدعــى عليــه ‪.........‬توقيعــه كاتــب الضبــط ‪.........‬‬\n‫توقيعــه القاضــي يف احملكمــة العامــة بينيــع ‪.........‬توقيعــه) وبعــرض‬\n‫إجابــة املدعــى عليــه علــى املدعيــة أجابــت قائلــة مــا ذكــره غيــر صحيــح‬\n‫والصحيــح مــا ذكرتــه فهــو قــد أخرجنــي وأنــا لــم أخــرج مــن منزلــه ولــم‬\n‫آخــذ منــه أي مبلــغ مالــي وأنــا ال أرغــب فهــو قــد قذفنــي وصــدر بحقــه‬\n‫القــرار الشــرعي الصــادر مــن احملكمــة العامــة مبحافظــة ينبــع برقــم‬\n‫‪ 3457933‬والتاريخ‪1434/03/08‬ه ـ واملتضمــن جلــد املدعــى عليــه ‪79‬‬\n‫تســعا وســبعني جلــدة بحضــور املدعيــة باحلــق اخلــاص ولــدي تقريــر طبــي‬\n‫بأنــه قــد ضربنــي هكــذا أجابت ونظرا لتوجه الدعوى فقد قررت طلب‬\n‫املدعــى عليــه ورفعــت اجللســة لطلــب حضــور املدعــى عليــه أو مــن ميثلــه‬\n‫واختتمــت اجللســة ثــم يف يــوم األحــد املوافــق‪ 1434/07/02‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة الواحــدة وفيهــا حضــرت املدعيــة ‪.........‬املثبتــة هويتهــا‬\n‫ســابقا املعــرف بهــا مــن قبــل أخيهــا الشــقيق ‪.........‬املثبتــة هويتــه ســابقا‬\n‫لســماع دعواهــا ‪.........‬بشــأن دعــوى يف حكــم منقــوض فســخ نــكاح‪/‬‬\n‫غيــر مشــتركة وقــد مت طلــب املدعــى عليــه عــن طريــق قســم محضــري‬\n‫اخلصــوم باخلطــاب رقــم ‪ 341303636‬وتاريــخ ‪1434/05/28‬ه ـ ملــا ذكر‬\n\n\n                                                                                        ‫‪350‬‬\n\f      ‫ســابقا فتمــت الكتابــة مــن قبــل رئيــس احملكمــة العامــة مبحافظــة‬\n      ‫جــدة املســاعد باخلطــاب رقــم ‪ 341303636‬وتاريــخ ‪1434/06/04‬ه ـ‬\n      ‫للمحكمــة العامــة مبحافظــة ينبــع فــوردت اإلفــادة مــن القائــم بعمــل‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة ينبــع باخلطــاب رقــم ‪341303636‬‬\n      ‫وتاريــخ ‪1434/06/26‬ه ـ املقيــد يف احملكمــة برقــم ‪341303636‬‬\n      ‫وتاريــخ ‪1434/07/01‬ه ـ املتضمنــة عليــه نفيدكــم مت إجــراء الــازم‬\n      ‫حيــال إبــاغ املذكــور ا‪.‬ه ـ نقــل نصــا وباالطــاع علــى املعاملــة وجــد‬\n      ‫ان املدعــى عليــه قــد تبلــغ بنفســه ووقــع علــى أصــل ورقــة التبليــغ ولــم‬\n      ‫يحضــر املدعــى عليــه وال مــن ميثلــه وبســؤال املدعيــة ببينتهــا علــى دعواهــا‬\n      ‫أجابــت قائلــة بينتــي هــي القــرار الشــرعي الصــادر مــن احملكمــة العامــة‬\n      ‫مبحافظــة ينبــع ويحمــل الرقــم ‪ 457933‬والتاريــخ ‪1434/03/08‬ه ـ‬\n      ‫هكــذا أجابــت ورفعــت اجللســة للتأمــل واختتمــت اجللســة ثــم يف يــوم‬\n      ‫اإلثنــن ‪1434/07/10‬ه ـ افتتحــت اجللســة يف الســاعة الثانيــة والنصــف‬\n      ‫وفيهــا حضــرت املدعيــة أصالــة ‪.........‬املثبتــة هويتهــا ســابقا املعــرف بهــا‬\n      ‫مــن قبــل أخيهــا الشــقيق ‪.........‬املثبتــة هويتــه ســابقا لســماع دعواهــا علــى‬\n      ‫‪.........‬بشــأن فســخ نــكاح ولــم يحضــر املدعــى عليــه وال مــن ميثلــه وقــد‬\n      ‫قــررت املدعيــة قائلــة‪ :‬إن املدعــى عليــه قــد ضارنــي وشــوه ســمعتي وأنــا‬\n      ‫متضــررة مــن ذلــك كمــا أنــي يف منــزل أهلــي منــذ ثــاث ســنوات وأنــا‬\n      ‫مــن ذوات األقــراء وغيــر حامــل كمــا أن وثيقــة عقــد النــكاح أصلهــا‬\n      ‫مــع املدعــى عليــه كمــا أنــا قــد حصلــت علــى صــورة طبــق األصــل‬\n      ‫مــن محكمــة األحــوال الشــخصية مبحافظــة جــدة هكــذا قــررت‬\n      ‫وباالطــاع علــى صــورة مصدقــة طبــق األصــل مــن القــرار الشــرعي رقــم‬\n      ‫‪ 3457933‬وتاريــخ ‪1434/03/08‬ه ـ الصــادر مــن احملكمــة العامــة يف‬\n\n\n‫‪351‬‬\n\f‫محافظــة ينبــع ومصدقــة مــن القاضــي ناظــر القضيــة فضيلــة الشــيخ‬\n‫‪.........‬القاضــي باحملكمــة العامــة مبحافظــة ينبــع وجدتــه يتضمــن‬\n‫دعــوى عامــة مــن املدعــي العــام ودعــوى خاصــة مــن املدعيــة وتتضمــن‬\n‫دعــوى املدعــي العــام طلبــه احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة‬\n‫ملــا أن الفعــل الــذي أقــدم عليــه محــرم ومعاقــب عليــه شــرعا والــذي هــو‬\n‫أن املدعــى عليــه قــد أرســل رســائل للمدعيــة علــى جوالهــا وتتضمــن أنهــا‬\n‫خائنــة ولهــا عالقــة بشــيعي ‪.........‬وأنهــا ســاقطة وأنهــا كانــت تخــرج مــع‬\n‫أشــخاص خــال الثانويــة وأنهــا حاولــت قتــل خطيبهــا وأن التهمــة توجهت‬\n‫علــى املدعــى عليــه بأنــه أرســل لهــا رســائل تتضمــن التلفــظ علــى املدعيــة‬\n‫بألفــاظ فاحشــة وغيــر الئقــة وتتضمــن دعــوى املدعيــة طلبهــا بإقامــة حــد‬\n‫القــذف كمــا أن املدعــى عليــه قــد تلفــظ علــى املدعيــة أمــام فضيلــة‬\n‫ناظــر القضيــة قائــا لهــا أنتــي ‪.........‬وأخــوك احلاضــر معــك يقــود عليــك‬\n‫وقــد حكــم علــى املدعــى عليــه باجللــد ‪ 79‬تســعا وســبعني جلــدة دفعــة‬\n‫واحــدة علنــا بحضــور املدعيــة باحلــق اخلــاص وقــررت املدعيــة القناعــة‬\n‫بينمــا قــرر املدعــى عليــه اعتراضــه وقــد جــرى املوافقــة علــى احلكــم مــن‬\n‫الدائــرة اجلزائيــة الرابعــة مبحكمة االســتئناف مبنطقــة مكة املكرمة‬\n‫بالقــرار رقــم ‪ 34185231‬وتاريــخ ‪1434/04/10‬ه ـ ا‪.‬ه ـ نقــل نصــا كمــا‬\n‫أبــرزت املدعيــة صــورة طبــق األصــل مــن ضبــط عقــد النــكاح مــن‬\n‫محكمــة األحــوال الشــخصية مبحافظــة جــدة ويتضمــن العقــد للمدعــى‬\n‫عليــه علــى املدعيــة علــى مهــر وقــدره (‪ )15000‬خمســة عشــرة ألــف ريــال‬\n‫ســعودي مســلم و(‪)20000‬عشــرين ألــف ريــال ســعودي مؤخــر ا‪.‬ه ـ نقــل‬\n‫نصــا كمــا مت االطــاع علــى الصــك بالصــك رقــم ‪ 32130444‬وتاريــخ‬\n‫‪1432/06/13‬ه ـ مــن فضيلــة الشــيخ ‪.........‬القاضــي بهــذه احملكمــة‬\n\n\n                                                                                     ‫‪352‬‬\n\f      ‫واملتضمــن فســخ نــكاح املدعيــة مــن املدعــى عليــه واملنقــوض بالقــرار‬\n      ‫رقــم ‪ 33300277‬وتاريــخ ‪1433/06/16‬ه ـ مــن الدائــرة الثانيــة لألحــوال‬\n      ‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة‬\n      ‫االســتئناف مبكــة املكرمــة فبنــاء علــى مــا تقــدم مــن دعــوى املدعيــة‬\n      ‫واملتضمنــة طلبهــا فســخ نكاحهــا مــن املدعــى عليــه لتضررهــا مــن‬\n      ‫البقــاء لديــه ألنــه يضربهــا ويســيء إليهــا وبنــاء علــى مــا ذكــره املدعــى‬\n      ‫عليــه لــدى القاضــي املســتخلف مــن عــدم موافقتــه علــى فســخ نكاحهــا‬\n      ‫وأنــه لــم يســيء عشــرتها ولــم يحضــر مــع تبلغــه ممــا يــدل علــى أنــه‬\n      ‫يقصــد الضــرر باملدعيــة وهــذا يعــد نكــوال منــه عــن اجلــواب واخلصومــة‬\n      ‫كمــا يظهــر أنــه لــم يطلبهــا طــوال الفتــرة املاضيــة لبيــت الطاعــة وهــذا‬\n      ‫إضــرار منــه باملدعيــة وملــا أن انقيادهــا لبيــت الزوجيــة أمــر ال تتحقــق‬\n      ‫معــه مصلحــة النــكاح مــن املــودة والرحمــة بــن الزوجــن وخصوصــا يف‬\n      ‫هــذه احلــال كمــا أن املدعيــة قــد أقامــت بنيتهــا املثبتــة لدعواهــا ولقولــه‬\n      ‫صلــى اهلل عليــه وســلم‪( :‬ال ضــرر والضــرار) فقــد فســخت نــكاح‬\n      ‫املدعيــة ‪.........‬مــن املدعــى عليــه ‪ ...‬مجانــا بغيــر عــوض ألنــه متســبب يف‬\n      ‫طلبهــا الفرقــة وبــه حكمــت ويعــد احلكــم يف حــق املدعــى عليــه غيابيــا‬\n      ‫وســوف يتــم إبــاغ احملكــوم عليــه وفــق إجــراءات التبليــغ ملــا يف املــادة‬\n      ‫‪ 4/176‬مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة ويبــدأ ميعــاد‬\n      ‫االعتــراض علــى احلكــم مــن تاريــخ التبليــغ وإذا لــم يقــدم املدعــى عليــه‬\n      ‫اعتراضــه خــال املــدة املقــررة نظامــا فيكتســب احلكــم القطعيــة وقفــا‬\n      ‫للمــادة (‪ )178‬مــن نظــام املرافعــات الشــرعية وأفهمــت املدعيــة أن عليهــا‬\n      ‫العــدة ثالثــة قــروء تبــدأ مــن تاريــخ اليــوم ألنهــا قــررت أنهــا مــن ذوات‬\n      ‫األقــراء وغيــر حامــل وأال تتــزوج حتــى يكتســب احلكــم القطعيــة كمــا‬\n\n\n‫‪353‬‬\n\f‫أن علــى الــزوج أن يفهــم أنهــا قــد بانــت منــه بينونــة صغــرى الحتــل لــه‬\n‫إال بعقــد ومهــر جديديــن كمــا قــررت الكتابــة حملكمــة األحــوال‬\n‫الشــخصية للتهميــش علــى وثيقــة عقــد النــكاح بعــد اكتســاب احلكــم‬\n‫القطعيــة جــرى النطــق باحلكــم يف يــوم اإلثنــن ‪1434/07/10‬ه ـ يف‬\n‫الســاعة الثانيــة والنصــف‪ ،‬واختتمــت اجللســة يف الســاعة الثالثــة‪ ،‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                           ‫يف ‪1434/07/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد اإلثنــن ‪1434/08/22‬ه ـ افتتحــت اجللســة يف‬\n‫الســاعة التاســعة وخمــس وأربعــن دقيقــة وفيهــا حضــر املدعــى عليــه‬\n‫‪.........‬أردنــي اجلنســية مســلم الديانــة مبوجــب رخصــة اإلقامــة رقــم ‪.........‬‬\n‫وبعــرض احلكــم املرصــود نصــه علــى املدعــى عليــه أجــاب قائــا أنــا‬\n‫معتــرض علــى احلكــم وغيــر قانــع ومســتعد بتقــدمي الئحــة اعتراضيــة‬\n‫هكــذا أجــاب فجــرى إفهامــه بــأن لــه ثالثــن يومــا مــن تاريــخ اســتالمه‬\n‫الــذي هــو اليــوم لنســخة احلكــم وإذا فــات علــى ميعــاد ولــم يقــدم الئحتــه‬\n‫االعتراضيــة ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة‬\n‫كمــا قــد جــرت الكتابــة للمحكمــة العامــة مبحافظــة ينبــع باخلطــاب‬\n‫رقــم ‪ 341718407‬وتاريــخ ‪1434/07/19‬ه ـ ملــا ذكــر ســابقا ولــم تردنــا‬\n‫اإلفادة حتى اآلن‪ ،‬واختتمت اجللسة ثم يف يوم اإلثنني ‪1434/08/22‬هـ‬\n‫افتتحــت اجللســة يف الســاعة الواحــدة والربــع وفيهــا حضــر املدعــى عليــه‬\n‫أصالــة ‪ .........‬املثبتــة هويتــه ســابقا وقــدم الئحتــه االعتراضيــة املقيــدة يف‬\n‫احملكمــة برقــم ‪ 342027984‬وتاريــخ ‪1434/08/22‬ه ـ واملكونــة مــن‬\n‫إحــدى وخمســن ورقــة ورفعــت اجللســة لدراســتها واختتمــت اجللســة ثــم‬\n‫يف يــوم األحــد ‪1434/09/05‬ه ـ افتتحــت اجللســة يف الســاعة العاشــرة‬\n\n\n                                                                                        ‫‪354‬‬\n\f      ‫والربــع وفيهــا حضــرت املدعيــة أصالــة ‪.........‬هويتهــا ســابقا كمــا حضــر‬\n      ‫حلضورهــا املدعــى عليــه أصالــة ‪.........‬املثبتــة هويتــه ســابقا وقــد وردتنــا‬\n      ‫اإلفــادة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة ينبــع املســاعد‬\n      ‫باخلطــاب رقــم ‪ 341718407‬وتاريــخ ‪1434/08/28‬ه ـ واملتضمــن أنــه مت‬\n      ‫تســليم نســخة احلكــم للمدعــى عليــه بتاريــخ ‪1434/08/21‬ه ـ مما يعني‬\n      ‫أنــه قــد اســتلم مــرة أخــرى لدينــا بتاريــخ ‪1434/08/22‬ه ـ وكال املرتــن‬\n      ‫يف وقــت االعتــراض وباالطــاع علــى الالئحــة االعتراضيــة املقدمــة مــن‬\n      ‫املدعــى عليــه واملذكــور رقــم قيدهــا وتاريخــه أعــاه ودراســتها لــم أجــد‬\n      ‫بهــا مــا يؤثــر علــى مــا حكمــت بــه لــذا قــررت رفعهــا مــع كامــل املعاملــة‬\n      ‫والصــك وصــورة مصدقــة مــن الضبــط حملكمــة االســتئناف ‪ ،‬واختتمت‬\n      ‫اجللســة يف الســاعة العاشــرة والنصــف‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/09/05‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبي بعــده ‪ ،‬وبعد فقد جرى منا‬\n      ‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n      ‫والقصار وبيوت املال مبحكمة االســتئناف يف منطقة مكة املكرمة‬\n      ‫االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪......... /‬القاضــي‬\n      ‫باحملكمــة العامــة بجــدة برقــم ‪ 34266092‬وتاريخ‪1434/7/11‬ه ـ‬\n      ‫املتضمــن دعــوى ‪.........‬ضــد ‪......... /‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم واهلل‬\n              ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪355‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":345,"source_page_end":355,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e125c3394ad35fea8c07db7777fb13da3357be48ceff095f4ed27950e337e151","normalized_text_hash":"ee1a8ea7601a090ef62c3265e8a877b584ec3cec60ce1c13d25e534fff7834e5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p345-34266092"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"591faeaf-4942-58ec-a866-be42d44b7820","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب فسخ النكاح بعد الدخول لسوء العشرة ،وتعاطي والكره -قرر احلكمان املختاران من قبل الزوجني التفريق املخدرات ، دون عوض -استعداد الزوجة بذل كامل املهر املسلم ،والتنازل عن املؤخر -عدم موافقة الزوج -فسخ النكاح على كامل العوض .","document_number":"33450924","case_number":"33199867","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/10","year":"1434","subject":"فسخ نكاح -طلب فسخ النكاح بعد الدخول لسوء العشرة ،وتعاطي والكره -قرر احلكمان املختاران من قبل الزوجني التفريق املخدرات ، دون عوض -استعداد الزوجة بذل كامل املهر املسلم ،والتنازل عن املؤخر -عدم موافقة الزوج -فسخ النكاح على كامل العوض .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/10 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33450924 :‬‬\n                          ‫َر ْق ُم الدعوى‪33199867 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3413731‬تاريخه‪1434/1/17:‬هـ‬\n\n\n       ‫فســخ نــكاح ‪ -‬طلــب فســخ النــكاح بعــد الدخــول لســوء العشــرة ‪ ،‬وتعاطي‬\n       ‫والكــره ‪ -‬قــرر احلكمــان املختــاران مــن قبل الزوجني التفريق‬  ‫املخــدرات ‪ُ ،‬‬\n       ‫دون عــوض ‪ -‬اســتعداد الزوجــة بــذل كامــل املهــر املســلم ‪ ،‬والتنــازل عــن‬\n            ‫املؤخــر ‪ -‬عــدم موافقــة الــزوج ‪ -‬فســخ النــكاح علــى كامــل العوض ‪.‬‬\n\n\n\n\n       ‫‪ .1‬قولــه تعالــى‪« :‬وإن خفتــم شــقاق بينهمــا فابعثــوا حكم ـ ًا مــن أهلــه‬\n                        ‫وحكم ـ ًا مــن أهلهــا إن يريــدا إصالح ـ ًا يوفــق اهلل بينهمــا»‬\n       ‫‪ .2‬مــا رواه البخــاري عــن ابــن عبــاس رضــي اهلل عنهمــا قــال‪ :‬جــاءت امــرأة‬\n       ‫ثابــت بــن قيــس بــن شــماس إلــى النبــي صلــى اهلل عليــه وســلم فقالــت‪:‬‬\n       ‫يــا رســول اهلل مــا أنقــم علــى ثابــت يف ديــن وال خلــق إال أنــي أخــاف‬\n       ‫الكفــر يف اإلســام‪ ،‬فقــال رســول اهلل صلــى اهلل عليــه وســلم‪ :‬أترديــن‬\n                        ‫عليــه حديقتــه قالــت‪ :‬نعــم فــردت عليــه فأمــره ففارقهــا»‪.‬‬\n                                  ‫‪ .3‬قوله صلى اهلل عليه وسلم‪« :‬ال ضرر وال ضرار»‬\n       ‫‪ .4‬مــا رواه النســائي وعبــد الــرزاق عــن ابــن عبــاس رضــي اهلل عنهمــا قــال‪:‬‬\n       ‫بعثــت أنــا ومعاويــة حكمــن قــال معمــر‪ :‬بلغنــي أن عثمــان بعثهمــا وقــال‬\n                         ‫إن رأيتمــا أن جتمعــا جمعتمــا وإن رأيتمــا أن تفرقــا ففرقــا»‬\n       ‫‪ .5‬مــا رواه الــدار قطنــي والنســائي والشــافعي والبيهقــي عــن محمــد بــن‬\n       ‫ســيرين عــن عبيــدة قــال‪« :‬جــاء رجــل وامــرأة إلــى علــي مــع كل واحــد‬\n       ‫منهمــا فئــام مــن النــاس فأمرهــم فبعثــوا حكم ـ ًا مــن أهلــه وحكم ـ ًا مــن‬\n‫‪307‬‬\n\f‫أهلهــا وقــال للحكمــن هــل تدريــان مــا عليكمــا؟ عليكمــا إن رأيتمــا إن‬\n‫جتمعــا فاجمعــا وإن رأيتمــا أن تفرقــا فرقتمــا فقالــت املــرأة‪ :‬رضيــت‬\n‫بكتــاب اهلل مبــا علـ ّـي فيــه ولــي ‪ ،‬وقــال الــزوج‪ :‬أمــا الفرقــة فــا‪ ،‬فقــال‬\n‫علــي‪ :‬كذبــت واهلل ال تبــرح حتــى تقــر مثــل الــذي أقــرت بــه» قــال ابــن‬\n                                                      ‫حجــر‪ :‬إســناده صحيــح‪.‬‬\n‫‪ .6‬مــا أخرجــه الطبــري يف تفســيره‪ :‬عــن ابــن عبــاس رضــي اهلل عنهمــا‬\n‫يف احلكمــن أنــه قــال‪ :‬فــإن اجتمــع أمرهمــا علــى أن يفرقــا أو يجمعــا‬\n                                                                ‫فأمرهمــا جائــز ‪.‬‬\n\n\n\n\n‫ادعــت املدعيــة املعــرف بهــا مــن قبــل والدهــا أن املدعــى عليــه تزوجهــا‪،‬‬\n‫ورزقــت منــه بابنــن وأن العشــرة ســاءت بينهمــا‪ ،‬وذلــك أنــه يضربهــا‬\n‫ويشــتمها ويســيء معاملتهــا ويتعاطــى املخــدرات‪ ،‬وال يعتنــي بنظافــة‬\n‫بدنــه‪ ،‬وأنهــا أصبحــت مبغضــة لــه وال تطيــق العيــش معــه وطلبــت‬\n‫تكليفــه بطالقهــا أو فســخ نكاحهــا منــه ‪ ،‬بعــرض دعــوى املدعيــة‬\n‫علــى املدعــى عليــه صــادق علــى الــزواج واملهــر واألبنــاء وأنكــر مــا ســوى‬\n‫ذلــك‪ ،‬وقــرر أنــه ضربهــا مــرة واحــدة بســبب وجــود مقاطــع إباحيــة يف‬\n‫جهازهــا اجلــوال وبســبب تكــرر رفــع صوتهــا عليــه‪ ،‬ولــم يوافــق علــى‬\n‫طلبهــا الطــاق ‪ ،‬اســتجابة لقــول اهلل تعالــى ( وإن خفتــم شــقاق بينهمــا‬\n‫فابعثــوا حكمــا مــن أهلــه وحكمــا مــن أهلهــا ) مت طلــب حكمــن مــن‬\n‫الطرفــن ‪ ،‬اختــارت املدعيــة أخاهــا‪ ،‬واختــار املدعــى عليــه أهــل اخلبــرة‬\n‫يف احملكمــة ‪ ،‬جــرى التحكيــم بــن الطرفــن ومحاولــة اإلصــاح‬\n‫بينهمــا قــدر املســتطاع ‪ -‬ورد جــواب هيئــة النظــر يف احملكمــة املتضمــن‬\n\n                                                                                       ‫‪308‬‬\n\f      ‫أنــه حضــر حكــم الزوجــة وحكـ ٌـم مــن قبــل الــزوج وذكــرا أن األمــر‬\n      ‫وصــل إلــى طريـ ٍـق مســدود ورأت هيئــة النظــر أن تعيــد املدعيــة املهــر‬\n      ‫إلــى زوجهــا وتتــم املخالعــة ‪ ،‬بعــرض ذلــك علــى الطرفــن وافقــت عليــه‬\n      ‫املدعيــة‪ ،‬وقــرر املدعــى عليــه عــدم موافقتــه ‪ ،‬قــرر الطرفــان أن املهــر‬\n      ‫عشــرون ألــف ‪ ،‬أحضــرت املدعيــة العــوض بشــيك مصــدق مببلــغ قــدره‬\n      ‫عشــرون ألــف ريــال ‪ ،‬وقــررت تنازلهــا عــن مؤخــر الصــداق وقــدره ثالثون‬\n      ‫ألــف ريــال ‪ ،‬إلصــرار كل منهمــا علــى رأيــه ونظــر ًا إلــى أن اســتمرار‬\n      ‫احليــاة الزوجيــة علــى هــذا الوضــع أمــر ال تتحقــق منــه مقاصــد النــكاح‬\n      ‫يف الشــريعة مــن املــودة والرحمــة والســكن وتربيــة األوالد والعفــة مــع‬\n      ‫مــا يف ذلــك مــن املضــار النفســية واالجتماعيــة واجلســدية علــى الزوجــن‬\n      ‫واألوالد‪ ،‬ونظــر ًا لبقــاء املدعيــة ناشــز ًا مــع طــول املــدة أمــر غيــر محمــود‬\n      ‫شــرع ًا مــع مــا ينشــأ عنــه مــن الظلــم واإلثــم والقطيعــة بــن األســر وتوليــد‬\n      ‫العــداوة والبغضــاء ‪ ،‬لــذا مت احلكــم بفســخ نــكاح املدعيــة مــن زوجهــا‬\n      ‫املدعــى عليــه علــى عــوض قــدره عشــرون ألــف ريــال ‪ ،‬جــرى إفهــام‬\n      ‫املدعيــة بــأن عليهــا العــدة الشــرعية ‪ ،‬كمــا جــرى إفهــام املدعــى عليــه‬\n      ‫بــأن زوجتــه قــد بانــت منــه بينونــة صغــرى ال حتــل لــه إال بعقــد ومهــر‬\n      ‫جديديــن ‪ ،‬بعــرض احلكــم علــى الطرفــن قــررت املدعيــة القناعــة وقــرر‬\n      ‫املدعــى عليــه عدمهــا ‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت‬\n                                                                         ‫املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫‪309‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا (‪ )........‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيس احملكمة العامــة مبحافظة جدة‪/‬‬\n‫املســاعد برقــم ‪ 33199867‬وتاريــخ ‪1433/3/20‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 33530117‬وتاريــخ ‪1433/03/20‬ه ـ حضــرت (‪ )........‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬املعــرف بهــا مــن قبــل‬\n‫والدهــا (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)........‬‬\n‫وحضــر حلضورهــا (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )........‬فادعــت ‪ ...‬قائلــة يف دعواهــا أن املدعــى عليــه زوجــي‬\n‫تزوجنــي عــام ‪1425‬ه ـ بواليــة والــدي مبوجــب عقــد نــكاح رســمي ال‬\n‫اعــرف رقمــه وال تاريخــه وأمهرنــي مبلغــا وقــدره ثالثــون ألــف ريــال وقــد‬\n‫رزقــت منــه بابنــن وهمــا ‪ ......‬املولــود يف ‪1427/3/19‬ه ـ و‪ ..........‬املولــود‬\n‫يف ‪1430/11/13‬ه ـ وقــد ســاءت العشــرة بينــي وبينــه فهــو يضربنــي‬\n‫ويشــتمني ويســيء معاملتــي ويتعاطــى املخــدرات وال يعتنــي بنظافــة‬\n‫بدنــه فأصبحــت مبغضــة لــه وال أطيــق العيــش معــه لــذا اطلــب تكليفــه‬\n‫بطالقــي أو فســخ نكاحــي منــه هكــذا ادعــت وبعــرض الدعــوى علــى‬\n‫املدعــى عليــه قــال مــا ذكرتــه املدعيــة يف دعواهــا مــن الــزواج وتاريخــه‬\n‫واملهــر وقــدره واألبنــاء وتواريــخ ميالدهــم كلــه صحيــح ومــا ذكرتــه مــن‬\n‫أننــي اشــتمها وأســيء معاملتهــا وأتعاطــى املخــدرات وال أعتنــي بنظافــة‬\n‫بدنــي فهــو غيــر صحيــح ومــا ذكرتــه مــن أننــي أضربهــا فلــم أضربهــا‬\n‫ســوى مــرة واحــدة بســبب وجــود مقاطــع اباحيــة يف جهازهــا اجلــوال‬\n\n                                                                                     ‫‪310‬‬\n\f      ‫وبســبب تكــرر رفــع صوتهــا علــي وأمــا طلبهــا الطــاق فــا أوافــق عليــه‬\n      ‫فهــي زوجتــي وأم أوالدي وأحبهــا وال أوافــق علــى طلبهــا الطــاق هكــذا‬\n      ‫أجــاب واســتجابة لقــول اهلل تعالــى ( وان خفتــم شــقاق بينهمــا فابعثــوا‬\n      ‫حكمــا مــن أهلــه وحكمــا مــن أهلهــا ) طلبــت مــن الطرفــن اختيــار‬\n      ‫حكمــن مــن أهلهمــا فاختــارت املدعيــة أخاهــا ‪ ...........‬واختــار املدعــى‬\n      ‫عليــه أهــل اخلبــرة يف احملكمــة فقــررت الكتابــة لقســم اخلبــراء يف هــذه‬\n      ‫احملكمــة الختيــار حكــم املدعــى عليــه مــن قبلهــم واالجتمــاع باحلكــم‬\n      ‫الــذي اختارتــه املدعيــة وإجــراء التحكيــم بــن الطرفــن ومحاولــة‬\n      ‫اإلصــاح بينهمــا قــدر املســتطاع ويف جلســة اخــرى حضــر الطرفــان‬\n      ‫واملعــرف وقــد كانــت جــرت الكتابــة لقســم الصلــح الختيــار حكــم‬\n      ‫منهــم عــن املدعــى عليــه واالجتمــاع بحكــم الزوجــة وإجــراء التحكيــم‬\n      ‫ومحاولــة اإلصــاح بينهمــا قــدر املســتطاع وذلــك مبوجــب خطابنــا رقــم‬\n      ‫‪ 33530117‬يف ‪1433/08/05‬ه ـ فوردنــا خطابهــم رقــم ‪ 33530117‬يف‬\n      ‫‪1433/10/15‬ه ـ وبرفقــه محضرهــم املــؤرخ يف ‪1433/10/13‬ه ـ ونــص‬\n      ‫احلاجــة منــه ( حضــرت املدعيــة وحضــر حلضورهــا املدعــى عليــه وجــرت‬\n      ‫محاولــة اإلصــاح حيــث ذكــرت املدعيــة أنهــا زوجــة لهــذا احلاضــر‬\n      ‫يف مجلــس الصلــح وأنهــا كرهــة العيــش معــه لســوء معاملتــه وطلبنــا‬\n      ‫إحضــار حكمــا مــن قبــل املدعيــة فأحضــرت ‪ .............‬وأحضــر الــزوج‬\n      ‫‪ ............‬وذكــرا أن األمــر وصــل إلــى طريــق مســدود وبعــرض ذلــك علــى‬\n      ‫الــزوج ذكــر أنــه يرغــب يف زوجتــه وال يســتطيع فراقهــا وحيــث األمــر‬\n      ‫مــا ذكــر وبعــد العــرض علــى املدعيــة إمــا العــودة إلــى بيــت زوجهــا أو‬\n      ‫إعــادة املهــر قالــت الزوجــة ال أريــده ومســتعدة بإعــادة املهــر ومقــداره‬\n      ‫عشــرون ألــف ريــال وحيــث األمــر مــا ذكــر فإنــا نــرى أن تعيــد املهــر إلــى‬\n\n\n‫‪311‬‬\n\f‫زوجهــا وتتــم املخالعــة والــرأي لفضيلتكــم‪ .‬حكــم مــن قبــل الزوجــة‬\n‫‪ ..........‬توقيــع ‪ ..............‬توقيــع) وبعرضــه علــى الطرفــن قالــت املدعيــة‬\n‫إننــي موافقــة علــى مــا جــاء فيــه هكــذا قــرر وقــال املدعــى عليــه إننــي‬\n‫غيــر موافــق علــى مــا جــاء فيــه هكــذا قــررت فجــرى ســؤال املدعيــة‬\n‫عــن املهــر فقالــت إنــه ليــس لــدي وأطلــب إمهالــي إلحضــاره كمــا قــرر‬\n‫الطرفــان بــأن املهــر عشــرين ألــف ريــال وليــس كمــا ذكــر يف اجللســة‬\n‫األولــى مــن أنــه ثالثــون ألــف ريــال ‪ ..........‬يتبــع ورفعــت اجللســة لذلــك ويف‬\n‫جلســة أخــرى حضــر الطرفــان واملعــرف وقــد أبــرزت الشــيك املصــدق‬\n‫رقــم ‪ 33440‬يف ‪2012/09/24‬م املســحوب علــى مصــرف اإلمنــاء باســم‬\n‫فضيلــة رئيــس احملكمــة مببلــغ وقــدره عشــرون ألــف ريــال وقــد جــرى‬\n‫منــي محاولــة اإلصــاح بــن الطرفــن مــرارا فلــم يصطلحــا فبنــاء علــى ما‬\n‫تقــدم مــن الدعــوى واإلجابــة ومــا قــرره احلكمــان اللــذان مت اختيارهمــا‬\n‫مــن قبــل الزوجــن مــن التفريــق بينهمــا بــدون عــوض ومــا مت مــن وعظهمــا‬\n‫وتوجيههمــا وإلصــرار كل منهمــا علــى رأيــه ولعمــوم قولــه تعالــى‪« :‬وإن‬\n‫خفتــم شــقاق بينهمــا فابعثــوا حكم ـ ًا مــن أهلــه وحكم ـ ًا مــن أهلهــا إن‬\n‫يريــدا إصالح ـ ًا يوفــق اهلل بينهمــا» وملــا رواه البخــاري عــن ابــن عبــاس‬\n‫رضــي اهلل عنهمــا قــال‪ :‬جــاءت امــرأة ثابــت بــن قيــس بــن شــماس إلــى‬\n‫النبــي صلــى اهلل عليــه وســلم فقالــت‪ :‬يــا رســول اهلل مــا أنقــم علــى ثابــت‬\n‫يف ديــن وال خلــق إال أنــي أخــاف الكفــر يف اإلســام‪ ،‬فقــال رســول اهلل‬\n‫صلــى اهلل عليــه وســلم‪ :‬أترديــن عليــه حديقتــه قالــت‪ :‬نعــم فــردت عليــه‬\n‫فأمــره ففارقهــا»‪ ،‬ولقولــه صلــى اهلل عليــه وســلم ‪« :‬ال ضــرر وال ضــرار»‬\n‫وملــا رواه النســائي وعبــد الــرزاق عــن ابــن عبــاس رضــي اهلل عنهمــا قــال‪:‬‬\n‫بعثــت أنــا ومعاويــة حكمــن قــال معمــر‪ :‬بلغنــي أن عثمــان بعثهمــا وقــال‬\n\n\n                                                                                          ‫‪312‬‬\n\f      ‫إن رأيتمــا أن جتمعــا جمعتمــا وإن رأيتمــا أن تفرقــا ففرقا»وملــا رواه‬\n      ‫الــدار قطنــي والنســائي والشــافعي والبيهقــي عــن محمــد بــن ســيرين عــن‬\n      ‫عبيــدة قــال‪« :‬جــاء رجــل وامــرأة إلــى علــي مــع كل واحــد منهمــا فئــام‬\n      ‫مــن النــاس فأمرهــم فبعثــوا حكمـ ًا مــن أهلــه وحكمـ ًا مــن أهلهــا وقــال‬\n      ‫للحكمــن هــل تدريــان مــا عليكمــا؟ عليكمــا إن رأيتمــا إن جتمعــا‬\n      ‫فاجمعــا وإن رأيتمــا أن تفرقــا فرقتمــا فقالــت املــرأة‪ :‬رضيــت بكتــاب‬\n      ‫اهلل مبــا علـ ّـي فيــه ولــي ‪ ،‬وقــال الــزوج‪ :‬أمــا الفرقــة فــا‪ ،‬فقــال علــي‪:‬‬\n      ‫كذبــت واهلل ال تبــرح حتــى تقــر مثــل الــذي أقــرت بــه» قــال ابــن حجــر‪:‬‬\n      ‫إســناده صحيــح وملــا أخرجــه الطبــري يف تفســيره‪ :‬عــن ابــن عبــاس رضــي‬\n      ‫اهلل عنهمــا يف احلكمــن أنــه قــال‪ :‬فــإن اجتمــع أمرهمــا علــى أن يفرقــا‬\n      ‫أو يجمعــا فأمرهمــا جائــز ونظــر ًا إلــى أن اســتمرار احليــاة الزوجيــة علــى‬\n      ‫هــذا الوضــع أمــر ال تتحقــق منــه مقاصــد النــكاح يف الشــريعة مــن املــودة‬\n      ‫والرحمــة والســكن وتربيــة األوالد والعفــة مــع مــا يف ذلــك مــن املضــار‬\n      ‫النفســية واالجتماعيــة واجلســدية علــى الزوجــن واألوالد‪ ،‬ونظــر ًا لبقــاء‬\n      ‫املدعيــة ناشــز ًا مــع طــول املــدة أمــر غيــر محمــود شــرع ًا مــع مــا ينشــأ عنــه‬\n      ‫مــن الظلــم واإلثــم والقطيعــة بــن األســر وتوليــد العــداوة والبغضــاء لــذا‬\n      ‫كلــه فقــد فســخت نــكاح املدعيــة ‪ ................‬مــن زوجهــا املدعــى عليــه‬\n      ‫‪ ..........‬وقــدره عشــرون ألــف ريــال وبــه حكمــت وجــرى إفهــام املدعيــة‬\n      ‫بــأن عليهــا العــدة الشــرعية وهــي ثــاث حيــض فقــد ذكــرت أنهــا مــن‬\n      ‫ذوات األقــراء كمــا جــرى إفهــام املدعــى عليــه بــأن زوجتــه قــد بانــت‬\n      ‫منــه بينونــة صغــرى ال حتــل لــه إال بعقــد ومهــر جديديــن وبعــرض احلكــم‬\n      ‫علــى الطرفــن قــررت املدعيــة القناعــة وقــرر املدعــى عليــه عــدم القناعــة‬\n      ‫وجــرى إفهامــه بتعليمــات االعتــراض وجــرى إفهــام الزوجــة بــأن عليهــا‬\n\n\n‫‪313‬‬\n\f‫أن ال تتــزوج وال تتعــرض خلاطــب حتــى يكتســب احلكــم القطعيــة كمــا‬\n‫قــررت التهميــش علــى عقــد النــكاح بحكمــي هــذا بعــد اكتســاب‬\n‫احلكــم القطعيــة وقــررت بعــث العــوض لبيــت املــال يف هــذه احملكمــة‬\n‫حلفظــه لديهــم لصالــح املدعــى عليــه وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n        ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/9‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n‫أنــا ‪ .........‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة والقائــم بعمــل‬\n‫فضيلــة القاضــي ‪ ..........‬أثنــاء تواجــده يف الــدورة التدريبيــة ففــي يــوم‬\n‫الثالثــاء املوافــق ‪1434/2/19‬ه ـ افتتحــت اجللســة بعــد أن عــادت املعاملــة‬\n‫مــن محكمــة االســتئناف وبرفقهــا القــرار رقــم ‪ 3413731‬وتاريــخ‬\n‫‪1434/01/17‬ه ـ ونــص احلاجــة منــه (وبدراســة الصــك وصــورة ضبطــه‬\n‫والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم بفســخ النــكاح‬\n‫مــع مالحظــة التنبيــه املرفــق واهلل املوفــق ) قاضــي اســتئناف ‪............‬‬\n‫ختــم وتوقيــع قاضــي اســتئناف ‪ ....................‬ختــم وتوقيــع رئيــس الدائــرة‬\n‫‪ ..............‬ختــم وتوقيــع عليــه فقــد أمــرت بإثباتــه علــى ضبطــه وســجله‬\n‫حتــى ال يخفــى وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                            ‫آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/02/19‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n‫‪............‬القاضــي يف احملكمــة العامــة مبحافظــة جــدة ويف يــوم األحــد‬\n‫املوافق‪1434/04/21‬ه ـ حضــرت املدعيــة واملعــرف وقــد جــرى االطــاع‬\n‫علــى قــرار التصديــق املرصــود نــص احلاجــة منــه أعــاه فتبــن وجــود‬\n‫تنبيــه مرفــق بــه مــن أصحــاب الفضيلــة قضــاة محكمــة االســتئناف‬\n‫ونــص احلاجــة مــن هــذا التنبيــه ( وحيــث جــرى منــا تصديقــه فإننــا ننبــه‬\n\n\n                                                                                       ‫‪314‬‬\n\f      ‫فضيلتــه إلــى مــا يلــي ‪ -1‬أخــذ اقــرار املدعيــة بأنهــا ال تطالــب باملؤخــر‬\n      ‫واحلاقــه بالصــك وســجله ‪ -2‬الغــاء مــا ورد يف الســطر الثالــث مــن الصــك‬\n      ‫صفحــة رقــم ‪ 2‬وكذلــك يف الضبــط واملقوســة بقلــم الرصــاص ‪ -3‬طلــب‬\n      ‫العقــد والشــرح عليــه مبــا مت مــن قبــل فضيلتــه املرفــق واهلل املوفــق )‬\n      ‫وبعــرض ذلــك علــى املدعيــة قالــت إننــي متنازلــة عــن مؤخــر الصــداق‬\n      ‫وقــدره ثالثــون ألــف ريــال ولــن أطالــب املدعــى عليــه بــه هكــذا قــررت‬\n      ‫وســيجري منــا تــدارك مــا جــاء يف الفقرتــن ‪ 2‬و ‪ 3‬إن شــاء اهلل وبــاهلل‬\n      ‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                          ‫حــرر يف‪1434/04/21‬ه ـ‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد‬\n      ‫فقــد جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية‬\n      ‫واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف‬\n      ‫منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة املســاعد مبحافظــة جــده برقــم ‪33530117‬‬\n      ‫وتاريــخ ‪1434/1/5‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ‬\n      ‫‪ ...........‬القاضــي باحملكمــة العامــة بجــده برقــم ‪ 33450924‬وتاريــخ‬\n      ‫‪1433/11/10‬ه ـ املتضمــن طلــب املــرأة ‪ ..........‬فســخ نكاحهــا مــن‬\n      ‫زوجهــا ‪ ، ........‬وبدراســة الصــك وصــورة ضبطــه والئحتــه االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم بفســخ النــكاح مــع مالحظــة التنبيــه‬\n      ‫املرفــق ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه‬\n                                                                                ‫وســلم ‪.‬‬\n\n\n\n\n‫‪315‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":307,"source_page_end":315,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e5cff5693ae7f896b195ff7a6127f4927d00f857ae4474e1ede95d7e4bc89fc2","normalized_text_hash":"91e7e0b2692511a6feb2452e196c72b28097256165e2936684e5eae9b650b489","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p307-33450924"},{"id":"ddc30d37-5907-5c06-acd7-b50835611a97","document_type":"judgment","category":"judicial","subcategory":"general","title":"زوجية -فسخ نكاح -مطالبة بسكن مستقل -ورد تقرير مكتب الصلح قرر فيه إن املدعى عليه ال يستطيع توفير سكن مستقل - املطالبة بالفسخ للسبب الوارد -حكمت المحكمة بفسخ النكاح دون عوض للسبب الوارد -صدق احلكم .","document_number":"34180146","case_number":"33248843","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/6","year":"1434","subject":"زوجية -فسخ نكاح -مطالبة بسكن مستقل -ورد تقرير مكتب الصلح قرر فيه إن املدعى عليه ال يستطيع توفير سكن مستقل - املطالبة بالفسخ للسبب الوارد -حكمت المحكمة بفسخ النكاح دون عوض للسبب الوارد -صدق احلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫تاريخه‪1434/4/6 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34180146 :‬‬\n                   ‫َر ْق ُم الدعوى‪33248843 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34248843‬تاريخه‪1434/6/21:‬هـ‬\n\n\n‫زوجيــة ‪ -‬فســخ نــكاح ‪ -‬مطالبــة بســكن مســتقل ‪ -‬ورد تقريــر مكتــب‬\n‫الصلــح قــرر فيــه إن املدعــى عليــه ال يســتطيع توفيــر ســكن مســتقل ‪-‬‬\n‫املطالبــة بالفســخ للســبب الــوارد ‪ -‬حكمــت احملكمــة بفســخ النــكاح دون‬\n                               ‫عــوض للســبب الــوارد ‪ -‬صــدق احلكــم ‪.‬‬\n\n\n\n\n               ‫(فإمساك مبعروف أو تسريح بإحسان)‪.‬‬     ‫ٌ‬          ‫‪ .1‬قول اهلل تعالى‬\n‫‪ .2‬قــول الرســول صلــى اهلل عليــه وســلم (امرأتــك تقــول أطعمنــي وإال‬\n                      ‫فارقنــي) رواه أحمــد والــدار قطنــي بإســناد صحيــح‪.‬‬\n‫‪ .3‬قــول البهوتــي (فصــل وإن اعســر الــزوج بنفقتهــا الواجبــة أو أعســر‬\n‫الــزوج ببعضهــا أي بعــض النفقــة بــأن أعســر عــن نفقــة املعســر فلهــا‬\n‫الفســخ وال تفســخ إذا أعســر مبــا زاد عنهــا أي عــن نفقــة املعســر ‪ -‬ألن‬\n‫الزيــادة تســقط بإعســاره أو أعســر الــزوج بالكســوة أو ببعضهــا أو أعســر‬\n‫بالســكنى أو أعســر باملهــر بشــرطه وتقــدم الســابق يف آخــر الصــداق‬\n‫خيــرت علــى التراخــي بــن الفســخ مــن غيــر انتظــار أي تأجيــل ثالث ـ ًا‬\n‫خالفـ ًا البــن البنــاء وبــن املقــام معــه علــى النــكاح وهــذا قــول عمــر وعلــي‬\n                                      ‫وأبــي هريــرة) كشــاف القنــاع‪. 476/5‬‬\n\n\n\n\n                                                                                         ‫‪316‬‬\n\f      ‫ادعــت زوجــة بالدعــوى تطالــب زوجهــا بتأمــن ســكن مســتقل لهــا ‪ -‬أقر‬\n      ‫املدعــى عليــه مبــا جــاء يف دعــوى املدعيــة وذكــر انــه ال مانــع مــن توفيــر‬\n      ‫ســكن مســتقل لهــا متــى مــا اســتطاع وانــه ال يســتطيع يف الوقــت احلاضر‬\n      ‫‪ ،‬أنكــرت املدعيــة مــا ذكــره املدعــى عليــه مــن أنــه ال يســتطيع تأمــن‬\n      ‫الســكن املســتقل ألنــه موظــف يف شــركة (‪ )...‬فســألت احملكمــة‬\n      ‫املدعــى عليــه عــن عملــه وراتبــه الشــهري وذكــر انــه موظــف يف شــركة‬\n      ‫ويتقاضــى راتــب شــهري قــدره ثالثــة آالف وســتمائة ريــال ‪ ،‬وطلبــت‬\n      ‫احملكمــة عقــد النــكاح فأبرزتــه املدعيــة وبعــد االطــاع عليــه تبــن أن‬\n      ‫مــن شــروط املدعيــة يف عقــد النــكاح بيــت مســتقل ‪ ،‬ســألت احملكمــة‬\n      ‫املدعــى عليــه عــن املانــع مــن اســتئجاره لســكن مســتقل لزوجتــه مــع‬\n      ‫وجــود راتبــه الشــهري فذكــر أن لديــه قســط شــهري لســداد قيمــة‬\n      ‫ســيارة قــدره ألــف وســبعمائة وواحــد وســبعون ريــا ًال فأفهمتــه احملكمــة‬\n      ‫بإحضــار مــا يثبــت ذلــك وكتبــت لقســم اخلبــراء لديهــا لإلفــادة عــن مــدى‬\n      ‫كفايــة راتــب املدعــى عليــه الســتئجار ســكن ‪ ،‬ورد للمحكمــة خطاب‬\n      ‫مــن مكتــب الصلــح بأنــه مت االجتمــاع بــن الطرفــن وانــه تعــذر الصلــح‬\n      ‫بينهمــا واتضــح انــه يتقاضــى راتــب قــدره ثالثــة آالف وخمســمائة ريــال‬\n      ‫وأن عليــه أقســاط مســتحقه وأن راتبــه يف الوقــت احلاضــر ال يكفــي‬\n      ‫الســتئجار ســكن ‪ ،‬عرضــت احملكمــة قــرار مكتــب الصلــح علــى‬\n      ‫الطرفــن فطالبــت املدعيــة بفســخ نكاحهــا بــا عــوض ‪ ،‬ورفــض‬\n      ‫املدعــى عليــه الفســخ ‪ ،‬وبعــد تأمــل احملكمــة لقــرار مكتــب الصلح وما‬\n      ‫قــرره املدعــى عليــه مــن عجــزه عــن الســكن املســتقل للمدعيــة واختيــار‬\n\n‫‪317‬‬\n\f‫املدعيــة للفســخ وملــا قــرره الفقهــاء مــن أن الــزوج إذا اعســر بنفقــة الزوجة‬\n‫ومنهــا تأمــن الســكن خيــرت الزوجــة بــن الفســخ مــن غيــر انتظــار أو‬\n‫البقــاء معــه ولقولــه صلــى اهلل عليــه وســلم (امرأتــك تقــول أطعمنــي وإال‬\n‫فارقنــي) لــذا فســخت احملكمــة نــكاح املدعــى عليــه مــن املدعيــة بــدون‬\n‫عــوض وأفهمتهــا بــأن عليــه العــدة الشــرعية ‪ ،‬اعتــرض املدعــى عليــه ‪،‬‬\n                                                                 ‫صــدق احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا(‪ )........‬القاضــي يف احملكمــة العامــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫وتاريــخ ‪1433/04/10‬ه ـ املقيــدة باحملكمــة وتاريــخ ‪1433/4/10‬ه ـ‬\n‫ففــي يــوم الثالثــاء املوافــق ‪1433/06/24‬ه ـ افتتحــت اجللســة وفيهــا‬\n‫حضــرت (‪ )........‬ســعودية (املعــرف بهــا مــن قبــل والدهــا ســعودي)‬\n‫وادعــت علــى احلاضــر (‪ )........‬ســعودي قائلــة يف دعواهــا‪ :‬إن املدعــى‬\n‫عليــه هــذا احلاضــر معــي زوجــي مبوجــب عقــد النــكاح لــدى مــأذون‬\n‫األنكحــة (‪ )........‬وتاريــخ ‪1430/6/6‬ه علــى مهــر وقــدره خمســون‬\n‫ألــف ريــال مقبوضــة ودخــل بــي الدخــول الشــرعي وأجنبــت منــه (‪)........‬‬\n‫املولــود يف ‪1431/7/16‬ه ـ وأخرجنــي مــن بيتــي إلــى بيــت أهلــي يف‬\n‫‪1432/6/28‬ه ـ حيــث قــال لــي روحــي ألهلــك ألننــي طلبــت منــه ســكن ًا‬\n‫ال لــي ألنــه أســكنني يف بيــت أهلــه املســتأجر فاتصلــت علــى‬     ‫مســتق ً‬\n‫أهلــي وأخذونــي ثــم بعــد أســبوعني أحضــر عفشــي إلــى بيــت أهلــي وإلــى‬\n‫اآلن لــم يجعــل لــي بيــت مســتقل حســب شــرط العقــد لــذا اطلــب أن يجعــل‬\n‫لــي ســكنا مســتقال هــذه دعــواي وبعرضهــا علــى املدعــى عليــه أجــاب‬\n                                                                                      ‫‪318‬‬\n\f      ‫قائــا‪ :‬مــا ذكرتــه املدعيــة مــن زواجــي بهــا والدخــول واملهــر واجنابهــا‬\n      ‫(‪ )........‬وســلمت لهــا مــن النفقــة ســتمائة ريــال فقــط فهــذا كلــه صحيــح‬\n      ‫ومــا ذكرتــه أننــي طلبــت منهــا الذهــاب إلــى أهلهــا فغيــر صحيــح بــل‬\n      ‫خرجــت مــن نفســها ألنهــا ترفــض اســتمرار الســكن مــع أهلــي وأنــا ال‬\n      ‫ال متــى اســتطعت وأمــا االن‬‫مانــع لــدي مــن أن أجعــل لهــا ســكن ًا مســتق ً‬\n      ‫فــا أســتطيع هكــذا أجــاب‪ .‬ويف يــوم االثنــن املوافــق ‪1433/11/01‬ه ـ‬\n      ‫افتتحــت اجللســة وفيهــا حضــرت (‪ )........‬املعــرف بهــا مــن قبــل والدهــا‬\n      ‫(‪ )........‬واملدعــى عليــه (‪ )........‬وبعــرض مــا ذكــره املدعــى عليــه يف‬\n      ‫اجللســة املاضيــة علــى املدعيــة أجابــت قائلــة‪ :‬مــا ذكــره املدعــى عليــه‬\n      ‫أنــه ال يســتطيع أن يســتأجر لــي ســكن ًا فغيــر صحيــح بــل يســتطيع‬\n      ‫وهــو موظــف يف شــركة هكــذا أجابــت وبســؤال املدعــى عليــه عــن‬\n      ‫وظيفتــه وراتبــه الشــهري أجــاب قائــا ‪ :‬أعمــل رجــل أمــن يف شــركة‬\n      ‫خاصــة وراتبــي الشــهري قــدره ثالثــة آالف وســتمائة ريــال هكــذا‬\n      ‫أجــاب وبطلــب عقــد الــزواج أبــرزت املدعيــة صــورة مــن ضبــط عقــد زواج‬\n      ‫للســعوديني وتاريــخ ‪1430/6/6‬ه ـ لــدى مــأذون األنكحــة واملتضمــن‬\n      ‫عقــد الــزواج بــن املدعيــة واملدعــى عليــه ومــن شــروطه بيــت مســتقل‪.‬‬\n      ‫أ‪.‬ه ـ وبســؤال املدعــى عليــه عــن املانــع لــه مــن اســتئجار ســكن لزوجتــه‬\n      ‫مــع وجــود راتبــه الشــهري أجــاب قائــا ‪ :‬لــدي قســط شــهري قــدره ألــف‬\n      ‫وســبعمائة وواحــد وســبعون ريــال الســداد ثمــن الســيارة هكــذا أجــاب‬\n      ‫وأفهمتــه بإحضــار مــا يثبــت ذلــك القســط كمــا أمــرت بالكتابــة إلــى‬\n      ‫قســم اخلبــراء لإلفــادة عــن مــدى كفايــة راتــب املدعــى عليــه الســتئجار‬\n                                                                            ‫ســكن‪.‬‬\n      ‫ويف يــوم الســبت املوافــق ‪1434/04/06‬ه ـ افتتحــت اجللســة وفيهــا‬\n\n\n‫‪319‬‬\n\f‫حضــرت املدعيــة املعــرف بهــا مــن قبــل أخوهــا (‪ )........‬ســعودي مبوجــب‬\n‫ســجل مدنــي رقــم (‪ )........‬وحضــر املدعــى عليــه ووردنــا خطــاب مديــر‬\n‫مكتــب الصلــح برقــم (‪ )........‬وتاريــخ ‪1434/3/25‬ه ـ املتضمــن أنــه مت‬\n‫االجتمــاع بالطرفــن وقــد تعــذر الصلــح بينهمــا واملدعيــة تطالــب املدعــى‬\n‫عليــه بتأمــن املســكن وأنــه ال يســتطيع تأمــن املســكن يف الوقــت‬\n‫احلاضــر وبعــد نهايــة األقســاط املســتحقة عليــه ســوف يقــوم بتأمــن‬\n‫املســكن وجتــدون إقــرار كال منهمــا بطــي املعاملــة وبنــاء علــى ذلــك‬\n‫واحلــال كمــا ذكــر وبعــد االطــاع علــى مقــدار مرتــب املدعــى عليــه‬\n‫حيــث اتضــح أنــه يتقاضــى مرتــب ‪ 3500‬ريــال وذلــك حســب اخلطــاب‬\n‫املرفــق رقــم بــدون وتاريــخ ‪1434/2/3‬ه ـ الصــادر مــن إدارة املجاهديــن‬\n‫وكذلــك كشــف احلســاب املرفــق واألقســاط املســتحقة عليــه وبعــد‬\n‫التأمــل يف الوضــع املــادي للمدعــى عليــه فإننــا نــرى إنــه تكــون النفقــة‬\n‫الســابقة واملســتقبلية للمدعيــة وابنهــا ‪ 400‬ريــال شــهري ًا لــكل واحــد‬\n‫منهمــا أمــا بخصــوص مــدى كفايــة راتــب املدعــى عليــه الســتئجار‬\n‫ســكن فإننــا نــرى أنــه غيــر كايف حيــث أنــه بعــد خصــم القســط‬\n‫املســتحق عليــه ونفقتــه علــى املدعيــة وابنهــا ال يتبقــى مــن مرتبــه إال‬\n‫الشــيء القليــل هــذا مــا لدينــا‪ .‬أ‪.‬ه ـ وبعرضــه علــى املدعيــة أجابــت قائلــة‪:‬‬\n‫أطلــب فســخ النــكاح بــدون عــوض هكــذا أجابــت‪ .‬وبعرضــه علــى‬\n‫املدعــى عليــه أجــاب قائــا‪ :‬أرفــض فســخ النــكاح هكــذا أجــاب‪ .‬فبنــاء‬\n‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وقــرار مكتــب الصلــح ومــا قــرره‬\n‫املدعــى عليــه مــن عجــزه عــن الســكن املســتقل للمدعيــة واختيارهــا‬\n‫فســخ النــكاح بــدون عــوض وملــا قــرره الفقهــاء يف حــال إعســار الــزوج‬\n‫بالســكنى قــال يف كشــاف القنــاع (‪ (476/5‬فصــل وإن أعســر الــزوج‬\n\n\n                                                                                       ‫‪320‬‬\n\f      ‫بنفقتهــا الواجبــة أو أعســر الــزوج ببعضهــا أي بعــض النفقــة بــأن أعســر‬\n      ‫عــن نفقــة املعســر فلهــا الفســخ وال تفســخ إذا أعســر مبــا زاد عنهــا أي عــن‬\n      ‫نفقــة املعســر‪ ،‬ألن الزيــادة تســقط بإعســاره أو أعســر الــزوج بالكســوة‬\n      ‫أو ببعضها أو أعســر بالســكنى أو أعســر باملهر بشــرطه وتقدم الســابق‬\n      ‫يف آخــر الصــداق خيــرت علــى التراخــي بــن الفســخ مــن غيــر انتظــار أي‬\n      ‫تأجيــل ثالث ـ ًا خالف ـ ًا البــن البنــاء وبــن املقــام معــه علــى النــكاح وهــذا‬\n      ‫قــول عمــر وعلــي وأبــي هريــرة لقولــه تعالــى‪( :‬فإمســاك مبعــروف أو‬\n      ‫تســريح بإحســان) وليــس اإلمســاك مــع تــرك اإلنفــاق إمســاكا مبعــروف‬\n      ‫فتعــن التســريح وقــال صلــى اهلل عليــه وســلم‪( :‬امرأتــك تقــول أطعمنــي‬\n      ‫وإال فارقنــي) رواه أحمــد والدارقطنــي والبيهقــي بإســناد صحيــح ورواه‬\n      ‫الشــيخان مــن قــول أبــي هريــرة‪ .‬لــذا فســخت نــكاح املدعــى عليــه مــن‬\n      ‫املدعيــة بــدون عــوض وبــه حكمــت وأفهمــت املدعيــة أن عليهــا العــدة‬\n      ‫الشــرعية ثــاث حيــض وأن ال تتــزوج إال بعــد اكتســاب احلكــم القطعية‬\n      ‫وبإعــان احلكــم قــرر املدعــى عليــه املعارضــة وطلــب االســتئناف فســلم‬\n      ‫صــورة احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن يوم ـ ًا فــإن مضــت‬\n      ‫املــدة ولــم يقــدم الئحــة اعتراضــه ســقط حقــه يف االعتــراض واكتســب‬\n      ‫احلكــم القطعيــة وأفهمــت املدعــى عليــه أن عليــه تســجيل هــذه الواقعــة‬\n      ‫يف إدارة األحــوال املدنيــة متــى اكتســب احلكــم القطعيــة وبــاهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                                       ‫يف ‪1434/4/6‬ه ـ‬\n      ‫ويف يــوم الثالثــاء ‪1434/09/01‬ه ـ حســب تقــومي أم القــرى و‬\n      ‫‪1434/08/30‬ه ـ حســب الرؤيــة افتتحــت اجللســة الســاعة ‪ 09.00‬بنــاء‬\n      ‫علــى ورود املعاملــة بشــرح رئيــس احملكمــة علــى القيــد رقــم وتاريــخ‬\n\n\n‫‪321‬‬\n\f‫‪1434/7/30‬ه ـ وبرفقــه خطــاب رئيــس محكمــة االســتئناف وتاريــخ‬\n‫‪1434/06/28‬ه ـ وبرفقــه قــرار دائــرة األحــوال الشــخصية الثانيــة‬\n‫وتاريــخ ‪1434/6/21‬ه ـ ونصــه مــا يلــي ‪ :‬وبدراســة الصــك وصــورة‬\n‫ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة‬\n‫علــى احلكــم وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                             ‫وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثانيــة‬\n‫املختصــة بنظــر قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة‬\n‫االســتئناف علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫وتاريــخ ‪1434/6/14‬ه املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ (‪ . )........‬وتاريــخ ‪1434/4/6‬ه ـ اخلــاص بدعــوى‬\n‫(‪ )........‬ضــد (‪ )........‬بشــأن فســخ نــكاح ‪ ،‬وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫والالئحــة االعتراضيــة وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى‬\n‫احلكــم ‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد و علــى آلــه وصحبــه‬\n                                                                        ‫وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪322‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":316,"source_page_end":322,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"58f51fa7257b1e10d5128b0baaa46d40101dd67699e223ec9b570461a7d5f511","normalized_text_hash":"e5bae316e6e1717ccc51805729f923e95bf22fd8375599960c7a62e1fb259c99","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p316-34180146"},{"id":"2c5bd33a-2f9a-5628-ad18-db0a41b8bf32","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول للضرر كون الزوج يف غيبوبة مدة أربع سنوات -الغيبوبة مرض يذهب مقصد االستمتاع بن الزوجن ويوجب اخليار للزوجة -احلكم بفسخ النكاح دون عوض .","document_number":"34234714","case_number":"33260543","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"فسخ نكاح -طلب الزوجة فسخ النكاح بعد الدخول للضرر كون الزوج يف غيبوبة مدة أربع سنوات -الغيبوبة مرض يذهب مقصد االستمتاع بن الزوجن ويوجب اخليار للزوجة -احلكم بفسخ النكاح دون عوض .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/6/7 :‬هـ‬\n                      ‫ُ‬                ‫َر ْق ُم َّ‬\n                         ‫الص ِّك‪34234714 :‬‬\n                        ‫َر ْق ُم الدعوى‪33260543 :‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34262527‬تاريخه‪1434/7/9:‬هـ‬\n\n\n      ‫فســخ نــكاح ‪ -‬طلــب الزوجــة فســخ النــكاح بعــد الدخــول للضــرر كــون‬\n      ‫الــزوج يف غيبوبــة مــدة أربــع ســنوات ‪ -‬الغيبوبــة مــرض يذهــب مقصــد‬\n      ‫االســتمتاع بــن الزوجــن ويوجــب اخليــار للزوجــة ‪ -‬احلكــم بفســخ‬\n                                                        ‫النــكاح دون عــوض ‪.‬‬\n\n\n\n\n            ‫تضاروهن لتذهبوا ببعض ما أتيتموهن ) ‪.‬‬      ‫ُّ‬     ‫‪ .1‬قوله تعالى‪ ( :‬وال‬\n                           ‫‪ .2‬قوله صلى اهلل عليه وسلم ( ال ضرر وال ضرار ) ‪.‬‬\n      ‫‪ .3‬قــال يف كشــاف القنــاع ( ويثبــت اخليــار يف فســخ النــكاح بجــذام أو‬\n      ‫بــرص أو جنــون ولــو أفــاق أحيانــا ألن النفــس ال تســكن إلــى مــن هــذه‬\n                                                            ‫حالــه ) ( ‪. ) 404/11‬‬\n\n\n\n\n      ‫ادعــت املدعيــة علــى املدعــى عليــه الغائــب عــن مجلــس احلكــم أنــه‬\n      ‫تزوجهــا وأجنبــت منــه علــى فــراش الزوجيــة ثالثــة أوالد‪ ،‬وأنــه أصيــب‬\n      ‫بجلطــة قبــل أربــع ســنوات نتيجــة ارتفــاع ضغــط الــدم‪ ،‬وأنــه مــن ذلــك‬\n      ‫احلــن وهــو يف املستشــفى يف غيبوبــة وتضــررت مــن بقائهــا يف عصمتــه‪،‬‬\n      ‫وطلبت فسخ نكاحها منه ‪ ،‬ورد التقرير الطبي املتضمن ‪ :‬بأن املريض‬\n      ‫طريــح الفــراش وال يســتطيع احلركــة وال يتواصــل مــع احمليطــن بــه وهــو‬\n\n‫‪323‬‬\n\f‫يف غيبوبــة ســباتية ناجتــة عــن نزيــف ســابق باملــخ والتنفــس عــن طريــق‬\n‫أنبوبــه الشــق احلنجــري والتغذيــة عــن طريــق األنبوبــة األنفيــة املعديــة إ‪.‬ه ـ‬\n‫‪ ،‬أحضــرت املدعيــة شــاهدين ‪ ،‬ومت ســماع شــهادتهما ‪ ،‬وتعديلهمــا ‪،‬‬\n‫جــرى االطــاع علــى عقــد النــكاح فوجــد مطابقـ ًا لدعــوى املدعيــة ‪ ،‬مــا‬\n‫ورد يف التقريــر الطبــي يشــهد بصحــة مــا جــاء يف دعــوى املدعيــة‪ ،‬ومــا‬\n‫جــاء يف شــهادة الشــهود‪ ،‬وألن املــرض الواقــع علــى زوج املدعيــة يذهــب‬\n‫مقصــد االســتمتاع بــن الزوجــن ‪ ،‬وبقــاء املدعيــة يف عصمــة زوجهــا مــع‬\n‫مرضــه ويف هــذه املــدة الطويلــة ضــرر عليهــا وألن املــرض الواقــع باملدعــى‬\n‫عليــه ممــا يثبــت بــه اخليــار للمدعيــة ‪ ،‬وألن الضــرر يــزال يف الشــريعة ‪،‬‬\n‫لــذا مت احلكــم بفســخ نــكاح املدعيــة مــن زوجهــا املدعــى عليــه وجــرى‬\n‫إفهــام املدعيــة بــأن عليهــا العــدة الشــرعية ‪ ،‬وأنهــا بانــت مــن زوجهــا‬\n‫بينونــة صغــرى ال حتــل لــه إال مبهــر وعقــد جديديــن وبرضاهــا كمــا‬\n‫جــرى إفهامهــا بأنهــا ال تتــزوج حتــى يكتســب احلكــم الصفــة القطعيــة‬\n           ‫‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n‫العامــة مبحافظــة جــدة بنــاء علــى االســتدعاء احملــال لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪33260543‬‬\n‫وتاريــخ ‪1433/04/13‬ه ـ املقيــد باحملكمــة برقــم ‪ 33701310‬وتاريــخ‬\n‫‪1433/04/13‬ه ـ ففــي يــوم الســبت املوافــق ‪1433/08/24‬ه ـ افتتحــت‬\n‫اجللســة الســاعة (‪ )10:15‬وفيهــا حضــرت املدعيــة (‪ )........‬مبوجــب‬\n‫اإلقامــة رقــم (‪ )........‬ولــم يحضــر املدعــى عليــه (‪ )........‬وال مــن ميثلــه‬\n                                                                                        ‫‪324‬‬\n\f      ‫بوكالــة شــرعية ولــم يردنــا مــا يفيــد تبلغــه مبوعــد هــذه اجللســة لــذا فقــد‬\n      ‫تقــرر رفــع اجللســة وتأجيلهــا إلــى يــوم األحــد املوافــق ‪1434/01/11‬ه ـ‬\n      ‫وبــاهلل التوفيــق ثــم بتاريــخ ‪1434/2/17‬ه ـ افتتحــت اجللســة وفيهــا‬\n      ‫حضــرت املدعيــة (‪ )........‬وحضــر حلضورهــا املترجــم (‪، )........‬‬\n      ‫بنجالديشــي اجلنســية مبوجــب اإلقامــة رقــم (‪ )........‬حيــث أن املدعيــة‬\n      ‫تتكلــم اللغــة البرماويــة وال جتيــد اللغــة العربيــة ولــم يحضــر املدعــى‬\n      ‫عليــه (‪ )........‬وال مــن ميثلــه بوكالــة شــرعية وقــد قــررت املدعيــة قائلــة‬\n      ‫إن املدعــى عليــه ‪ .........‬مريــض منــذ أربــع ســنوات وقــد أبــرزت مــن‬\n      ‫يدهــا صــورة إشــعار تنــومي بتاريــخ ‪1432/10/27‬ه ـ جــاء فيــه ( تشــهد‬\n      ‫مستشــفى ‪ ...........‬بحــداء بــأن املريــض أعــاه منــوم لدينــا باملستشــفى‬\n      ‫محــوال إلينــا بتاريــخ ‪1430/09/04‬ه ـ مــن مستشــفى النــور التخصصــي‬\n      ‫ومــا زال منومــا حتــى تاريــخ حتريــر هــذا اإلشــعار ‪1430/10/27‬ه ـ )‬\n      ‫أ‪.‬ه ـ ‪ ،‬عليــه فقــد تقــرر الكتابــة ملستشــفى ‪ ............‬بحــداء طريــق‬\n      ‫مكــة القــدمي لالستفســار عــن حــال املدعــى عليــه وموافاتنــا بتقريــر‬\n      ‫وايف ومفصــل عــن حالــة املذكــور واإلفــادة وحتــى ورود اجلــواب فقــد‬\n      ‫تقــرر رفــع اجللســة ثــم بتاريــخ ‪ 1434/06/04‬ه ـ افتتحــت اجللســة وفيهــا‬\n      ‫حضــرت املدعيــة ‪...........‬وحضــر حلضورهــا املترجــم يف هــذه احملكمــة‬\n      ‫‪ .............‬وبســؤال املدعيــة عــن دعواهــا أجابــت قائلــه ان املدعــى عليــه‬\n      ‫‪ ...........‬زوجــي تــزوج بــي مبوجــب عقــد شــرعي صحيــح ودخــل بــي‬\n      ‫الدخــول الشــرعي وقــد أجنبــت منــه علــى فــراش الزوجيــة ب‪.......‬‬\n      ‫وعمــره اآلن تســعة أعــوام و‪ .......‬وعمــره اآلن ســتة أعــوام و‪ .....‬وعمرهــا‬\n      ‫اآلن أربعــة أعــوام وقــد أصيــب بجلطــة نتيجــة ارتفــاع ضغــط الــدم وكان‬\n      ‫ذلــك قبــل أربعــة أعــوام ومــن ذلــك احلــن وزوجــي مريــض يف املستشــفى‬\n\n\n‫‪325‬‬\n\f‫لــم نســمع لــه صوتــا فهــو يف غيبوبــة وقــد تضــررت مــن بقائــي يف عصمتــه‬\n‫وهــو ال يعــي شــيئا أطلــب احلكــم بفســخ نكاحــي مــن املدعــى عليــه‬\n‫هــذه دعــواي وقــد وردنــا اخلطــاب الصــادر مــن مستشــفى ‪ .........‬بحــداء‬\n‫ذي الرقــم ‪ 93‬وتاريــخ ‪1434/2/23‬ه ـ واملقيــد بهــذه احملكمــة برقــم‬\n‫‪ 34584575‬وتاريــخ ‪1434/03/07‬ه ـ واملتضمــن مــا يلــي ( أن املريــض‬\n‫املذكــور حاليــا طريــح فــراش وال يســتطيع احلركــة وال يتواصــل مــع‬\n‫احمليطــن بــه وهــو يف غيبوبــة ســباتية ناجتــة عــن نزيــف ســابق باملــخ‬\n‫والتنفــس عــن طريــق أنبوبــه الشــق احلنجــري والتغذيــة عــن طريــق‬\n‫األنبوبــة األنفيــة املعديــة وذلــك منــذ إحالتــه إلينــا مــن مستشــفى النــور‬\n‫التخصصــي مبكــة املكرمــة بتاريــخ ‪1430/09/04‬ه ـ حتــى تاريخــه )‬\n‫وبعــد االطــاع علــى التقريــر املرفــق وبســؤال املدعيــة وهــل لديهــا مزيــد‬\n‫مــن البينــات علــى مــا جــاء ويف دعواهــا فأجابــت قائلــة نعــم لــدي املزيــد‬\n‫منهــا ومســتعدة بإحضارهــا يف اجللســة القادمــة فأجيــب لطلبهــا وتقــرر‬\n‫رفــع اجللســة لذلــك وتأجلــت إلــى يــوم األربعــاء املوافــق ‪1434/06/07‬ه ـ‬\n‫وبــاهلل التوفيــق ‪ .‬ثــم بتاريــخ ‪1434/6/7‬ه ـ افتتحــت اجللســة وفيهــا‬\n‫حضــرت املدعيــة ‪ ..................‬وقــد أبــرزت املدعيــة مــن يدهــا عقــد‬\n‫النــكاح الصــادر مــن احملكمــة العامــة مبكــة املكرمــة ذي الرقــم‬\n‫‪ ..............‬وتاريــخ ‪1425/08/27‬ه ـ والــذي جــرى االطــاع عليــه فوجــد‬\n‫مطابقــا ملــا جــاء يف دعواهــا وبســؤالها عمــا طلبــت املهلــة ألجلــه أحضــرت‬\n‫للشــهادة وأدائهــا ‪ ، ..............‬بنجالديشــي اجلنســية مبوجــب اإلقامــة رقــم‬\n‫‪ ..........‬ويظهــر أن تاريــخ ميــاده هــو ‪1399/01/01‬ه ـ وبســؤاله عــن‬\n‫معلوماتــه املدنيــة بعــد ظهــور معرفتــه العربيــة حتدثــا وفهمــا أجــاب قائــا‬\n‫إننــي أســكن يف كيلــو أربعــة عشــر يف مدينــة جــدة ومتــزوج ولــي أوالد‬\n\n\n                                                                                     ‫‪326‬‬\n\f      ‫وأعمــل يف مؤسســة خاصــة وأعــرف املدعيــة وزوجهــا مــن زمــن وأشــهد‬\n      ‫بــاهلل العظيــم أن زوج املدعيــة واســمه ‪..........‬مريــض يف غيبوبة منذ أربعة‬\n      ‫أعــوام وقــد زرتــه يف املستشــفى مــرارا هــذا مــا أشــهد بــه وقــد أحضــرت‬\n      ‫املدعيــة كذلــك للشــهادة وأدائهــا ‪ ، ................‬اجلنســية ميامنــار مبوجــب‬\n      ‫اإلقامــة رقــم ………… ويظهــر أن تاريــخ ميــاده هــو ‪1981/01/01‬م‬\n      ‫وبســؤاله عــن معلوماتــه املدنيــة أجــاب قائــا إننــي أســكن يف كيلــو‬\n      ‫أربعــة عشــر يف مدينــة جــدة ومتــزوج وال أوالد لــي وأعمــل يف ســوق‬\n      ‫الصواريــخ يف جــدة واملدعيــة وزوجهــا كانــوا يســكنون معنــا يف احلــي‬\n      ‫وأشــهد بــاهلل العظيــم أن زوج املدعيــة واســمه ‪ .........‬مريــض عــن مــا يزيــد‬\n      ‫عــن أربعــة أعــوام مغمــى عليــه وقــد زرتــه يف املستشــفى هــذا مــا أشــهد‬\n      ‫بــه وقــد أحضــرت املدعيــة كذلــك للشــهادة وأدائهــا كال مــن ‪.........‬‬\n      ‫‪ ،‬بنجالديشــي اجلنســية مبوجــب اإلقامــة رقــم ‪ ........‬و‪ ، ..........‬اجلنســية‬\n      ‫ميامنــار مبوجــب اإلقامــة رقــم ……‪ .‬وشــهد كل واحــد منهمــا مبفــرده‬\n      ‫أن كال مــن ‪ .......‬و‪ ............‬عــدول ومقبولــن الشــهادة فبنــاءا علــى مــا‬\n      ‫تقــدم مــن الدعــوى وحيــث أن املدعيــة قــد ادعــت مــرض زوجهــا مرضــا‬\n      ‫مزمنــا وتضررهــا مــن ذلــك حيــث أنــه قــد بقــي مــدة طويلــة وطلبهــا فســخ‬\n      ‫النــكاح وحيــث قــد ورد التقريــر الطبــي يشــهد بصحــة مــا جــاء يف‬\n      ‫دعــوى املدعيــة مــن مــرض زوجهــا ملــدة طويلــة وحيــث أن املدعيــة كذلــك‬\n      ‫قــد أحضــرت بينــة موصلــة تشــهد لصحــة دعواهــا مــن شــهادة الشــهود‬\n      ‫وحيــث أن املــرض الواقــع علــى زوج املدعيــة يذهــب مقصــد االســتمتاع‬\n      ‫الــذي هــو مــن مقاصــد الــزوج والزوجــة وحيــث أ‪ ،‬يف بقــاء املدعيــة يف‬\n      ‫عصمــة زوجهــا مــع مرضــه ويف هــذه املــدة الطويلــة ضــرر علــى املدعيــة‬\n      ‫وحيــث أن املــرض الواقــع باملدعــى عليــه ممــا يثبــت بــه اخليــار للمدعيــة‬\n\n\n‫‪327‬‬\n\f‫قــال يف كشــاف القنــاع ( ويثبــت اخليــار يف فســخ النــكاح بجــذام أو‬\n‫بــرص أو جنــون ولــو أفــاق أحيانــا ألن النفــس ال تســكن إلــى مــن هــذه‬\n‫حالــه ) (‪ )404/11‬وحيــث أن الضــرر يــزال يف الشــريعة بقــول اهلل تعالــى‬\n‫( وال تضاروهــن لتذهبــوا ببعــض مــا أتيتموهــن) وقــول النبــي صلــى اهلل‬\n‫عليــه وســلم ( ال ضــرر وال ضــرار ) وحيــث أن الواقــع مــن خــال مــا دون‬\n‫أعــاه يظهــر أنــه يتعــذر تبليــغ املدعــى عليــه باحلكــم جلميــع ما تقــدم فقد‬\n‫فســخت نــكاح املدعيــة ‪ .............‬مــن زوجهــا ‪ ............‬وبذلــك حكمــت‬\n‫وأفهمــت املدعيــة بــأن عليهــا العــدة الشــرعية حســب حالهــا وأنهــا بانــت‬\n‫مــن زوجهــا بينونــة صغــرى ال حتــل لــه إال مبهــر وعقــد جديديــن وبرضاها‬\n‫كمــا أفهمتهــا بأنهــا ال تتــزوج حتــى يكتســب احلكــم الصفــة القطعيــة‬\n‫وأمــرت بالتهميــش علــى عقــد النــكاح مبــا انتهــى إليــه الطرفــان بعــد‬\n‫تصديــق احلكــم مــن محكمــة االســتئناف وبعثــه إلــى مرجعــه لنقلــه يف‬\n‫ســجله وأمــرت برفــع كامــل أوراق املعاملــة إلــى محكمــة االســتئناف‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                       ‫حــرر يف ‪1434/6/7‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن‬\n‫محكمــة االســتئناف مبكــة املكرمــة برقــم ‪ 33/701310‬وتاريــخ‬\n‫‪1434/07/11‬ه ـ واملقيــدة بهــذه احملكمــة برقــم ‪ 33/701310‬وتاريــخ‬\n‫‪1434/07/15‬ه ـ واملصدقــة مــن الدائــرة الثالثــة لألحــوال الشــخصية‬\n‫واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف‬\n‫مبكــة املكرمــة بالقــرار الصــادر مــن أصحــاب الفضيلــة قضــاة‬\n‫محكمــة االســتئناف رقــم ‪ 34262527‬وتاريــخ ‪1434/07/09‬ه ـ‬\n‫املتضمــن مــا نصــه ‪ :‬وبدراســة الصــك وصــورة ضبطــه تقــرر املوافقــة‬\n\n\n                                                                                     ‫‪328‬‬\n\f      ‫علــى احلكــم بفســخ النــكاح مالحظــة التنبيــه املرفــق وبــاهلل التوفيــق‬\n      ‫‪ .‬أ‪.‬ه ـ ‪ ،‬قاضــي اســتئناف ختــم وتوقيــع ‪ ...............‬وقاضــي اســتئناف‬\n      ‫ختــم وتوقيــع ‪ .............‬ورئيــس الدائــرة ختــم وتوقيــع ‪ ، ..........‬عليــه فقــد‬\n      ‫أمــرت بإحلــاق ذلــك بالضبــط وســجله وبــاهلل التوفيــق وصلــى اهلل علــى‬\n         ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/07/23‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده ‪ ،‬وبعــد فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة الثالثــة لألحــوال الشــخصية واألوقــاف‬\n      ‫والوصايــا والقصــار وبيــوت املــال مبحكمــة االســتئناف يف منطقــة‬\n      ‫مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة مبحافظــة جــده املســاعد برقــم ‪ 33/701310‬وتاريــخ‬\n      ‫‪1434/7/2‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪...........‬‬\n      ‫القاضــي باحملكمــة العامــة مبحافظــة جــده برقــم ‪ 34234714‬وتاريــخ‬\n      ‫‪1434/6/7‬ه ـ ‪ ،‬املتضمــن دعــوى املــرأة ‪ ........‬بنقاليــه اجلنســية ضــد‬\n      ‫‪ ...........‬اجلنســية يف فســخ نكاحهــا مــن املدعــى عليــه ‪ ،‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه ‪ ،‬تقــررت املوافقــة علــى احلكــم بفســخ النــكاح ‪ ،‬مــع‬\n      ‫مالحظــة التنبيــه املرفــق ‪ ،‬واهلل املوفــق ‪ .‬وصلــى اهلل علــى نبينــا محمــد‬\n                                                          ‫وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪329‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":323,"source_page_end":329,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1d78ca5b527518b420e6acb14577a09021be3cbcff7901d4030201b1c26ae0f7","normalized_text_hash":"ef0830d12e1f3ceb3fa7161a513255ae8d7d31f5877f419b4717c3e5cc756d94","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p323-34234714"},{"id":"ed650b08-6362-58a0-8cde-6220d6a9e0a1","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح -طلب الزوجة الفسخ بعد الدخول لطروء إعاقة عقلية على الزوج -إنكار ولي الزوج اإلعاقة العقلية -صك الوالية مثبت به اإلعاقة العقلية -ما قرره األطباء من التخلف العقلي للزوج -اجلنون عيب يثبت به اخليار -اخليار يثبت بحدوث العيب بعد العقد ولو بعد الدخول -احلكم بفسخ نكاح املدعية من زوجها با","document_number":"3457561","case_number":"33406385","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة القطيف ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/8","year":"1434","subject":"فسخ نكاح -طلب الزوجة الفسخ بعد الدخول لطروء إعاقة عقلية على الزوج -إنكار ولي الزوج اإلعاقة العقلية -صك الوالية مثبت به اإلعاقة العقلية -ما قرره األطباء من التخلف العقلي للزوج -اجلنون عيب يثبت به اخليار -اخليار يثبت بحدوث العيب بعد العقد ولو بعد الدخول -احلكم بفسخ نكاح املدعية من زوجها با","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫تاريخه‪1434/3/8 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                     ‫الص ِّك‪3457561 :‬‬\n                   ‫َر ْق ُم الدعوى‪33406385 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 3522928‬تاريخه‪1434/5/25:‬هـ‬\n\n\n‫فســخ نــكاح ‪ -‬طلــب الزوجــة الفســخ بعــد الدخــول لطــروء إعاقــة عقليــة‬\n‫علــى الــزوج ‪ -‬إنــكار ولــي الــزوج اإلعاقــة العقليــة ‪ -‬صــك الواليــة مثبــت‬\n‫بــه اإلعاقــة العقليــة ‪ -‬مــا قــرره األطبــاء مــن التخلــف العقلــي للــزوج‬\n‫‪ -‬اجلنــون عيــب يثبــت بــه اخليــار ‪ -‬اخليــار يثبــت بحــدوث العيــب بعــد‬\n‫العقــد ولــو بعــد الدخــول ‪ -‬احلكــم بفســخ نــكاح املدعيــة مــن زوجهــا بــا‬\n                                                                       ‫عــوض ‪.‬‬\n\n\n\n\n                   ‫‪ .1‬قوله صلى اهلل عليه وآله وسلم (ال ضرر وال ضرار)‪.‬‬\n‫‪ .2‬مــا نــص عليــه الفقهــاء مــن أن اجلنــون عيــب يثبــت بــه اخليــار‪ .‬انظــر‬\n                                                     ‫كشــاف القناع ‪405/11‬‬\n‫‪ .3‬مــا قــرره الفقهــاء مــن ثبــوت اخليــار بحــدوث العيــب بعــد العقــد ولــو‬\n‫بعــد الدخــول وأن الــزوج ال يرجــع باملهــر‪ .‬انظــر كشــاف القناع ‪409/11‬‬\n\n\n\n\n‫ادعــت املدعيــة علــى املدعــى عليــه أنــه تزوجهــا وأجنبــت منــه ثالثــة‬\n‫أوالد‪ ،‬وأنــه أصيــب بحــادث مــروري ممــا أدى إلــى إصابتــه بإعاقــة‬\n‫عقليــة وجســمية ‪ ،‬وأنهــا صبــرت عليــه ولكنهــا تعبــت ‪ ،‬ولــم تعــد تطيــق‬\n‫العيــش معــه‪ ،‬وطلبــت فســخ نكاحهــا منــه ‪ ،‬حضــر حلضــور املدعيــة‬\n\n                                                                                    ‫‪330‬‬\n\f      ‫الولــي الشــرعي علــى املدعــى عليــه مبوجــب صــك الواليــة الصــادر مــن‬\n      ‫احملكمــة برقــم ‪ ....‬يف ‪ ....‬وبعــرض دعــوى املدعيــة عليــه‪ ،‬صــادق عليها‪،‬‬\n      ‫ســوى مــا ذكرتــه أنــه مصــاب بإعاقــة عقليــة وذكــر أن الصحيــح أنــه‬\n      ‫مصــاب بإعاقــة جســمية وصعوبــة يف النطــق وأنــك إذا ســألته ســؤا ًال‬\n      ‫يجيــب إجابــة صحيحــة ‪ ،‬وقــرر أنــه ال مانــع لديــه مبــا طلبتــه املدعيــة ‪،‬‬\n      ‫ا أو عيب ـ ًا ‪،‬‬\n                    ‫املدعــى عليــه بالواليــة أنكــر أن يكــون يف عقــل ابنــه خل ـ ً‬\n      ‫وبعــد االطــاع علــى صــك الواليــة وجــد يتضمــن إنهاء املنهي وهــو املدعى‬\n      ‫عليــه بالواليــة بطلــب الواليــة علــى ابنــه لكونــه مصــاب بحالــة التخلــف‬\n      ‫العقلــي ‪ ،‬أهــل اخلبــرة مــن األطبــاء قــرروا أن املولــى عليــه مصــاب بحالــة‬\n      ‫التخلــف العقلــي وهــو غيــر مــدرك ملــا يــدور حولــه وال يســتطيع إدارة‬\n      ‫شــؤونه بنفســه ويحتــاج إلــى ولــي ‪ ،‬مــا نــص عليــه الفقهــاء مــن أن اجلنــون‬\n      ‫عيــب يثبــت بــه اخليــار ‪ ،‬وأن اخليــار يثبــت بحــدوث العيــب بعــد العقــد ولــو‬\n      ‫بعــد الدخــول وأن الــزوج ال يرجــع باملهــر ‪ ،‬بقــاء الزوجــة جبــر ًا مــع زوجهــا‬\n      ‫وهــو علــى هــذه احلــال فيــه ضــرر ظاهــر عليهــا ولقولــه صلــى اهلل عليــه‬\n      ‫وآلــه وســلم (ال ضــرر وال ضــرار) ‪ ،‬لــذا مت احلكــم بفســخ نــكاح املدعيــة‬\n      ‫مــن زوجهــا بــا عــوض ‪ ،‬بعــرض احلكــم علــى الطرفــن قــررا القناعــة‬\n      ‫‪ ،‬مت رفــع احلكــم حملكمــة االســتئناف لتدقيقــه نظــر ًا حلــق القاصــر‬\n      ‫والتهميــش علــى عقــد النــكاح بذلــك بعــد اكتســاب احلكــم القطعيــة‬\n      ‫وجــرى إفهــام املدعيــة بــأن عليهــا العــدة الشــرعية‪ ،‬وأن ال تتــزوج حتــى‬\n      ‫يكتســب احلكــم القطعيــة ‪ ،‬بعــد رفــع احلكــم حملكمــة االســتئناف‬\n                                                                   ‫متــت املصادقــة عليــه ‪.‬‬\n\n\n\n\n‫‪331‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وآلــه وصحبــه أمــا‬\n‫العامــة مبحافظة القطيف‬  ‫ّ‬    ‫بعــد فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n‫وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة برقــم‬\n‫‪ 331132758‬يف ‪ 1433/6/16‬هـ يف يوم الثالثاء املوافق‪1433/7/1‬هـ‬\n‫افتتحــت اجللســة اخلاصــة بدعــوى (‪ )........‬ضــد (‪ )........‬وفيهــا حضــرت‬\n‫(‪ )........‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم ‪ .........‬برفقــة‬\n‫املعــرف بهــا أخوهــا (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم (‪ )........‬ولــم يحضــر املدعــى عليــه وال مــن ميثلــه ولــم يقــدم أي عــذر‬\n‫هــذا وقــد وردتنــا إفــادة قســم احملضريــن باحملكمة برقــم ‪331132758‬‬\n‫يف ‪1433/6/19‬ه ـ املتضمنــة تبلــغ املدعــى عليــه لغيــر شــخصه ومســتلم‬\n‫التبليــغ ‪ ........‬أخــو املدعــى عليــه الســاكن معــه أ‪ .‬ه ـ ‪ .‬وقــررت املدعيــة‬\n‫بــأن املدعــى عليــه لــن يحضــر يف هــذا اليــوم وطلبــت رفــع اجللســة ليــوم‬\n‫آخــر فأجبتهــا لطلبهــا ورفعــت اجللســة مــن أجــل إعــادة إبــاغ املدعــى‬\n‫عليــه ويف جلســة أخــرى حضــرت املدعيــة برفقــة املعــرف بهــا أخوهــا ولــم‬\n‫يحضــر املدعــى عليــه وال مــن ميثلــه ولــم يقــدم أي عــذر وقــد وردتنــا إفــادة‬\n‫قســم احملضريــن باحملكمــة برقــم ‪ 331240531‬يف ‪1433/7/2‬ه ـ‬\n‫املتضمنــة تبلــغ املدعــى عليــه لغيــر شــخصه ومســتلم التبليــغ ‪...........‬‬\n‫والــد املدعــى عليــه الســاكن معــه أ‪ .‬ه ـ ‪ .‬وبســؤال املدعيــة عــن دعواهــا‬\n‫قالــت‪ :‬إن املدعــى عليــه زوجــي تزوجنــي أكثــر مــن خمســة عشــر ســنة‬\n‫تقريبـ ًا وقــد أجنبــت منــه ثالثــة أوالد وهــم كمــا يلــي‪ ........ -1 :‬املولــودة‬\n‫بتاريــخ ‪1418/3/7‬ه ـ ‪ ......-2‬املولــود بتاريــخ ‪1420/11/1‬هــ‪.......... -3 .‬‬\n\n                                                                                        ‫‪332‬‬\n\f      ‫املولــود بتاريــخ ‪1426/12/17‬ه ـ وقــد أصيــب بحــادث مــروري بتاريــخ‬\n      ‫‪1429/3/1‬ه ـ ‪ .‬ممــا أدى إلــى إصابتــه بإعاقــة عقليــة وجســمية وقــد‬\n      ‫صبــرت عليــه ولكنــي تعبــت ولــم أعــد أطيــق العيــش معــه لــذا أطلــب‬\n      ‫فســخ نكاحــي منــه هــذه دعــواي ‪ .‬هــذا ونظــر ًا لعــدم حضــور املدعــى‬\n      ‫عليــه رفعــت اجللســة مــن أجــل إعــادة إبالغــه عــن طريــق احملافظــة‬\n      ‫وإحضــاره أو مــن ينــوب عنــه بالقــوة ويف جلســة أخــرى حضــرت املدعيــة‬\n      ‫برفقــة والدهــا املعــرف بهــا ‪ ........‬ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪ ...........‬وحضــر حلضورهــا ‪ ........‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدني رقم ‪ ........‬الولي الشــرعي على املدعى عليه عبداللطيف‬\n      ‫مبوجــب صــك الواليــة الصــادر مــن هــذه احملكمــة برقــم ‪ 33431675‬يف‬\n      ‫‪1433/10/21‬ه ـ واملتضمــن إقامــة ‪ ..........‬والــد املدعــى عليــه وليـ ًا عليــه‬\n      ‫ال ‪ :‬ما ذكرته‬      ‫وبعــرض دعــوى املدعيــة علــى ولــي املدعى عليه أجــاب قائ ً‬\n      ‫املدعيــة يف دعواهــا صحيــح ســوى أنــه مصــاب بإعاقــة عقليــة والصحيــح‬\n      ‫أنــه مصــاب بإعاقــة جســمية وصعوبــة يف النطق ولكن إذا ســألته ســؤا ًال‬\n      ‫يجيــب إجابــة صحيحــة وال مانــع لــدي مبــا طلبتــه املدعيــة ‪ .‬هكذا أجاب‬\n      ‫‪ .‬ثــم طلبــت وثيقــة عقــد النــكاح فاســتعدت املدعيــة بإحضــاره يف اجللســة‬\n      ‫القادمــة ثــم رفعــت اجللســة ويف جلســة أخــرى حضــرت املدعيــة برفقــة‬\n      ‫ـاء علــى مــا‬\n                   ‫والدهــا وحضــر حلضورهــا املدعــى عليــه بالواليــة ‪ ............‬فبنـ ً‬\n      ‫تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليــه بالواليــة أنكــر أن‬\n      ‫ا أو عيبـ ًا ‪ ،‬وبعــد االطــاع علــى صــك الواليــة‬        ‫يكــون يف عقــل ابنــه خلـ ً‬\n      ‫واملتضمــن إنهــاء املنهــي وهــو املدعــى عليــه بالواليــة بطلــب الواليــة علــى‬\n      ‫ابنــه لكونــه مصــاب بحالــة التخلــف العقلــي ‪ .‬ومبــا أن أهــل اخلبــرة مــن‬\n      ‫األطبــاء قــرروا أن ‪...........‬املولــى عليــه مصــاب بحالــة التخلــف العقلــي‬\n\n\n‫‪333‬‬\n\f‫وهــو غيــر مــدرك ملــا يــدور حولــه وال يســتطيع إدارة شــؤونه بنفســه‬\n‫ويحتــاج إلــى ولــي ‪ .‬وملــا نــص عليــه الفقهــاء مــن أن اجلنــون عيــب يثبــت‬\n‫بــه اخليــار ‪ -‬انظــر كشــاف القنــاع ‪ - 405/11‬وملــا قــرروه أيض ـ ًا مــن‬\n‫ثبــوت اخليــار بحــدوث العيــب بعــد العقــد ولــو بعــد الدخــول وأن الــزوج‬\n‫ال يرجــع باملهــر ‪ -‬انظــر كشــاف القنــاع ‪ - 409/11‬وألن بقــاء الزوجــة‬\n‫جبــر ًا مــع زوجهــا وهــو علــى هــذه احلــال فيــه ضــرر ظاهــر عليهــا ولقولــه‬\n‫صلــى اهلل عليــه وآلــه وســلم (( ال ضــرر وال ضــرار )) لذلــك كلــه فقــد‬\n‫فســخت نــكاح املدعيــة ‪ ...........‬مــن زوجهــا ‪ ...........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ ...........‬مجان ـ ًا وبــه حكمــت وبعــرض‬\n‫احلكــم علــى الطرفــن قــررا القناعــة بــه عليــه فقــد قــررت رفــع احلكــم‬\n‫حملكمــة االســتئناف لتدقيقــه نظــر ًا حلــق القاصــر والتهميــش علــى عقــد‬\n‫النــكاح بذلــك بعــد اكتســاب احلكــم القطعيــة وأفهمــت املدعيــة بــأن‬\n‫عليهــا العــدة الشــرعية وهــي حيضــة واحــدة وأن ال تتــزوج حتــى يكتســب‬\n‫احلكــم القطعيــة ففهمــت ذلــك حــرر يف ‪1433/11/21‬ه ـ وصلــى اهلل‬\n                                 ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلــى آلــه‬\n‫ـاء‬\n‫وصحبــه أمــا بعــد يف يــوم الثالثــاء ‪1434/6/13‬ه ـ فتحــت اجللســة بنـ ً‬\n‫علــى ورود املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية مبوجــب‬\n‫كتــاب ســماحة رئيســها رقــم ‪ 34790604‬يف ‪1434/5/29‬ه ـ وبرفقهــا‬\n‫قــرار أصحــاب الفضيلــة قضــاة دائــرة األحــوال الشــخصية الثانيــة رقــم‬\n‫‪/34222009‬ش‪ 2/‬يف ‪1434/5/26‬ه ـ املتضمــن نــص احلاجــة منــه‪:‬‬\n‫بدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة لوحــظ أن املعاملــة لــم‬\n‫يرفــق بهــا صــورة مصدقــة مــن واليــة ‪ .......‬علــى ابنــه املدعــى عليــه ‪........‬‬\n\n\n                                                                                         ‫‪334‬‬\n\f      ‫والبــد مــن ذلــك فعلــى فضيلتــه مالحظــة مــا أشــير إليــه وإحلاق مــا يجد يف‬\n      ‫الصــك وضبطــه وســجله ومــن ثــم إعــادة املعاملــة إلكمــال ال زمهــا واهلل‬\n      ‫املوفــق قاضــي اســتئناف ختمــه وتوقيعــه ‪ ..........‬قاضــي اســتئناف ختمــه‬\n      ‫وتوقيعــه ‪ .........‬رئيــس الدائــرة ختمــه وتوقيعــه ‪ .......‬أ‪.‬ه ـ ‪ .‬عليــه أجيــب‬\n      ‫أصحــاب الفضيلــة بأنــه مت إرفــاق املطلــوب شــاكر ًا ألصحــاب الفضيلــة‬\n      ‫مــا تفضلــوا علــي وقــررت إعــادة كامــل املعاملــة حملكمــة االســتئناف‬\n           ‫لتدقيقــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى نبينــا محمــد وعلى آلــه وصحبه‬\n      ‫ـاء علــى ورود‬‫أمــا بعــد يف يــوم الثالثــاء ‪1434/8/9‬ه ـ فتحــت اجللســة بنـ ً‬\n      ‫املعاملــة مــن محكمــة االســتئناف باملنطقــة الشــرقية بكتــاب ســماحة‬\n      ‫رئيسها رقم ‪ 34/1567036‬يف ‪1434/7/22‬هـ املرفق به قرار أصحاب‬\n      ‫الفضيلــة قضــاة دائــرة األحــوال الشــخصية الثانيــة رقــم ‪ 34269840‬يف‬\n      ‫‪1434/7/16‬ه ـ املتضمــن نــص احلاجــة منــه‪ ( :‬باالطــاع علــى مــا أجــاب‬\n      ‫بــه فضيلــة القاضــي وأحلقــه بالصــك جواب ـ ًا علــى قرارنــا الســابق رقــم‬\n      ‫‪/34222009‬ش‪/2‬ب يف ‪1434/5/26‬ه ـ لوحــظ أن فضيلــة القاضــي لم‬\n      ‫يــدون قــرار محكمــة االســتئناف املتضمــن املالحظــة علــى فضيلتــه ولــم‬\n      ‫يجــب عليهــا فعلــى فضيلتــه مالحظــة مــا أشــير إليــه وإحلــاق مــا يجــد يف‬\n      ‫الصــك وضبطــه وســجله ومــن ثــم إعــادة املعاملــة إلكمــال الزمهــا واهلل‬\n      ‫املوفــق ) ‪ .‬أ ه ـ ‪ .‬قاضــي اســتئناف ‪........‬ختمــه وتوقيعــه قاضــي اســتئناف‬\n      ‫‪ ...........‬ختمــه وتوقيعــه رئيــس الدائــرة ‪ ........‬ختمــه وتوقيعــه عليــه أجيــب‬\n      ‫أصحــاب الفضيلــة بأنــه مت إكمــال املطلــوب يف قرارهــم املشــار إليــه‬\n      ‫أعــاه ‪ .‬شــاكر ًا ألصحــاب الفضيلــة مــا تفضلــوا بــه وأســأل اهلل لــي‬\n      ‫ولهــم معرفــة احلــق واتباعــه حــرر يف ‪1434/8/9‬ه ـ ‪ ،‬وصلــى اهلل علــى‬\n\n\n‫‪335‬‬\n\f                                   ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة دائ ــرة األحــوال‬\n‫الشــخصية الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى‬\n‫املعاملــة املقيــدة لــدى احملكمــة برقــم ‪/34/2303389‬ش‪ 2‬وتاريــخ‬\n‫‪1434/10/13‬ه ـ والــواردة مــن فضيلــة رئيــس احملكمــة العامــة‬\n‫مبحافظــة القطيــف برقــم ‪ 34/5167036‬وتاريــخ ‪1434/9/23‬ه ـ‬\n‫املرفــق بهــا الصــك الصــادر مــن فضيلــة القاضــي بها الشــيخ ‪ ......‬املســجل‬\n‫برقــم ‪ 3457561‬وتاريــخ ‪1434/3/8‬ه ـ اخلــاص بدعــوى ‪ ..........‬ضــد‬\n‫‪ ...........‬يف قضيــة فســخ نــكاح وباالطــاع علــى مــا أجــاب بــه فضيلــة‬\n‫القاضــي وأحلقــه بالصــك جواب ـ ًا علــى قــراري الدائــرة الســابقني رقــم‬\n‫‪/34222009‬ش‪/2‬ب يف ‪1434/5/26‬ه ـ ورقــم ‪/34269840‬ش‪/2‬ب‬\n‫يف ‪1434/7/16‬ه ـ قررنــا أنــه لــم يظهــر مــا يوجــب النقــض بعــد اإلجــراء‬\n‫األخيــر‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‬\n                                                    ‫حــرر يف ‪1435/1/22‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪336‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":330,"source_page_end":336,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"18053af6b69d91d739514f21822633ef70dd8104f84443ad0472b6fbd375fbe1","normalized_text_hash":"b58da8e1892ce5acddabe29872b397a36daca3a1b926c5e840764d70c260242b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p330-3457561"},{"id":"b363bd52-8bc5-5d7d-80c2-cb8c4239c588","document_type":"judgment","category":"judicial","subcategory":"general","title":"خلع -مطالبة الزوجة باخللع مقابل رد املهر -امتناع الزوج من املخالعة -املطالبة بفسخ النكاح -بقاء الزوجة معلقة مع وجود الشقاق من الضرر الواجب إزالته شرع ا -من وجب عليه شيء وامتنع عن أدائه استوفاه عنه احلاكم -احلكم بفسخ النكاح على عوض -ال عبرة بالطاق بعد صدور احلكم بالفسخ -إفهام الطرفن باآلثار املترتبة على فسخ النكاح .","document_number":"33422293","case_number":"33431124","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1432/10/10","year":"1434","subject":"خلع -مطالبة الزوجة باخللع مقابل رد املهر -امتناع الزوج من املخالعة -املطالبة بفسخ النكاح -بقاء الزوجة معلقة مع وجود الشقاق من الضرر الواجب إزالته شرع ا -من وجب عليه شيء وامتنع عن أدائه استوفاه عنه احلاكم -احلكم بفسخ النكاح على عوض -ال عبرة بالطاق بعد صدور احلكم بالفسخ -إفهام الطرفن باآلثار املترتبة على فسخ النكاح .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1432/10/10 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33422293 :‬‬\n                          ‫َر ْق ُم الدعوى‪33431124 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3429503‬تاريخه‪1434/2/4 :‬هـ‬\n\n\n       ‫خلــع ‪ -‬مطالبــة الزوجــة باخللــع مقابــل رد املهــر ‪ -‬امتنــاع الــزوج مــن‬\n       ‫املخالعــة ‪ -‬املطالبــة بفســخ النــكاح ‪ -‬بقــاء الزوجــة معلقــة مــع وجــود‬\n       ‫الشــقاق مــن الضــرر الواجــب إزالتــه شــرع ًا ‪ -‬مــن وجــب عليــه شــيء‬\n       ‫وامتنــع عــن أدائــه اســتوفاه عنــه احلاكــم ‪ -‬احلكــم بفســخ النــكاح‬\n       ‫علــى عــوض ‪ -‬ال عبــرة بالطــاق بعــد صــدور احلكــم بالفســخ ‪ -‬إفهــام‬\n                                 ‫الطرفــن باآلثــار املترتبــة علــى فســخ النــكاح ‪.‬‬\n\n\n\n       ‫‪ -1‬قولــه تعالــى (فــإن خفتــم شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه‬\n                      ‫وحكمــا مــن أهلهــا إن يريــدا إصالحــا يوفــق اهلل بينهمــا)‪.‬‬\n                            ‫‪ -2‬قوله تعالى (وإن يتفرقا يغن اهلل كال من سعته)‪.‬‬\n                                  ‫‪ -3‬قوله تعالى (وال تضاروهن لتضيقوا عليهن)‪.‬‬\n                                ‫‪ -4‬قوله صلى اهلل عليه وسلم (ال ضرر وال ضرار)‪.‬‬\n       ‫‪ -5‬قولــه صلــى اهلل عليــه وســلم يف قصــة ثابــت بــن قيــس (خــذ احلديقــة‬\n                                                   ‫وطلقهــا تطليقــة) رواه البخاري‪.‬‬\n                            ‫‪ -6‬املادة ‪ 176‬واملادة ‪ 178‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n       ‫ادعــت املدعيــة علــى املدعــى عليــه بأنــه قــد تزوجهــا ودخــل بهــا الدخــول‬\n       ‫الشــرعي علــى صــداق قــدره ســتون ألــف ريــال وقــد حصــل بينهمــا نــزاع‬\n‫‪337‬‬\n\f‫ذهبــت علــى إثــره إلــى بيــت أهلهــا منــذ شــهر شــعبان ‪1429‬ه ـ وحتــى‬\n‫هــذا اليــوم وقــد كرهتــه وال تطيــق العيــش معــه وتطلــب اخللــع منــه ورد‬\n‫مهــره لــه هكــذا ادعــت ‪ ،‬أجــاب املدعــى عليــه باملصادقــة علــى الــزواج‬\n‫والدخــول بهــا وأنكــر وجــود نــزاع بينهمــا وأن ســبب خروجهــا مــن‬\n‫البيــت هــو زواجــه بثانيــة ويرفــض اخللــع ويطلــب رجوعهــا لبيــت الزوجيــة‬\n‫‪ ،‬جــرى عــرض الصلــح علــى الطرفــن لكــن املدعيــة كرهــت املدعــى‬\n‫عليــه ورفضــت الرجــوع معــه ‪ ،‬اســتعد املدعــى عليــه باخللــع مقابــل تنــازل‬\n‫املدعيــة عــن احلضانــة ورفضــت املدعيــة ذلــك ‪ ،‬أقــر املدعــى عليــه ببقــاء‬\n‫املدعيــة ببيــت أهلهــا أربــع ســنوات ‪ ،‬ولقولــه تعالــى (فــإن خفتــم شــقاق‬\n‫بينهمــا فابعثــوا حكمــا مــن أهلــه وحكمــا مــن أهلهــا إن يريــدا إصالحــا‬\n‫يوفــق اهلل بينهمــا ) فاختــار كل واحــد منهمــا حكم ـ ًا لــه واســتعدا‬\n‫بإحضــار احلكمــن يف اجللســة القادمــة ‪ ،‬حضــر حكــم الزوجــة ولــم‬\n‫يحضــر حكــم الــزوج ‪ ،‬جــرى محاولــة الصلــح بينهمــا ولــم يصطلحــا ‪،‬‬\n‫طلــب مــن املدعــى عليــه طــاق زوجتــه أو مخالعتهــا بعــوض وتذكيــره‬\n‫بقــول اهلل جــل وعــا (وإن يتفرقــا يغــن اهلل كال مــن ســعته ) فرفــض‬\n‫ذلــك ‪ ،‬ولتعــذر الصلــح بــن الطرفــن وإلقــرار املدعــى عليــه ببقــاء زوجتــه‬\n‫أربــع ســنوات خــارج بيتــه وحيــث اســتعدت املدعيــة بدفــع كامــل املهــر‬\n‫وقــدره ســتون ألــف ريــال ‪ ،‬وألن بقــاء الزوجــة هــذه الفتــرة فيــه ضــرر‬\n‫عليهــا ولقولــه تعالــى (وال تضاروهــن لتضيقــوا عليهــن ) ولقولــه صلــى‬\n‫اهلل عليــه وســلم (ال ضــرر وال ضرار)وقــد شــرع رفــع الضــرر بالفرقــة‬\n‫بــن الزوجــن وألن الشــقاق حاصــل بينهمــا ممــا تعــذر التحكيــم بــن‬\n‫الطرفــن ولقولــه صلــى اهلل عليــه وســلم يف قصــة ثابــت بــن قيــس (خــذ‬\n‫احلديقــة وطلقهــا تطليقــة) رواه البخــاري وألن الــزوج امتنــع مــن الطــاق‬\n\n\n                                                                                   ‫‪338‬‬\n\f      ‫وألن مــن وجــب عليــه شــيء وامتنــع عــن أدائــه اســتوفاه عنــه احلاكــم ‪،‬‬\n      ‫ملــا تقــدم جــرى فســخ نــكاح املدعيــة مــن زوجهــا املدعــى عليــه علــى مبلــغ‬\n      ‫وقــدره ســتون ألــف ريــال تســلمه املدعيــة للمدعــى عليــه ‪ ،‬إفهــام املدعــى‬\n      ‫عليــه بــأن زوجتــه قــد بانــت منــه بينونــة صغــرى ال حتــل لــه إال بعقــد‬\n      ‫جديــد ومهــر جديــد كمــا أفهمــت املدعيــة بــأن ال تســتقبل اخلطــاب‬\n      ‫إال بعــد اكتســاب احلكــم القطعيــة وانتهــاء العــدة الشــرعية ‪ ،‬قنعــت‬\n      ‫املدعيــة باحلكــم واعتــرض املدعــى عليــه ‪ ،‬قــدم املدعــى عليــه يف اليــوم‬\n      ‫التالــي للحكــم ورقــة إقــرار بتطليقــه زوجتــه ‪ ،‬أفهمــه حاكــم القضيــة‬\n      ‫بــأن إقــراره بالطــاق ال يؤثــر علــى ماحكــم بــه ‪ ،‬صــدق احلكــم مــن‬\n         ‫دائــرة األحــوال الشــخصية األولــى مبحكمــة االســتئناف بالريــاض ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا (‪ )........‬القاضــي القائــم بالعمــل يف‬\n      ‫املكتــب القضائــي احلــادي والثالثــن باحملكمــة العامــة بالريــاض بنــاء‬\n      ‫علــى تكليــف فضيلــة رئيــس احملكمــة املســاعد رقــم ‪ 331421333‬يف‬\n      ‫‪1433/08/21‬ه ـ وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة العامــة بالريــاض (‪ )........‬املســاعد برقــم ‪33431124‬‬\n      ‫وتاريــخ ‪ 1433/06/29‬ه ـ املقيــدة باحملكمــة برقــم ‪33748263‬‬\n      ‫وتاريــخ ‪ 1433/04/20‬ه ـ ففــي يــوم الســبت املوافــق‪1433/08/24‬‬\n      ‫ه ـ افتتحــت اجللســة وفيهــا حضــرت (‪ )........‬ســعودية اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪ )........‬واملعــرف بهــا مــن قبــل أخيهــا احلاضــر معهــا‬\n      ‫(‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ )........‬كمــا‬\n      ‫حضــر (‪ )........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪)........‬‬\n‫‪339‬‬\n\f‫وكيلهــا الشــرعي مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل عرقــة‬\n‫رقــم ‪ 511002005798‬وتاريــخ ‪1431/12/24‬ه ـ واملتضمــن لــه (حــق‬\n‫املطالبــة واملرافعــة واملدافعــة واملخاصمــة وإقامــة الدعــاوى وســماع‬\n‫الدعــاوى والــرد عليهــا واإلقــرار واإلنــكار والصلــح وطلــب قبــول‬\n‫احلكــم واالعتــراض عليــه وطلــب متييــزه ) كمــا حضــر ‪ ...‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬وقــرر قائــا إننــي وكيــل عــن ‪...‬‬\n‫وبســؤاله عــن أســاس الوكالــة أجــاب قائــا ســأحضرها اجللســة القادمة‬\n‫ويف يــوم األربعــاء املوافــق ‪ 1433/08/28‬ه ـ افتتحــت اجللســة وفيهــا‬\n‫حضــرت املدعيــة ومعرفهــا ووكيلهــا احلاضــرون يف اجللســة الســابقة‬\n‫كمــا حضــر املدعــى عليــه‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ...‬وبســؤال املدعيــة عــن دعواهــا أجابــت قائلــة إن املدعــى عليــه‬\n‫احلاضــر هــو زوجــي وقــد تزوجنــي ودخــل بــي الدخــول الشــرعي مبوجــب‬\n‫العقــد الصــادر مــن محكمــة الضمــان و األنكحــة بالريــاض برقــم ‪26‬‬\n‫وتاريــخ ‪1417/5/1‬ه ـ علــى مهــر وقــدره ســتون ألــف ريــال واجنبــت لــه‬\n‫علــى فــراش الزوجيــة ثالثــة أوالد وهــم ‪ ...‬املولــودة يف ‪1419/2/11‬ه ـ‬\n‫و‪ ...‬املولــود يف ‪1422/4/24‬ه ـ و‪ ...‬املولــود يف ‪1425/4/10‬ه ـ وقــد‬\n‫حصــل بيننــا نــزاع ذهبــت علــى إثــره إلــى بيــت أهلــي منــذ شــهر شــعبان‬\n‫‪1429‬ه ـ وحتــى هــذا اليــوم وقــد كرهتــه وال أطيــق العيــش معــه وأطلــب‬\n‫اخللــع منــه ورد مهــره لــه هكــذا ادعــت وبعــرض ذلــك علــى املدعــى عليــه‬\n‫أجــاب قائــا مــا ذكرتــه املدعيــة مــن زواجــي بهــا ودخولــي بهــا الدخــول‬\n‫الشــرعي وإجنابهــا لــي األوالد الثالثــة فكلــه صحيــح وأمــا النــزاع فــا‬\n‫صحــة لــه وســبب خروجهــا مــن البيــت هــو زواجــي بثانيــة وأنــا أرفــض‬\n‫اخللــع وأطلــب رجوعهــا لبيــت الزوجيــة هكــذا أجــاب هــذا كمــا جــرى‬\n\n\n                                                                                    ‫‪340‬‬\n\f      ‫اإلطــاع علــى أســاس عقــد النــكاح فوجدتــه كمــا ذكــرت املدعيــة‬\n      ‫وبعــرض الصلــح علــى الطرفــن أبــدى الــزوج اســتعداده للصلــح وقبولــه‬\n      ‫رجــوع الزوجــة والعفــو عمــا ســلف وبعــرض ذلــك علــى املدعيــة أجابــت‬\n      ‫قائلــة أنــا ال أقبــل بالصلــح وأرفــض الرجــوع إليــه وقــد كرهتــه وليــس‬\n      ‫لــدي أكثــر مــن ذلــك وأطلــب اخللــع منــه هكــذا أجابــت وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه أجــاب قائــا إننــي أعــرض عليهــا بقائهــا علــى ذمتــي‬\n      ‫مقابــل ســكنها هــي وأوالدي يف بيــت خــاص لهــم هكــذا أجاب وبعرض‬\n      ‫ذلــك علــى املدعيــة أجابــت قائلــة غيــر مســتعدة لذلــك هكــذا أجابــت‬\n      ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائــا إننــي مســتعد لقبــول‬\n      ‫اخللــع مقابــل تنازلهــا عــن حضانــة األوالد وبعــرض ذلــك علــى املدعيــة‬\n      ‫أجابــت قائلــة ليــس لــدي زيــادة علــى مــا ذكــرت وأطلــب اخللــع منــه وال‬\n      ‫أوافــق علــى جعــل حضانــة األوالد عوضــا علــى اخللــع هكــذا أجابــت‬\n      ‫وبســؤال املدعــى عليــه كــم مكثــت عنــد أهلهــا فقــال إنهــا مكثــت‬\n      ‫أربــع ســنوات هكــذا أجــاب فبنــاء علــى ذلــك ولقولــه تعالــى (فــإن خفتــم‬\n      ‫شــقاق بينهمــا فابعثــوا حكمــا مــن أهلــه وحكمــا مــن أهلهــا إن يريــدا‬\n      ‫إصالحــا يوفــق اهلل بينهمــا ) فقــد ألزمــت الطرفــان بتحديــد حكمــن‬\n      ‫مــن طرفهمــا فأجابــت املدعيــة قائلــه أطلــب أن يكــون احلكــم مــن‬\n      ‫طــريف العــم ‪ ...‬هكــذا أجابــت وبســؤال املدعــى عليــه عــن احلكــم مــن‬\n      ‫طرفــه أجــاب قائــا أطلــب أن يكــون احلكــم مــن طــريف ابــن اخلــال ‪...‬‬\n      ‫هكــذا أجــاب فاســتعد كل واحــد منهمــا بإحضــار احلكــم مــن طرفــه‬\n      ‫يف موعــد اجللســة القادمــة ويف جلســة أخــرى افتتحــت اجللســة الســاعة‬\n      ‫وفيهــا حضــر الطرفــان احلاضــران يف اجللســة الســابقة كمــا حضــر ‪...‬‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪ ...‬وقــرر قائــا إننــي مســتعد للتحكيــم‬\n\n\n‫‪341‬‬\n\f‫بــن الطرفــن ومحاولــة اإلصــاح هكــذا قــرر وبســؤال املدعــى عليــه‬\n‫عــن احلكــم مــن طرفــه أجــاب قائــا لــم يلتقــي الطرفــان ولــم أفهــم منــك‬\n‫أنــه يحضــر ملوعــد هــذه اجللســة هكــذا قــرر هــذا وقــد جــرى محاولــة‬\n‫اإلصــاح بــن الطرفــن وتذكيرهمــا بــاهلل جــل وعــا وحقــوق بعضهمــا‬\n‫لبعض ومداراة مصلحة أوالدهما وتقوى اهلل يف هذا الشهر الفضيل إال‬\n‫أن محاولــة اإلصــاح قــد تعــذرت كمــا قــرر احلكــم مــن طــرف املدعيــة‬\n‫قائــا إن اإلصــاح متعــذر بــن الطرفــن هكــذا قــرر هــذا وبســؤال‬\n‫املدعــى عليــه هــل قــام برفــع دعــوى انقيــاد وطاعــة علــى املدعيــة فأجــاب‬\n‫قائــا لــم يســبق لــي أن رفعــت دعــوى انقيــاد وطاعــة هكــذا أجــاب عنــد‬\n‫ذلــك طلبــت مــن املدعــى عليــه طــاق زوجتــه وتذكيــره بقــول اهلل جــل‬\n‫وعــا (وإن يتفرقــا يغــن اهلل كال مــن ســعته ) فرفــض ذلــك وبطلــب‬\n‫مخالعــة زوجتــه مقابــل العــوض أجــاب قائــا أرفــض ذلــك فبنــاء علــى‬\n‫مــا تقــدم مــن الدعــوى واإلجابــة ولتعــذر الصلــح بــن الطرفــن وإلقــرار‬\n‫املدعــى عليــه ببقــاء زوجتــه أربــع ســنوات خــارج بيتــه وإلصــرار الزوجــة‬\n‫علــى ذلــك وقــد رفــض الــزوج ذلــك ومبــا أن الزوجــة قــد خرجــت مــن بيتهــا‬\n‫منــذ عــام ‪ 1429‬وحيــث اســتعدت املدعيــة بدفــع كامــل املهــر وقــدره‬\n‫ســتون ألــف ريــال وألن بقــاء الزوجــة هــذه الفتــرة فيــه ضــرر عليهــا ولقولــه‬\n‫تعالــى (وال تضاروهــن لتضيقــوا عليهــن ) ولقولــه صلــى اهلل عليــه وســلم‬\n‫(ال ضــرر وال ضــرار) وقــد شــرع رفــع الضــرر بالفرقــة بــن الزوجــن وألن‬\n‫الشــقاق حاصــل بينهمــا ممــا تعــذر التحكيــم بني الطرفــن ولقوله صلى‬\n‫اهلل عليــه وســلم يف قصــة ثابــت بــن قيــس (خــذ احلديقــة وطلقهــا تطليقــة)‬\n‫رواه البخــاري وألن الــزوج امتنــع مــن الطــاق وألن مــن وجــب عليــه شــي‬\n‫وامتنــع عــن أدائــه اســتوفاه عنــه احلاكــم لذلــك كلــه فقــد فســخت‬\n\n\n                                                                                       ‫‪342‬‬\n\f      ‫نــكاح املدعيــة ‪ ...‬مــن زوجهــا ‪ ...‬علــى مبلــغ وقــدره ســتون ألــف ريــال‬\n      ‫تســلمه املدعيــة للمدعــى عليــه وبذلــك كلــه حكمــت وبعــرض احلكــم‬\n      ‫علــى الطرفــن قنعــت بــه املدعيــة ولــم يقنــع بــه املدعــى عليــه فأفهمته بأن‬\n      ‫لــه أن يتقــدم بالئحــة اعتراضيــة خــال ثالثــن يومــا مــن اســتالمه نســخة‬\n      ‫مــن احلكــم وإن لــم يتقــدم خاللهــا بالئحتــه االعتراضيــة ســقط حقــه يف‬\n      ‫االعتــراض ويكتســب احلكــم القطعيــة كمــا أفهــم املدعــى عليــه بــأن‬\n      ‫عليــه املراجعــة يــوم الســبت بتاريــخ ‪1433/09/09‬ه ـ الســتالم نســخة‬\n      ‫مــن احلكــم هــذا كمــا أفهمــت املدعــى عليــه بــأن زوجتــه ‪ ...‬ال حتــل‬\n      ‫لــه إال بعقــد جديــد ومهــر جديــد كمــا أفهمــت املدعيــة بــأن ال تســتقبل‬\n      ‫اخلطــاب إال بعــد اكتســاب احلكــم القطعيــة وانتهــاء العــدة الشــرعية‬\n      ‫هــذا وقــد ســلمت املدعيــة العــوض املذكــور مبوجــب الشــيك املصــدق‬\n      ‫باســم رئيــس احملكمــة مســحوبا علــى بنــك ‪ ...‬مببلــغ وقــدره ســتون ألــف‬\n      ‫ريــال برقــم ‪ 393697‬يف ‪1432/05/15‬ه ـ كمــا أفهمــت املدعــى عليــه‬\n      ‫باســتالمه وكان ذلــك بحضــور وشــهادة احلاضــر ‪ ...‬واملعــرف بهــا ‪ ...‬ويف‬\n      ‫جلســة أخــرى يف يــوم الســبت املوافــق ‪1433/9/9‬ه ـ افتتحــت اجللســة‬\n      ‫وفيهــا حضــرت املدعيــة ‪ ...‬واملعــرف بهــا مــن قبــل ‪ ...‬واحلكــم مــن طرفهــا‬\n      ‫عمهــا ‪ ...‬وقــد حضــر املدعــى عليــه صبــاح هــذا اليــوم وقــدم إقــرارا‬\n      ‫خطي ـ ًا متضمنــا ( اقــر لفضيلتكــم بأننــي طلقــت زوجتــي ‪ ... /‬طلقــة‬\n      ‫واحــدة رجعيــة شــرعية بقولــه لنــا أنتــي طالــق وهــي تســمع وقــد أخبــرت‬\n      ‫الشــهود وإخوانهــا بذلــك وســأزود مكتبكــم بنســخة مــن صــك الطــاق‬\n      ‫حــال صــدوره خــال يومــن وســأخبر إخوانهــا برقــم الصــك ليســتلموه‬\n      ‫مــع شــيك النفقــة مــن محكمــة األنكحــة واهلل املوفــق املقــر مبــا فيــه ‪...‬‬\n      ‫توقيــع) ولــم يســتلم نســخة مــن احلكــم عليــه فقــد جــرى إفهــام املدعــى‬\n\n\n‫‪343‬‬\n\f‫عليــه بأنــه ال تــزال مــدة االعتــراض ســارية وأنــه ســوف يعامــل مبقتضــى‬\n‫املــادة ‪ 176‬واملــادة ‪ 178‬مــن نظــام املرافعــات الشــرعية وأن إقــراره‬\n‫بالطــاق لــم يؤثــر علــى مــا حكمــت بــه كمــا مت إرفــاق اإلقــرار يف‬\n‫املعاملــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                             ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/09/09‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة األولــى لتمييــز‬\n‫قضايــا األحــوال الشــخصية واإلنهــاءات مبحكمــة االســتئناف بالرياض‬\n‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n‫برقــم ‪ 331793511‬وت ــاريخ ‪1434/1/11‬ه ـ املرفــق بهــا الصــك الصــادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ... /‬املســجل برقــم ‪ ...‬وتاريــخ‬\n‫‪1432/10/10‬ه ـ اخلــاص بدعــوى ‪ ... /‬ضــد ‪ ... /‬بالوكالــة عــن ‪ ...‬بشــأن‬\n‫طلــب املدعيــة اخللــع مــن املدعــى عليــه ‪ ،‬وقــد تضمــن الصــك حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك وصــورة ضبطــه‬\n‫وأوراق املعاملــة لــم يظهــر مــا يوجــب االعتــراض علــى مــا حكــم بــه‬\n‫فضيلتــه بالفســخ املــؤرخ يف ‪1433/9/9‬ه ـ واهلل املوفــق وصلــى اهلل علــى‬\n                                    ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪344‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":337,"source_page_end":344,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1cbb2668956cdb2a35f633e85c11ac243afed482461019129677422a8efbc710","normalized_text_hash":"c8c9f07b299c45ff54af80157b4e4670e1c92c09cd9cbcc5bfc202ce06ec5f5e","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p337-33422293"},{"id":"4424fecd-c6e4-556e-9eb9-9652a4c501c4","document_type":"judgment","category":"judicial","subcategory":"general","title":"فسخ نكاح بعد الدخول للضرر وسوء العشرة -للمدعية يف القضايا الزوجية إقامة دعواها يف بلد إقامتها -االستخالف لسماع جواب املدعى عليه -عدم حضور املدعى عليه رغم تبلغه يعد نكو ال عن اجلواب -احلكم بفسخ النكاح دون عوض -إفهام الطرفن باآلثار املترتبة على فسخ النكاح .","document_number":"34266092","case_number":"33464576","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بينبع وقد أبرزته لناظر القضية","circuit":"الدائرة اجلزائية الرابعة مبحكمة الاستئناف مبنطقة مكة املكرمة","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/11","year":"1434","subject":"فسخ نكاح بعد الدخول للضرر وسوء العشرة -للمدعية يف القضايا الزوجية إقامة دعواها يف بلد إقامتها -االستخالف لسماع جواب املدعى عليه -عدم حضور املدعى عليه رغم تبلغه يعد نكو ال عن اجلواب -احلكم بفسخ النكاح دون عوض -إفهام الطرفن باآلثار املترتبة على فسخ النكاح .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/7/11 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34266092 :‬‬\n                         ‫َر ْق ُم الدعوى‪33464576 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34355084‬تاريخه‪1434/11/10 :‬هـ‬\n\n\n      ‫فســخ نــكاح بعــد الدخــول للضــرر وســوء العشــرة ‪ -‬للمدعيــة يف القضايا‬\n      ‫الزوجيــة إقامــة دعواهــا يف بلــد إقامتهــا ‪ -‬االســتخالف لســماع جــواب‬\n      ‫املدعــى عليــه ‪ -‬عــدم حضــور املدعــى عليــه رغــم تبلغــه يعــد نكــو ًال عــن‬\n      ‫اجلــواب ‪ -‬احلكــم بفســخ النــكاح دون عــوض ‪ -‬إفهــام الطرفــن باآلثــار‬\n                                                         ‫املترتبــة علــى فســخ النــكاح ‪.‬‬\n\n\n\n\n                        ‫‪ .1‬قوله صلى اهلل عليه وسلم‪( :‬ال ضرر وال ضرار) ‪.‬‬\n         ‫‪ .2‬املادة ‪/10/34‬ه من نظام املرافعات الشرعية والئحته التنفيذية ‪.‬‬\n                    ‫‪ .3‬املادة ‪ 4/176‬واملادة ‪178‬من نظام املرافعات الشرعية ‪.‬‬\n\n\n\n\n      ‫ادعــت املدعيــة ضــد املدعــى عليــه الغائــب بأنه تزوجهــا بوالية أخيها على‬\n      ‫مهــر وقــدره (‪ )15000‬خمســة عشــر ألــف ريــال ســعودي مســتلمة مقدمــا‬\n      ‫واملؤخــر (‪ )20000‬عشــرون ألــف ريــال ودخــل بهــا وأنــه قــد هجرهــا منــذ‬\n      ‫أكثــر مــن ســنتني وتركهــا بــا نفقــة وهــو ال يقيــم الصــاة ويضربهــا‬\n      ‫وســاءت العشــرة بينهمــا وأنهــا تكرهــه وال تطيقــه وتطلــب احلكــم لهــا‬\n      ‫بفســخ نكاحهــا منــه هكــذا ادعــت ‪ ،‬طلبــت االســتخالف يف ســماع‬\n      ‫جــواب املدعــى عليــه ألنــه يقيــم يف محافظــة ينبــع ‪ ،‬جــرى اســتخالف‬\n\n‫‪345‬‬\n\f‫محكمــة ينبــع لســماع إجابــة الــزوج بنــاء علــى املــادة ‪/10/34‬ه مــن‬\n‫نظــام املرافعــات الشــرعية ‪ ،‬ورد جــواب محكمــة ينبــع بأنــه مت إكمــال‬\n‫الــازم وبرفقــه جــواب املدعــى عليــه املتضمــن (املصادقــة علــى الــزواج‬\n‫والدخــول والصــداق وإنــكار مــا ســوى ذلــك ‪ ،‬وبعــرض ذلــك علــى‬\n‫املدعيــة أنكــرت جوابــه وأن الصحيــح مــا ذكرتــه فهــو قــد أخرجهــا‬\n‫وقــد قذفهــا وصــدر بحقــه القــرار الشــرعي الصــادر مــن احملكمــة‬\n‫واملتضمــن جلــد املدعــى عليــه ‪ 79‬تســعا وســبعني جلــدة بحضــور املدعيــة‬\n‫باحلــق اخلــاص ولديهــا تقريــر طبــي بأنــه قــد ضربهــا هكــذا أجابــت ‪ ،‬لــم‬\n‫يحضــر املدعــى عليــه رغــم تبلغــه ‪ -‬قدمــت املدعيــة بينــة القــرار الشــرعي‬\n‫الصــادر مــن احملكمــة العامــة بينبــع وقــد أبرزتــه لناظــر القضيــة ‪،‬‬\n‫فبنــاء علــى مــا تقــدم مــن دعــوى املدعيــة وحيــث لــم يحضــر املدعــى عليــه‬\n‫مــع تبلغــه ممــا يــدل علــى أنــه يقصــد الضــرر باملدعيــة وهــذا يعــد نكــوال‬\n‫منــه عــن اجلــواب واخلصومــة كمــا يظهــر أنــه لــم يطلبهــا طــوال الفتــرة‬\n‫املاضيــة لبيــت الطاعــة وهــذا إضــرار منــه باملدعيــة وملــا أن انقيادها لبيت‬\n‫الزوجيــة أمــر ال تتحقــق معــه مصلحــة النــكاح مــن املــودة والرحمــة بــن‬\n‫الزوجــن وخصوصــا يف هــذه احلــال كمــا أن املدعيــة قــد أقامــت بينتهــا‬\n‫املثبتــة لدعواهــا ولقولــه صلــى اهلل عليــه وســلم‪( :‬ال ضرر وال ضرار) ‪ ،‬ملا‬\n‫تقــدم جــرى فســخ نــكاح املدعيــة مــن املدعــى عليــه مجانــا بغيــر عــوض‬\n‫ألنــه متســبب يف طلبهــا الفرقــة ‪ ،‬ويعــد احلكــم يف حــق املدعــى عليــه‬\n‫غيابيـ ًا ‪ ،‬وســوف يتــم إبــاغ احملكــوم عليــه وفــق إجــراءات التبليــغ ملــا يف‬\n‫املــادة ‪ 4/176‬مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة ‪ ،‬إفهــام‬\n‫املدعيــة أن عليهــا العــدة ثالثــة قــروء تبــدأ مــن تاريــخ اليــوم وأال تتــزوج‬\n‫حتــى يكتســب احلكــم القطعيــة كمــا أن علــى الــزوج أن يفهــم أنهــا قــد‬\n\n\n                                                                                       ‫‪346‬‬\n\f      ‫بانــت منــه بينونــة صغــرى ال حتــل لــه إال بعقــد ومهــر جديديــن ‪ ،‬الكتابــة‬\n      ‫حملكمــة األحــوال الشــخصية للتهميــش علــى وثيقــة عقــد النــكاح بعــد‬\n      ‫اكتســاب احلكــم القطعيــة ‪ ،‬اعتــرض املدعــى عليــه بالئحــة ‪ ،‬صــدق‬\n      ‫احلكــم مــن دائــرة األحــوال الشــخصية الثانيــة مبحكمــة االســتئناف‬\n                                                        ‫مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده ‪ ،‬وبعــد‪ :‬فلــدي أنــا (‪ )........‬القاضــي يف احملكمــة‬\n      ‫العامــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪33464576‬‬\n      ‫وتاريــخ ‪1433/07/14‬ه ـ املقيــدة باحملكمــة برقــم ‪331225033‬‬\n      ‫وتاريــخ ‪ 1433/06/30‬ه ـ ففــي يــوم اإلثنني‪1434/01/05‬ه ـ افتتحــت‬\n      ‫اجللســة يف الســاعة العاشــرة والربــع وفيهــا حضــرت (‪ )........‬فلســطينية‬\n      ‫اجلنســية بوثيقــة مصريــة مســلمة الديانــة مبوجــب رخصــة اإلقامــة رقــم‬\n      ‫(‪ )........‬بهــا مــن قبــل أخيهــا الشــقيق (‪ )........‬فلســطيني اجلنســية مســلم‬\n      ‫الديانــة مبوجــب رخصــة اإلقامــة رقــم (‪ )........‬لســماع دعواهــا (‪)........‬‬\n      ‫بشــأن فســخ نــكاح وقــد أفــادت املدعيــة بــأن املدعــى عليــه زوجهــا يقيــم‬\n      ‫يف محافظــة ينبــع وبنــاء علــى املــادة ‪/10/34‬ه ـ مــن نظــام املرافعــات‬\n      ‫الشــرعية والئحتــه التنفيذيــة والتــي جتيــز ســماع الدعــاوى الزوجيــة يف‬\n      ‫بلــد الزوجــة فقــد قــررت ســماع الدعــوى وادعــت األولــى قائلــة إن املدعــى‬\n      ‫عليــه زوجــي عقــد علــي بتاريــخ ‪1430/06/15‬ه ـ بواليــة ‪ ......‬علــى مهــر‬\n      ‫وقــدره (‪ )15000‬خمســة عشــر ألــف ريــال ســعودي مســتلمة مقدمــا‬\n      ‫واملؤخــر (‪ )20000‬عشــرون ألــف ريــال وال شــروط بيننــا ودخــل بــي‬\n\n‫‪347‬‬\n\f‫بتاريــخ ‪1430/08/21‬ه ـ وأجنبــت منــه بنتــا اســمها ‪ ......‬وعمرهــا ســنتان‬\n‫وإن زوجــي قــد هجرنــي منــذ أكثــر مــن ســنتني وتركنــي بــا نفقــة وهــو‬\n‫ال يقيــم الصــاة وقــد ضربنــي وقــد ســاءت العشــرة بيننــا وأنــا أكرهــه‬\n‫وال أطيقــه أطلــب احلكــم لــي بفســخ نكاحــي منــه هكــذا ادعــت ثــم‬\n‫أضافــت قائلــة إن زوجــي يقيــم يف واليــة احملكمــة العامــة مبحافظــة‬\n‫ينبــع وهــو مقيــم إقامــة نظاميــة ويعمــل يف جامعــة طيبــة فــرع محافظــة‬\n‫ينبــع ورقــم هاتفــه النقــال األول ‪ ......‬والثانــي ‪ ......‬وأطلــب اســتخالف‬\n‫فضيلــة رئيــس احملكمــة العامــة بينبــع أو مــن ينيبــه مــن قضاتهــا يف‬\n‫ســماع إجابــة الــزوج هكــذا أضافــت لــذا قــررت الكتابــة لفضيلة رئيس‬\n‫احملكمــة العامــة مبحافظــة ينبــع الســتخالفه يف ســماع إجابــة الــزوج‬\n‫أو مــن ينيبــه مــن قضاتهــا وعليــه رفعــت اجللســة واختتمــت اجللســة ثــم‬\n‫يف يــوم الثالثاء‪1434/05/28‬ه ـ افتتحــت اجللســة يف الســاعة العاشــرة‬\n‫وفيهــا حضــرت ‪ ......‬هويتهــا ســابقا املعــرف بهــا مــن قبــل أخيهــا الشــقيق‬\n‫‪ ......‬هويتــه ســابقا وقــد متــت الكتابــة للمحكمــة العامــة مبحافظــة ينبــع‬\n‫ملــا ذكــر ســابقا باخلطــاب رقــم ‪ 3446543‬وتاريــخ ‪1434/01/11‬ه ـ‬\n‫فــوردت اإلفــادة باخلطــاب رقــم ‪ 34180932‬وتاريــخ ‪1434/05/14‬ه ـ من‬\n‫أنــه مت إكمــال الــازم ونــص الضبــط‪( :‬احلمــد هلل وحــده وبعــد فلــدي‬\n‫أنــا ‪ .......‬القاضــي يف احملكمــة بينبــع وبنــاء علــى املعاملــة احملالــة لنــا‬\n‫مــن فضيلــة رئيــس احملكمــة العامــة بينبع‪/‬املســاعد برقــم ‪3444015‬‬\n‫وتاريخ‪1434/01/25‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34180932‬وتاريــخ‬\n‫‪1434/01/20‬ه ـ املبنيــة علــى كتــاب االســتخالف الــوارد مــن فضيلــة‬\n‫رئيــس احملكمــة العامــة بجــدة برقــم ‪ 3446543‬يف ‪1434/01/11‬ه ـ‬\n                                  ‫ففــي يــوم اإلثنــن املوافــق ‪1434/05/13‬ه ـ‬\n\n\n                                                                                       ‫‪348‬‬\n\f      ‫افتتحــت اجللســة الســاعة ‪ 12:00‬وفيهــا حضــر ‪ .........‬أردنــي اجلنســية‬\n      ‫مبوجــب رخصــة اإلقامــة ‪.........‬وجــرى االطــاع علــى الدعــوى املقيــدة يف‬\n      ‫صــورة الضبــط املرفقــة بخطــاب االســتخالف املتضمنــة بعــد املقدمــة‬\n      ‫مــا نصــه‪ « :‬وفيهــا حضــرت ‪.........‬فلســطينية اجلنســية بوثيقــة مصريــة‬\n      ‫مســلمة الديانــة مبوجــب رخصــة اإلقامــة رقــم ‪.........‬املعــرف بهــا مــن قبــل‬\n      ‫أخيهــا الشــقيق ‪.........‬فلســطيني اجلنســية مســلم الديانــة مبوجــب رخصــة‬\n      ‫اإلقامــة رقــم‪ .........‬لســماع دعواهــا ‪.........‬بشــأن فســخ نــكاح وقــد‬\n      ‫أفــادت املدعيــة بــأن املدعــى عليــه زوجهــا يقيــم يف محافظــة ينبــع وبنــاء‬\n      ‫علــى املــادة ‪/10/34‬ه ـ مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذية‬\n      ‫والتــي جتيــز ســماع الدعــاوى الزوجيــة يف بلــد الزوجــة فقــد قــررت ســماع‬\n      ‫الدعــوى وادعــت األولــى قائلــة إن املدعــى عليــه زوجــي عقــد علــي بتاريــخ‬\n      ‫‪1430/06/15‬ه ـ بواليــة أخــي ‪.........‬علــى مهــر وقــدره (‪ )15000‬خمســة‬\n      ‫عشــر ألــف ريــال ســعودي مســتلمة مقدمــا واملؤخــر (‪ )20000‬عشــرون‬\n      ‫ألــف ريــال وال شــروط بيننــا ودخــل بــي بتاريــخ ‪1430/08/21‬ه ـ وأجنبت‬\n      ‫منه بنتا اسمها ‪.........‬وعمرها سنتان وإن زوجي قد هجرني منذ أكثر‬\n      ‫مــن ســنتني وتركنــي بــا نفقــة وهــو ال يقيــم الصــاة وقــد ضربنــي وقــد‬\n      ‫ســاءت العشــرة بيننــا وأنــا أكرهــه وال أطيقــه أطلــب احلكــم لــي بفســخ‬\n      ‫نكاحــي منــه» أ‪.‬ه ـ وبعــرض الدعــوى أعــاه علــى احلاضــر ‪.........‬أجــاب‬\n      ‫قائــا‪ :‬مــا ذكرتــه املدعيــة ‪.........‬مــن زواجــي بهــا بالتاريــخ املذكــور‬\n      ‫باملهــر املذكــور ودخولــي بهــا وإجنابهــا بنتــا منــي علــى فــراش الزوجيــة‬\n      ‫فصحيــح‪ ،‬ومــا ســوى ذلــك فغيــر صحيــح‪ ،‬فاســم البنــت ‪.........‬وليــس‬\n      ‫‪ ،.........‬ومــا ذكرتــه مــن هجرانــي لهــا فغيــر صحيــح فهــي هربــت مــن‬\n      ‫بيــت الزوجيــة يف ينبــع إلــى جــدة‪ ،‬وقــد أخــذت معهــا حــن خرجــت مــن‬\n\n\n‫‪349‬‬\n\f‫بيــت الزوجيــة مبلغــا مــن مالــي قــدره ســتة آالف ريــال ومــا ذكرتــه مــن‬\n‫أنــي ال أقيــم الصــاة فغيــر صحيــح فأنــا مــن احملافظــن علــى الصــاة‬\n‫ومســتعد بإحضــار مــن يزكينــي مــن أئمــة املســاجد‪ ،‬ولــم أخرجهــا قــط‬\n‫ولــم أســئ عشــرتها وأنــا راغــب بهــا ولســت مســتعدا بطالقهــا هكــذا‬\n‫أجــاب املدعــى عليــه‪ ،‬وقــررت إعــادة املعاملــة لفضيلــة حاكــم القضيــة‬\n‫مرفقــا بهــا صــورة مصدقــة مــن ضبــط االســتخالف وبــاهلل التوفيــق‪،‬‬\n‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف‬\n‫‪1434/05/13‬ه ـ مدعــى عليــه ‪.........‬توقيعــه كاتــب الضبــط ‪.........‬‬\n‫توقيعــه القاضــي يف احملكمــة العامــة بينيــع ‪.........‬توقيعــه) وبعــرض‬\n‫إجابــة املدعــى عليــه علــى املدعيــة أجابــت قائلــة مــا ذكــره غيــر صحيــح‬\n‫والصحيــح مــا ذكرتــه فهــو قــد أخرجنــي وأنــا لــم أخــرج مــن منزلــه ولــم‬\n‫آخــذ منــه أي مبلــغ مالــي وأنــا ال أرغــب فهــو قــد قذفنــي وصــدر بحقــه‬\n‫القــرار الشــرعي الصــادر مــن احملكمــة العامــة مبحافظــة ينبــع برقــم‬\n‫‪ 3457933‬والتاريخ‪1434/03/08‬ه ـ واملتضمــن جلــد املدعــى عليــه ‪79‬‬\n‫تســعا وســبعني جلــدة بحضــور املدعيــة باحلــق اخلــاص ولــدي تقريــر طبــي‬\n‫بأنــه قــد ضربنــي هكــذا أجابت ونظرا لتوجه الدعوى فقد قررت طلب‬\n‫املدعــى عليــه ورفعــت اجللســة لطلــب حضــور املدعــى عليــه أو مــن ميثلــه‬\n‫واختتمــت اجللســة ثــم يف يــوم األحــد املوافــق‪ 1434/07/02‬ه ـ افتتحــت‬\n‫اجللســة يف الســاعة الواحــدة وفيهــا حضــرت املدعيــة ‪.........‬املثبتــة هويتهــا‬\n‫ســابقا املعــرف بهــا مــن قبــل أخيهــا الشــقيق ‪.........‬املثبتــة هويتــه ســابقا‬\n‫لســماع دعواهــا ‪.........‬بشــأن دعــوى يف حكــم منقــوض فســخ نــكاح‪/‬‬\n‫غيــر مشــتركة وقــد مت طلــب املدعــى عليــه عــن طريــق قســم محضــري‬\n‫اخلصــوم باخلطــاب رقــم ‪ 341303636‬وتاريــخ ‪1434/05/28‬ه ـ ملــا ذكر‬\n\n\n                                                                                        ‫‪350‬‬\n\f      ‫ســابقا فتمــت الكتابــة مــن قبــل رئيــس احملكمــة العامــة مبحافظــة‬\n      ‫جــدة املســاعد باخلطــاب رقــم ‪ 341303636‬وتاريــخ ‪1434/06/04‬ه ـ‬\n      ‫للمحكمــة العامــة مبحافظــة ينبــع فــوردت اإلفــادة مــن القائــم بعمــل‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة ينبــع باخلطــاب رقــم ‪341303636‬‬\n      ‫وتاريــخ ‪1434/06/26‬ه ـ املقيــد يف احملكمــة برقــم ‪341303636‬‬\n      ‫وتاريــخ ‪1434/07/01‬ه ـ املتضمنــة عليــه نفيدكــم مت إجــراء الــازم‬\n      ‫حيــال إبــاغ املذكــور ا‪.‬ه ـ نقــل نصــا وباالطــاع علــى املعاملــة وجــد‬\n      ‫ان املدعــى عليــه قــد تبلــغ بنفســه ووقــع علــى أصــل ورقــة التبليــغ ولــم‬\n      ‫يحضــر املدعــى عليــه وال مــن ميثلــه وبســؤال املدعيــة ببينتهــا علــى دعواهــا‬\n      ‫أجابــت قائلــة بينتــي هــي القــرار الشــرعي الصــادر مــن احملكمــة العامــة‬\n      ‫مبحافظــة ينبــع ويحمــل الرقــم ‪ 457933‬والتاريــخ ‪1434/03/08‬ه ـ‬\n      ‫هكــذا أجابــت ورفعــت اجللســة للتأمــل واختتمــت اجللســة ثــم يف يــوم‬\n      ‫اإلثنــن ‪1434/07/10‬ه ـ افتتحــت اجللســة يف الســاعة الثانيــة والنصــف‬\n      ‫وفيهــا حضــرت املدعيــة أصالــة ‪.........‬املثبتــة هويتهــا ســابقا املعــرف بهــا‬\n      ‫مــن قبــل أخيهــا الشــقيق ‪.........‬املثبتــة هويتــه ســابقا لســماع دعواهــا علــى‬\n      ‫‪.........‬بشــأن فســخ نــكاح ولــم يحضــر املدعــى عليــه وال مــن ميثلــه وقــد‬\n      ‫قــررت املدعيــة قائلــة‪ :‬إن املدعــى عليــه قــد ضارنــي وشــوه ســمعتي وأنــا‬\n      ‫متضــررة مــن ذلــك كمــا أنــي يف منــزل أهلــي منــذ ثــاث ســنوات وأنــا‬\n      ‫مــن ذوات األقــراء وغيــر حامــل كمــا أن وثيقــة عقــد النــكاح أصلهــا‬\n      ‫مــع املدعــى عليــه كمــا أنــا قــد حصلــت علــى صــورة طبــق األصــل‬\n      ‫مــن محكمــة األحــوال الشــخصية مبحافظــة جــدة هكــذا قــررت‬\n      ‫وباالطــاع علــى صــورة مصدقــة طبــق األصــل مــن القــرار الشــرعي رقــم‬\n      ‫‪ 3457933‬وتاريــخ ‪1434/03/08‬ه ـ الصــادر مــن احملكمــة العامــة يف‬\n\n\n‫‪351‬‬\n\f‫محافظــة ينبــع ومصدقــة مــن القاضــي ناظــر القضيــة فضيلــة الشــيخ‬\n‫‪.........‬القاضــي باحملكمــة العامــة مبحافظــة ينبــع وجدتــه يتضمــن‬\n‫دعــوى عامــة مــن املدعــي العــام ودعــوى خاصــة مــن املدعيــة وتتضمــن‬\n‫دعــوى املدعــي العــام طلبــه احلكــم علــى املدعــى عليــه بعقوبــة تعزيريــة‬\n‫ملــا أن الفعــل الــذي أقــدم عليــه محــرم ومعاقــب عليــه شــرعا والــذي هــو‬\n‫أن املدعــى عليــه قــد أرســل رســائل للمدعيــة علــى جوالهــا وتتضمــن أنهــا‬\n‫خائنــة ولهــا عالقــة بشــيعي ‪.........‬وأنهــا ســاقطة وأنهــا كانــت تخــرج مــع‬\n‫أشــخاص خــال الثانويــة وأنهــا حاولــت قتــل خطيبهــا وأن التهمــة توجهت‬\n‫علــى املدعــى عليــه بأنــه أرســل لهــا رســائل تتضمــن التلفــظ علــى املدعيــة‬\n‫بألفــاظ فاحشــة وغيــر الئقــة وتتضمــن دعــوى املدعيــة طلبهــا بإقامــة حــد‬\n‫القــذف كمــا أن املدعــى عليــه قــد تلفــظ علــى املدعيــة أمــام فضيلــة‬\n‫ناظــر القضيــة قائــا لهــا أنتــي ‪.........‬وأخــوك احلاضــر معــك يقــود عليــك‬\n‫وقــد حكــم علــى املدعــى عليــه باجللــد ‪ 79‬تســعا وســبعني جلــدة دفعــة‬\n‫واحــدة علنــا بحضــور املدعيــة باحلــق اخلــاص وقــررت املدعيــة القناعــة‬\n‫بينمــا قــرر املدعــى عليــه اعتراضــه وقــد جــرى املوافقــة علــى احلكــم مــن‬\n‫الدائــرة اجلزائيــة الرابعــة مبحكمة االســتئناف مبنطقــة مكة املكرمة‬\n‫بالقــرار رقــم ‪ 34185231‬وتاريــخ ‪1434/04/10‬ه ـ ا‪.‬ه ـ نقــل نصــا كمــا‬\n‫أبــرزت املدعيــة صــورة طبــق األصــل مــن ضبــط عقــد النــكاح مــن‬\n‫محكمــة األحــوال الشــخصية مبحافظــة جــدة ويتضمــن العقــد للمدعــى‬\n‫عليــه علــى املدعيــة علــى مهــر وقــدره (‪ )15000‬خمســة عشــرة ألــف ريــال‬\n‫ســعودي مســلم و(‪)20000‬عشــرين ألــف ريــال ســعودي مؤخــر ا‪.‬ه ـ نقــل‬\n‫نصــا كمــا مت االطــاع علــى الصــك بالصــك رقــم ‪ 32130444‬وتاريــخ‬\n‫‪1432/06/13‬ه ـ مــن فضيلــة الشــيخ ‪.........‬القاضــي بهــذه احملكمــة‬\n\n\n                                                                                     ‫‪352‬‬\n\f      ‫واملتضمــن فســخ نــكاح املدعيــة مــن املدعــى عليــه واملنقــوض بالقــرار‬\n      ‫رقــم ‪ 33300277‬وتاريــخ ‪1433/06/16‬ه ـ مــن الدائــرة الثانيــة لألحــوال‬\n      ‫الشــخصية واألوقــاف والوصايــا والقصــار وبيــوت املــال مبحكمــة‬\n      ‫االســتئناف مبكــة املكرمــة فبنــاء علــى مــا تقــدم مــن دعــوى املدعيــة‬\n      ‫واملتضمنــة طلبهــا فســخ نكاحهــا مــن املدعــى عليــه لتضررهــا مــن‬\n      ‫البقــاء لديــه ألنــه يضربهــا ويســيء إليهــا وبنــاء علــى مــا ذكــره املدعــى‬\n      ‫عليــه لــدى القاضــي املســتخلف مــن عــدم موافقتــه علــى فســخ نكاحهــا‬\n      ‫وأنــه لــم يســيء عشــرتها ولــم يحضــر مــع تبلغــه ممــا يــدل علــى أنــه‬\n      ‫يقصــد الضــرر باملدعيــة وهــذا يعــد نكــوال منــه عــن اجلــواب واخلصومــة‬\n      ‫كمــا يظهــر أنــه لــم يطلبهــا طــوال الفتــرة املاضيــة لبيــت الطاعــة وهــذا‬\n      ‫إضــرار منــه باملدعيــة وملــا أن انقيادهــا لبيــت الزوجيــة أمــر ال تتحقــق‬\n      ‫معــه مصلحــة النــكاح مــن املــودة والرحمــة بــن الزوجــن وخصوصــا يف‬\n      ‫هــذه احلــال كمــا أن املدعيــة قــد أقامــت بنيتهــا املثبتــة لدعواهــا ولقولــه‬\n      ‫صلــى اهلل عليــه وســلم‪( :‬ال ضــرر والضــرار) فقــد فســخت نــكاح‬\n      ‫املدعيــة ‪.........‬مــن املدعــى عليــه ‪ ...‬مجانــا بغيــر عــوض ألنــه متســبب يف‬\n      ‫طلبهــا الفرقــة وبــه حكمــت ويعــد احلكــم يف حــق املدعــى عليــه غيابيــا‬\n      ‫وســوف يتــم إبــاغ احملكــوم عليــه وفــق إجــراءات التبليــغ ملــا يف املــادة‬\n      ‫‪ 4/176‬مــن نظــام املرافعــات الشــرعية والئحتــه التنفيذيــة ويبــدأ ميعــاد‬\n      ‫االعتــراض علــى احلكــم مــن تاريــخ التبليــغ وإذا لــم يقــدم املدعــى عليــه‬\n      ‫اعتراضــه خــال املــدة املقــررة نظامــا فيكتســب احلكــم القطعيــة وقفــا‬\n      ‫للمــادة (‪ )178‬مــن نظــام املرافعــات الشــرعية وأفهمــت املدعيــة أن عليهــا‬\n      ‫العــدة ثالثــة قــروء تبــدأ مــن تاريــخ اليــوم ألنهــا قــررت أنهــا مــن ذوات‬\n      ‫األقــراء وغيــر حامــل وأال تتــزوج حتــى يكتســب احلكــم القطعيــة كمــا‬\n\n\n‫‪353‬‬\n\f‫أن علــى الــزوج أن يفهــم أنهــا قــد بانــت منــه بينونــة صغــرى الحتــل لــه‬\n‫إال بعقــد ومهــر جديديــن كمــا قــررت الكتابــة حملكمــة األحــوال‬\n‫الشــخصية للتهميــش علــى وثيقــة عقــد النــكاح بعــد اكتســاب احلكــم‬\n‫القطعيــة جــرى النطــق باحلكــم يف يــوم اإلثنــن ‪1434/07/10‬ه ـ يف‬\n‫الســاعة الثانيــة والنصــف‪ ،‬واختتمــت اجللســة يف الســاعة الثالثــة‪ ،‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر‬\n                                                           ‫يف ‪1434/07/10‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد اإلثنــن ‪1434/08/22‬ه ـ افتتحــت اجللســة يف‬\n‫الســاعة التاســعة وخمــس وأربعــن دقيقــة وفيهــا حضــر املدعــى عليــه‬\n‫‪.........‬أردنــي اجلنســية مســلم الديانــة مبوجــب رخصــة اإلقامــة رقــم ‪.........‬‬\n‫وبعــرض احلكــم املرصــود نصــه علــى املدعــى عليــه أجــاب قائــا أنــا‬\n‫معتــرض علــى احلكــم وغيــر قانــع ومســتعد بتقــدمي الئحــة اعتراضيــة‬\n‫هكــذا أجــاب فجــرى إفهامــه بــأن لــه ثالثــن يومــا مــن تاريــخ اســتالمه‬\n‫الــذي هــو اليــوم لنســخة احلكــم وإذا فــات علــى ميعــاد ولــم يقــدم الئحتــه‬\n‫االعتراضيــة ســقط حقــه يف االعتــراض واكتســب احلكــم القطعيــة‬\n‫كمــا قــد جــرت الكتابــة للمحكمــة العامــة مبحافظــة ينبــع باخلطــاب‬\n‫رقــم ‪ 341718407‬وتاريــخ ‪1434/07/19‬ه ـ ملــا ذكــر ســابقا ولــم تردنــا‬\n‫اإلفادة حتى اآلن‪ ،‬واختتمت اجللسة ثم يف يوم اإلثنني ‪1434/08/22‬هـ‬\n‫افتتحــت اجللســة يف الســاعة الواحــدة والربــع وفيهــا حضــر املدعــى عليــه‬\n‫أصالــة ‪ .........‬املثبتــة هويتــه ســابقا وقــدم الئحتــه االعتراضيــة املقيــدة يف‬\n‫احملكمــة برقــم ‪ 342027984‬وتاريــخ ‪1434/08/22‬ه ـ واملكونــة مــن‬\n‫إحــدى وخمســن ورقــة ورفعــت اجللســة لدراســتها واختتمــت اجللســة ثــم‬\n‫يف يــوم األحــد ‪1434/09/05‬ه ـ افتتحــت اجللســة يف الســاعة العاشــرة‬\n\n\n                                                                                        ‫‪354‬‬\n\f      ‫والربــع وفيهــا حضــرت املدعيــة أصالــة ‪.........‬هويتهــا ســابقا كمــا حضــر‬\n      ‫حلضورهــا املدعــى عليــه أصالــة ‪.........‬املثبتــة هويتــه ســابقا وقــد وردتنــا‬\n      ‫اإلفــادة مــن فضيلــة رئيــس احملكمــة العامــة مبحافظــة ينبــع املســاعد‬\n      ‫باخلطــاب رقــم ‪ 341718407‬وتاريــخ ‪1434/08/28‬ه ـ واملتضمــن أنــه مت‬\n      ‫تســليم نســخة احلكــم للمدعــى عليــه بتاريــخ ‪1434/08/21‬ه ـ مما يعني‬\n      ‫أنــه قــد اســتلم مــرة أخــرى لدينــا بتاريــخ ‪1434/08/22‬ه ـ وكال املرتــن‬\n      ‫يف وقــت االعتــراض وباالطــاع علــى الالئحــة االعتراضيــة املقدمــة مــن‬\n      ‫املدعــى عليــه واملذكــور رقــم قيدهــا وتاريخــه أعــاه ودراســتها لــم أجــد‬\n      ‫بهــا مــا يؤثــر علــى مــا حكمــت بــه لــذا قــررت رفعهــا مــع كامــل املعاملــة‬\n      ‫والصــك وصــورة مصدقــة مــن الضبــط حملكمــة االســتئناف ‪ ،‬واختتمت‬\n      ‫اجللســة يف الســاعة العاشــرة والنصــف‪ ،‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل‬\n      ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪ .‬حــرر يف ‪1434/09/05‬ه ـ‬\n      ‫احلمــد هلل والصــاة والســام علــى مــن ال نبي بعــده ‪ ،‬وبعد فقد جرى منا‬\n      ‫نحــن قضــاة الدائــرة الثانيــة لألحــوال الشــخصية واألوقــاف والوصايــا‬\n      ‫والقصار وبيوت املال مبحكمة االســتئناف يف منطقة مكة املكرمة‬\n      ‫االطــاع علــى الصــك الصــادر مــن فضيلــة الشــيخ‪......... /‬القاضــي‬\n      ‫باحملكمــة العامــة بجــدة برقــم ‪ 34266092‬وتاريخ‪1434/7/11‬ه ـ‬\n      ‫املتضمــن دعــوى ‪.........‬ضــد ‪......... /‬وبدراســة الصــك وصــورة ضبطــه‬\n      ‫والالئحــة االعتراضيــة تقــرر باألكثريــة املوافقــة علــى احلكــم واهلل‬\n              ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى الــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪355‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"80f9241f-522e-5e5b-9c5b-24043d5934e7","source_page_start":345,"source_page_end":355,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e125c3394ad35fea8c07db7777fb13da3357be48ceff095f4ed27950e337e151","normalized_text_hash":"ee1a8ea7601a090ef62c3265e8a877b584ec3cec60ce1c13d25e534fff7834e5","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v10-p345-34266092"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
